QT_ISI(13,{"1649":["(\"Dan aku tidak membebaskan diriku) dari kesalahan-kesalahan (karena sesungguhnya nafsu itu) yaitu hawa nafsu (selalu menyuruh) banyak menyuruh (kepada kejahatan kecuali orang) lafal maa di sini bermakna man, yaitu orang atau diri (yang diberi rahmat oleh Rabbku) sehingga terpeliharalah ia dari kesalahan-kesalahan. (Sesungguhnya Rabbku Maha Pengampun lagi Maha Penyayang.\").",[["۞ وَمَآ","Dan tidak"],["أُبَرِّئُ","aku bebaskan"],["نَفْسِىٓ ۚ","diri sendiri"],["إِنَّ","Sesungguhnya"],["ٱلنَّفْسَ","jiwa"],["لَأَمَّارَةٌۢ","(adalah) suruhan tertentu"],["بِٱلسُّوٓءِ","daripada kejahatan"],["إِلَّا","melainkan"],["مَا","[bahawa]"],["رَحِمَ","mengurniakan Rahmat"],["رَبِّىٓ ۚ","Tuhanku"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1650":["(Dan raja berkata, \"Bawalah Yusuf kepadaku, agar aku memilih dia sebagai orang yang dekat kepadaku.\") artinya aku akan jadikan ia sebagai orang yang paling kupercayai tanpa tandingan. Kemudian utusan sang raja datang kepada Nabi Yusuf seraya berkata, \"Turutilah kemauan sang raja!\" Maka Nabi Yusuf bangkit dan berpamit kepada semua penghuni penjara, kemudian ia pun berdoa bagi mereka. Setelah itu Nabi Yusuf mandi dan memakai pakaian yang bagus, lalu barulah ia menemui sang raja. (Maka tatkala raja telah bercakap-cakap dengan dia, dia berkata) kepadanya (\"Sesungguhnya kamu mulai hari ini menjadi orang yang berkedudukan tinggi lagi dipercayai pada sisi kami.\") artinya mulai hari ini engkau menjadi orang yang berkedudukan tinggi dan sangat dipercaya terhadap urusan-urusan kami. Lalu bagaimana pendapatmu apakah yang harus kami lakukan sekarang? Nabi Yusuf berkata kepadanya, \"Kumpulkanlah semua bibit-bibit, kemudian mari kita tanamkan dengan secara massal pada tahun-tahun yang subur sekarang ini. Simpanlah hasilnya pada bulir-bulirnya. Kelak akan datang orang-orang menitipkan hasil panennya kepadamu.\" Maka sang raja berkata, \"Lalu siapakah yang akan mengurusi dan menangani hal ini untuk membantuku?\"",[["وَقَالَ","Dan berkata"],["ٱلْمَلِكُ","raja"],["ٱئْتُونِى","Bawa dia kepada aku"],["بِهِۦٓ","Bawa dia kepada aku"],["أَسْتَخْلِصْهُ","Aku akan pilih dia"],["لِنَفْسِى ۖ","untuk diri aku sendiri"],["فَلَمَّا","Kemudian apabila"],["كَلَّمَهُۥ","dia bercakap dengannya"],["قَالَ","dia berkata"],["إِنَّكَ","Sesungguhnya kamu"],["ٱلْيَوْمَ","(adalah) hari ini"],["لَدَيْنَا","dengan kami"],["مَكِينٌ","mantap"],["أَمِينٌۭ","(dan) dipercayai"]]],"1651":["(Berkatalah ia) Nabi Yusuf (\"Jadikanlah aku bendaharawan negeri ini,) yakni negeri Mesir (sesungguhnya aku adalah orang yang pandai menjaga lagi berpengetahuan.\") orang yang mempunyai keahlian dalam hal perbendaharaan. Menurut suatu pendapat ditakwilkan, bahwa Nabi Yusuf pandai dalam hal menulis dan menghitung.",[["قَالَ","Dia berkata"],["ٱجْعَلْنِى","lantik aku"],["عَلَىٰ","atas"],["خَزَآئِنِ","(the) perbendaharaan"],["ٱلْأَرْضِ ۖ","(dari) tanah itu"],["إِنِّى","Sesungguhnya aku"],["حَفِيظٌ","(akan menjadi) penjaga"],["عَلِيمٌۭ","mengetahui"]]],"1652":["(Dan demikianlah) sebagaimana Kami berikan nikmat kepada Yusuf, yaitu dibebaskan dari penjara (Kami memberi kedudukan kepada Yusuf di negeri) Mesir (pergi) ia dapat bepergian (menuju ke mana saja ia kehendaki di bumi Mesir) yang pada sebelumnya ia hidup dalam kesempitan dan dalam sekapan tahanan. Menurut suatu riwayat dikisahkan bahwa sang raja memberinya mahkota dan cincin kebesaran kemudian sang raja memecat Al-Aziz lalu mengangkat Yusuf menggantikan kedudukannya. Tidak lama kemudian Al-Aziz wafat lalu Yusuf menikahi istrinya yang bernama Zulaikha. Ternyata setelah Nabi Yusuf menggaulinya, Zulaikha masih perawan; Nabi Yusuf mempunyai dua orang putra dari Zulaikha ini. Nabi Yusuf mampu menegakkan keadilan di negeri Mesir dan semua orang menaatinya.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["مَكَّنَّا","Kami menubuhkan"],["لِيُوسُفَ","[kepada] Yusuf"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["يَتَبَوَّأُ","untuk menyelesaikan"],["مِنْهَا","di dalamnya"],["حَيْثُ","mana pernah"],["يَشَآءُ ۚ","dia berkehendak"],["نُصِيبُ","Kami kurniakan"],["بِرَحْمَتِنَا","Kerahiman Kami"],["مَن","(pada) siapa"],["نَّشَآءُ ۖ","Kami akan"],["وَلَا","Dan tidak"],["نُضِيعُ","Kita lepaskan pembaziran"],["أَجْرَ","(i) ganjaran"],["ٱلْمُحْسِنِينَ","(dari) orang-orang yang berbuat baik"]]],"1653":["(Dan sesungguhnya pahala di akhirat itu lebih baik) daripada upah di dunia (bagi orang-orang beriman dan selalu bertakwa.) ketika musim paceklik tiba, musim paceklik itu menimpa pula negeri Kan`an dan negeri Syam.",[["وَلَأَجْرُ","Dan sesungguhnya pahalanya"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["خَيْرٌۭ","(lebih) baik"],["لِّلَّذِينَ","bagi mereka yang"],["ءَامَنُوا۟","beriman"],["وَكَانُوا۟","dan adalah"],["يَتَّقُونَ","Tuhan sedar"]]],"1654":["(Dan saudara-saudara Yusuf datang) kecuali Bunyamin, mereka datang untuk meminta makanan, karena mereka telah mendengar bahwa Aziz negeri Mesir membagi-bagikan makanan dengan memakai bayaran atau cara barter (lalu mereka masuk ke tempatnya. Maka Yusuf mengenal mereka) bahwasanya mereka adalah saudara-saudaranya (sedangkan mereka sudah tidak kenal lagi kepadanya) mereka tidak mengenalnya lagi karena sudah terlalu lama berpisah, dan pula mereka telah memastikan bahwa Yusuf telah mati. Lalu mereka berbicara dengan Yusuf memakai bahasa Ibrani. Nabi Yusuf berkata kepada mereka seolah-olah tidak mengenal mereka, \"Apakah gerangan yang menyebabkan kalian datang ke negeriku ini?\" Lalu mereka menjawab, \"Untuk membeli makanan.\" Lalu Nabi Yusuf berkata, \"Jangan-jangan kalian ini mata-mata musuh.\" Mereka menjawab, \"Kami berlindung kepada Allah dari hal itu.\" Nabi Yusuf bertanya, \"Dari manakah kalian ini?\" Mereka menjawab, \"Dari negeri Kan'an dan bapak kami bernama Yakub seorang nabi.\" Nabi Yusuf bertanya kembali, \"Apakah dia mempunyai anak lagi selain kalian?\" Mereka menjawab, \"Ya, dahulu kami berjumlah dua belas orang, kemudian saudara yang paling kecil di antara kami, kami ajak bepergian, lalu ia binasa di tengah padang sahara. Dia adalah anak yang paling disayang oleh bapak kami, dan saudara sekandungnya sajalah kini yang tinggal bersama bapak kami, lalu bapak kami melarangnya pergi ke mana-mana karena khawatir akan terjadi hal yang serupa. Ia kini menjadi penghibur hati bapak kami.\" Kemudian Nabi Yusuf memerintahkan supaya mereka diberi tempat dan dihormati sebagaimana layaknya tamu.",[["وَجَآءَ","Dan datang"],["إِخْوَةُ","(yang) saudara"],["يُوسُفَ","(dari) Yusuf"],["فَدَخَلُوا۟","dan mereka masuk"],["عَلَيْهِ","atasnya"],["فَعَرَفَهُمْ","dan dia mengenali mereka"],["وَهُمْ","tetapi mereka"],["لَهُۥ","tidak mengenalinya"],["مُنكِرُونَ","tidak mengenalinya"]]],"1655":["(Dan tatkala Yusuf menyiapkan untuk mereka bahan makanannya) lalu Nabi Yusuf menyempurnakan takaran bahan makanan itu buat mereka (ia berkata, \"Bawalah kepadaku saudara kalian yang seayah dengan kalian) yaitu Bunyamin, untuk mengecek kebenaran cerita kalian itu (tidakkah kalian melihat, bahwa aku menyempurnakan sukatan) yakni, aku telah menyempurnakannya tanpa menguranginya sedikit pun (dan aku adalah sebaik-baik penerima tamu?).",[["وَلَمَّا","Dan apabila"],["جَهَّزَهُم","dia telah menyediakan mereka"],["بِجَهَازِهِمْ","dengan bekalan mereka"],["قَالَ","dia berkata"],["ٱئْتُونِى","Bawa kepada aku"],["بِأَخٍۢ","seorang abang"],["لَّكُم","kamu"],["مِّنْ","daripada"],["أَبِيكُمْ ۚ","ayah kamu"],["أَلَا","Jangan"],["تَرَوْنَ","kamu lihat"],["أَنِّىٓ","bahawa aku"],["أُوفِى","[Aku] memberi penuh"],["ٱلْكَيْلَ","ukuran"],["وَأَنَا۠","dan bahawa aku"],["خَيْرُ","(yang) terbaik"],["ٱلْمُنزِلِينَ","(daripada) tuan rumah"]]],"1656":["(Jika kalian tidak membawanya kepadaku, maka kalian tidak akan mendapat sukatan lagi daripadaku) artinya kalian tidak akan mendapatkan bantuan makanan lagi (dan jangan kalian mendekatiku lagi.\") lafal wala taqrabuuni bermakna nahi atau melarang; atau di'athafkan kepada mahal lafal falaa kaila, sehingga artinya menjadi kalian tidak akan mendapatkan bantuan makanan dan kalian tidak dapat mendekat kepadaku.",[["فَإِن","Tetapi jika"],["لَّمْ","tidak"],["تَأْتُونِى","kamu bawa dia kepada aku"],["بِهِۦ","kamu bawa dia kepada aku"],["فَلَا","maka (akan ada) tidak"],["كَيْلَ","mengukur"],["لَكُمْ","bagi kamu"],["عِندِى","daripada aku"],["وَلَا","dan bukan"],["تَقْرَبُونِ","kamu akan datang dekat aku"]]],"1657":["(Mereka berkata, \"Kami akan membujuk ayahnya untuk membawanya ke mari) artinya kami akan berupaya sekuat tenaga dengan meminta kepada ayahnya untuk dapat membawanya (dan sesungguhnya kami benar-benar akan melaksanakannya.\") yakni melaksanakan hal tersebut.",[["قَالُوا۟","Mereka berkata"],["سَنُرَٰوِدُ","Kami akan cuba mendapatkan kebenaran"],["عَنْهُ","baginya"],["أَبَاهُ","(dari) bapanya"],["وَإِنَّا","dan sesungguhnya kita"],["لَفَـٰعِلُونَ","pasti akan buat"]]],"1658":["(Yusuf berkata kepada pembantu-pembantunya) menurut suatu qiraat lafal lifityaanihi dibaca lifatayaanihi yang artinya, kedua pembantunya (\"Masukkanlah barang-barang mereka) yang mereka bawa sebagai pengganti harga makanan; barang-barang tersebut berupa uang dirham (ke dalam karung-karung mereka) ke dalam kantung-kantung tempat makanan mereka (supaya mereka mengetahuinya apabila mereka telah kembali kepada keluarganya) kemudian mereka menumpahkan isi karung-karung mereka itu (mudah-mudahan mereka kembali lagi.\") kepada kita karena sesungguhnya mereka adalah kaum yang tidak menghalalkan menahannya.",[["وَقَالَ","Dan dia berkata"],["لِفِتْيَـٰنِهِ","kepada hamba-hambanya"],["ٱجْعَلُوا۟","letak"],["بِضَـٰعَتَهُمْ","barang dagangan mereka"],["فِى","dalam"],["رِحَالِهِمْ","beg pelana mereka"],["لَعَلَّهُمْ","supaya mereka"],["يَعْرِفُونَهَآ","mungkin mengenalinya"],["إِذَا","apabila"],["ٱنقَلَبُوٓا۟","mereka balik"],["إِلَىٰٓ","kepada"],["أَهْلِهِمْ","rakyat mereka"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَرْجِعُونَ","kembali"]]],"1659":["(Maka tatkala mereka telah kembali kepada ayah mereka, mereka berkata, \"Wahai ayah kami! Kami tidak akan mendapat sukatan) gandum lagi, jika ayah tidak mengizinkan saudara kami Bunyamin untuk menghadap kepadanya (sebab itu biarkanlah saudara kami pergi bersama kami supaya kami mendapat sukatan) menurut suatu qiraat dibaca yaktal artinya, supaya mendapat sukatan (dan sesungguhnya kami akan benar-benar menjaganya.\").",[["فَلَمَّا","Maka apabila"],["رَجَعُوٓا۟","mereka kembali"],["إِلَىٰٓ","kepada"],["أَبِيهِمْ","bapa mereka"],["قَالُوا۟","mereka berkata"],["يَـٰٓأَبَانَا","Wahai ayah kami"],["مُنِعَ","Telah dinafikan"],["مِنَّا","kepada kami"],["ٱلْكَيْلُ","ukurannya"],["فَأَرْسِلْ","jadi hantar"],["مَعَنَآ","dengan kami"],["أَخَانَا","saudara kita"],["نَكْتَلْ","(bahawa) kita akan mendapat ukuran"],["وَإِنَّا","Dan sesungguhnya, kita"],["لَهُۥ","baginya"],["لَحَـٰفِظُونَ","pasti (akan) menjadi penjaga"]]],"1660":["(Berkata Yakub, \"Bagaimana) tiada (aku akan mempercayakannya kepada kalian, kecuali seperti aku mempercayakan saudaranya kepada kalian) yang dimaksud adalah Nabi Yusuf (dahulu?) dan ternyata kalian telah mencelakakannya. (Maka Allah adalah sebaik-baik penjaga) menurut qiraat yang lain lafal haafizhan dibaca hifzhan dengan kedudukan menjadi tamyiz; perihalnya sama dengan perkataan mereka/orang-orang Arab lillaahi darruhu faarisan (dan Dia adalah Maha Penyayang di antara para penyayang.\") maka aku memohon semoga Dia menganugerahkan pemeliharaan-Nya terhadap Nabi Yusuf.",[["قَالَ","Dia berkata"],["هَلْ","sepatutnya"],["ءَامَنُكُمْ","aku amanahkan kamu"],["عَلَيْهِ","dengan dia"],["إِلَّا","kecuali"],["كَمَآ","seperti"],["أَمِنتُكُمْ","Aku amanahkan kamu"],["عَلَىٰٓ","dengan"],["أَخِيهِ","abangnya"],["مِن","sebelum"],["قَبْلُ ۖ","sebelum"],["فَٱللَّهُ","Tetapi Allah"],["خَيْرٌ","(adalah) yang terbaik"],["حَـٰفِظًۭا ۖ","Penjaga"],["وَهُوَ","dan Dia"],["أَرْحَمُ","(adalah) Yang Maha Penyayang"],["ٱلرَّٰحِمِينَ","(dari) yang penyayang"]]],"1661":["(Tatkala mereka membuka barang-barangnya, mereka menemukan kembali barang-barang penukaran mereka dikembalikan kepada mereka. Mereka berkata, \"Wahai ayah kami! Apalagi yang kita inginkan) huruf maa di sini merupakan kata tanya, artinya apalagi yang kita cari lebih dari penghormatan yang telah diberikan oleh sang raja? Menurut qiraat lafal nabghii dibaca tabghii sebagai khithab atau pembicaraan yang ditujukan kepada Nabi Yakub. Karena mereka menceritakan kepadanya tentang penghormatan sang raja terhadap mereka. (Ini barang-barang kita dikembalikan kepada kita dan kami akan dapat memberi makan keluarga kami) artinya kami dapat membawa perbekalan makanan buat mereka (dan kami akan menjaga saudara kami dan kami akan mendapat tambahan sukatan seberat beban seekor unta) untuk saudara kami Bunyamin. (Itulah sukatan yang mudah.\") bagi raja Mesir, karena ia orangnya sangat dermawan.",[["وَلَمَّا","Dan apabila"],["فَتَحُوا۟","mereka buka"],["مَتَـٰعَهُمْ","bagasi mereka"],["وَجَدُوا۟","mereka jumpa"],["بِضَـٰعَتَهُمْ","barang dagangan mereka"],["رُدَّتْ","dikembalikan"],["إِلَيْهِمْ ۖ","kepada mereka"],["قَالُوا۟","Mereka berkata"],["يَـٰٓأَبَانَا","Wahai ayah kami"],["مَا","Apa"],["نَبْغِى ۖ","(boleh) kita inginkan"],["هَـٰذِهِۦ","Ini"],["بِضَـٰعَتُنَا","(adalah) barang dagangan kami"],["رُدَّتْ","dikembalikan"],["إِلَيْنَا ۖ","kepada kami"],["وَنَمِيرُ","Dan kita akan mendapat rezeki"],["أَهْلَنَا","(untuk) keluarga kita"],["وَنَحْفَظُ","dan kami akan melindungi"],["أَخَانَا","saudara kita"],["وَنَزْدَادُ","dan mendapat peningkatan"],["كَيْلَ","mengukur"],["بَعِيرٍۢ ۖ","(dari) unta (muatan)"],["ذَٰلِكَ","Itu"],["كَيْلٌۭ","(adalah) ukuran"],["يَسِيرٌۭ","mudah"]]],"1662":["(Yakub berkata, \"Aku sekali-kali tidak akan melepaskannya pergi bersama kalian sebelum kalian memberikan kepadaku janji yang teguh) sumpah (atas nama Allah) seumpamanya kalian bersumpah (bahwa kalian pasti akan membawanya kepadaku kembali kecuali jika kalian dikepung musuh.\") seumpamanya kalian semuanya mati, atau kalian dikalahkan oleh musuh sehingga kalian tidak mampu membawa Bunyamin kembali kepadaku. Lalu mereka menyetujui hal tersebut. (Tatkala mereka memberikan janji mereka) mengikrarkan hal tersebut (maka Yakub berkata, \"Allah terhadap apa yang kita ucapkan) ini, yaitu saya dan kalian (adalah menjadi saksi.\") menyaksikannya kemudian Nabi Yakub memberikan izin kepada mereka untuk membawa serta Bunyamin.",[["قَالَ","Dia berkata"],["لَنْ","tidak pernah"],["أُرْسِلَهُۥ","adakah aku akan menghantarnya"],["مَعَكُمْ","bersama kamu"],["حَتَّىٰ","sehingga"],["تُؤْتُونِ","kamu berikan kepada aku"],["مَوْثِقًۭا","sebuah janji"],["مِّنَ","oleh"],["ٱللَّهِ","Allah"],["لَتَأْتُنَّنِى","bahawa sesungguhnya kamu akan membawanya kepadaku"],["بِهِۦٓ","bahawa sesungguhnya kamu akan membawanya kepadaku"],["إِلَّآ","melainkan"],["أَن","bahawa"],["يُحَاطَ","kamu dikelilingi"],["بِكُمْ ۖ","kamu dikelilingi"],["فَلَمَّآ","Dan apabila"],["ءَاتَوْهُ","mereka telah memberinya"],["مَوْثِقَهُمْ","janji mereka"],["قَالَ","dia berkata"],["ٱللَّهُ","Allah"],["عَلَىٰ","atas"],["مَا","apa"],["نَقُولُ","kita cakap"],["وَكِيلٌۭ","(adalah) seorang Penjaga"]]],"1663":["(Dan Yakub berkata, \"Hai anak-anakku! Janganlah kalian masuk) ke negeri Mesir (dari satu pintu gerbang, tetapi masuklah dari pintu-pintu gerbang yang berlainan) supaya kalian tidak menjadi sial karenanya (namun demikian aku tidak dapat menghindarkan) menolak (diri kalian) dengan melalui saranku ini (dari takdir Allah) huruf min di sini adalah zaidah (barang sedikit pun) yang telah ditakdirkan-Nya terhadap kalian; sesungguhnya hal tersebut hanyalah terdorong oleh rasa sayangku. (Tiada lain) (keputusan hanyalah hak Allah) semata (dan hanya kepada-Nyalah aku bertawakal) artinya hanya kepada-Nyalah aku percaya (dan hanya kepada-Nyalah hendaknya orang-orang yang bertawakal berserah diri.\")",[["وَقَالَ","Dan dia berkata"],["يَـٰبَنِىَّ","Wahai anak-anakku"],["لَا","Jangan"],["تَدْخُلُوا۟","masuk"],["مِنۢ","daripada"],["بَابٍۢ","satu pintu gerbang"],["وَٰحِدٍۢ","satu pintu gerbang"],["وَٱدْخُلُوا۟","tapi masuk"],["مِنْ","daripada"],["أَبْوَٰبٍۢ","pintu pagar"],["مُّتَفَرِّقَةٍۢ ۖ","berbeza"],["وَمَآ","Dan tidak"],["أُغْنِى","Aku boleh memanfaatkan"],["عَنكُم","kamu"],["مِّنَ","terhadap"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["شَىْءٍ ۖ","perkara"],["إِنِ","Tidak"],["ٱلْحُكْمُ","(adalah) keputusannya"],["إِلَّا","kecuali"],["لِلَّهِ ۖ","dengan Allah"],["عَلَيْهِ","atas Dia"],["تَوَكَّلْتُ ۖ","Aku meletakkan kepercayaan aku"],["وَعَلَيْهِ","dan kepada-Nya"],["فَلْيَتَوَكَّلِ","hendaklah meletakkan amanah (mereka)."],["ٱلْمُتَوَكِّلُونَ","mereka yang meletakkan amanah"]]],"1664":["Allah berfirman: (Dan tatkala mereka masuk menurut yang diperintahkan oleh ayah mereka) yaitu masuk secara berpencar-pencar (maka hal itu tidak dapat melepaskan diri mereka dari Allah) yakni dari kepastian-Nya (barang) huruf min di sini adalah zaidah (sedikit pun akan tetapi itu hanya) tetapi hal itu hanyalah (suatu keinginan pada diri Yakub yang telah ditunaikannya) yaitu bermaksud untuk menghindarkan mereka dari kesialan karena terdorong oleh rasa sayang (dan sesungguhnya dia mempunyai pengetahuan karena Kami telah mengajarkan kepadanya) disebabkan Kami telah mengajarkan kepadanya (akan tetapi kebanyakan manusia) mereka adalah orang-orang kafir (tiada mengetahui.) ilham Allah yang dianugerahkan kepada orang-orang pilihan-Nya.",[["وَلَمَّا","Dan apabila"],["دَخَلُوا۟","mereka masuk"],["مِنْ","daripada"],["حَيْثُ","di mana"],["أَمَرَهُمْ","memerintahkan mereka"],["أَبُوهُم","bapa mereka"],["مَّا","tidak"],["كَانَ","ia"],["يُغْنِى","avail(ed)"],["عَنْهُم","mereka"],["مِّنَ","terhadap"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["شَىْءٍ","perkara"],["إِلَّا","tetapi"],["حَاجَةًۭ","(ia adalah) keperluan"],["فِى","daripada"],["نَفْسِ","ruh Yaqub"],["يَعْقُوبَ","ruh Yaqub"],["قَضَىٰهَا ۚ","yang dia laksanakan"],["وَإِنَّهُۥ","Dan sesungguhnya, dia"],["لَذُو","(adalah) seorang pemilik"],["عِلْمٍۢ","(dari) pengetahuan"],["لِّمَا","kerana"],["عَلَّمْنَـٰهُ","Kami telah mengajarnya"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(daripada) rakyat"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"1665":["(Dan tatkala mereka masuk ke tempat Yusuf, Yusuf menempatkan) yakni membawa saudaranya Bunyamin (saudaranya ke tempatnya. Yusuf berkata, \"Sesungguhnya aku ini adalah saudaramu, maka janganlah kamu berduka cita) bersedih hati (terhadap apa yang telah mereka lakukan.\") yaitu kedengkian mereka terhadap kita. Kemudian Nabi Yusuf menyuruh Bunyamin supaya jangan menceritakan hal ini kepada mereka. Yusuf telah bersepakat dengan Bunyamin, bahwa ia akan membuat siasat supaya Bunyamin tetap tinggal bersamanya.",[["وَلَمَّا","Dan apabila"],["دَخَلُوا۟","mereka masuk"],["عَلَىٰ","ke atas"],["يُوسُفَ","Yusuf"],["ءَاوَىٰٓ","dia ambil"],["إِلَيْهِ","kepada dirinya sendiri"],["أَخَاهُ ۖ","abangnya"],["قَالَ","Dia berkata"],["إِنِّىٓ","Sesungguhnya aku"],["أَنَا۠","[Aku] adalah"],["أَخُوكَ","abang kamu"],["فَلَا","jadi (jangan)"],["تَبْتَئِسْ","bersedih"],["بِمَا","bagi apa"],["كَانُوا۟","mereka pernah (untuk)"],["يَعْمَلُونَ","lakukan"]]],"1666":["(Maka tatkala telah disiapkan untuk mereka bahan makanan mereka, Yusuf memasukkan piala tempat minum) teko yang terbuat dari emas dan dihiasi dengan permata (ke dalam karung saudaranya) yaitu karung kepunyaan Bunyamin (kemudian berteriaklah seseorang yang menyerukan) setelah mereka berpisah dari majelis Yusuf, tiba-tiba terdengar ada seseorang yang berseru (\"Hai kafilah!) rombongan musafir (Sesungguhnya kalian adalah orang-orang yang mencuri.\").",[["فَلَمَّا","Maka apabila"],["جَهَّزَهُم","dia telah menyediakan mereka"],["بِجَهَازِهِمْ","dengan bekalan mereka"],["جَعَلَ","dia meletakkan"],["ٱلسِّقَايَةَ","cawan minuman itu"],["فِى","dalam"],["رَحْلِ","beg itu"],["أَخِيهِ","(dari) saudaranya"],["ثُمَّ","Kemudian"],["أَذَّنَ","dipanggil keluar"],["مُؤَذِّنٌ","seorang juruhebah"],["أَيَّتُهَا","Wahai"],["ٱلْعِيرُ","(dalam) karavan"],["إِنَّكُمْ","Sesungguhnya kamu"],["لَسَـٰرِقُونَ","sesungguhnya (adalah) pencuri"]]],"1667":["(Mereka menjawab sambil) seraya (menghadap kepada penyeru-penyeru itu, \"Barang apakah) sesuatu apakah yang (hilang daripada kalian.\").",[["قَالُوا۟","Mereka berkata"],["وَأَقْبَلُوا۟","menoleh ke arah"],["عَلَيْهِم","mereka"],["مَّاذَا","apa (itu)"],["تَفْقِدُونَ","kamu rindu"]]],"1668":["(Penyeru-penyeru itu berkata, \"Kami kehilangan piala) teko (raja dan bagi siapa yang dapat mengembalikannya akan memperoleh hadiah seberat beban unta) berupa bahan makanan (dan aku terhadapnya) tentang hadiah itu (menjadi penjamin.\") yang menanggungnya.",[["قَالُوا۟","Mereka berkata"],["نَفْقِدُ","Kami hilang"],["صُوَاعَ","(the) cawan"],["ٱلْمَلِكِ","(dari) raja"],["وَلِمَن","Dan untuk (seorang) yang"],["جَآءَ","membawa"],["بِهِۦ","ia"],["حِمْلُ","(adalah) beban"],["بَعِيرٍۢ","(dari) unta"],["وَأَنَا۠","dan aku"],["بِهِۦ","baginya"],["زَعِيمٌۭ","(adalah) bertanggungjawab"]]],"1669":["(Saudara-saudara Yusuf menjawab, \"Demi Allah) sumpah yang di dalamnya terkandung makna takjub (sesungguhnya kalian mengetahui bahwa kami datang bukan untuk membuat kerusakan di negeri ini dan kami bukanlah orang-orang pencuri.\") kami sama sekali belum pernah mencuri.",[["قَالُوا۟","Mereka berkata"],["تَٱللَّهِ","Demi Allah"],["لَقَدْ","sudah tentu"],["عَلِمْتُم","kamu tahu"],["مَّا","tidak"],["جِئْنَا","kami datang"],["لِنُفْسِدَ","bahawa kita menyebabkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَمَا","dan bukan"],["كُنَّا","kita"],["سَـٰرِقِينَ","pencuri"]]],"1670":["(Penyeru-penyeru itu berkata) yakni juru penyeru dan teman-temannya (\"Tetapi apa balasannya) bagi si pencuri (jika kalian betul-betul pendusta?\") kalian berdusta di dalam pengakuan kalian yang mengatakan bahwa kalian tidak mencuri. Kemudian ternyata piala tersebut ditemukan dalam barang kalian.",[["قَالُوا۟","Mereka berkata"],["فَمَا","Kemudian apa"],["جَزَٰٓؤُهُۥٓ","(adalah) balasannya"],["إِن","jika"],["كُنتُمْ","kamu"],["كَـٰذِبِينَ","pembohong"]]],"1671":["(Mereka menjawab, \"Balasannya) lafal jazaauhu ini menjadi mubtada, sedangkan khabarnya ialah (ialah pada siapa ditemukan barang yang hilang itu dalam karungnya) maka ia harus dijadikan budak. Kemudian diperkuat dengan berikutnya (maka dia sendirilah) si pencuri itu sendiri (balasannya.\") sebagai tebusan dari barang yang dicurinya, bukan orang lain. Ketentuan ini yaitu orang yang mencuri dihukum menjadi budak, merupakan syariat Nabi Yakub. (Demikianlah) seperti pembalasan itu (Kami memberi pembalasan kepada orang-orang yang lalim.) yaitu karena mencuri. Kemudian para penyeru itu mengajukan usul kepada Nabi Yusuf supaya karung-karung mereka diperiksa.",[["قَالُوا۟","Mereka berkata"],["جَزَٰٓؤُهُۥ","balasannya"],["مَن","(adakah itu) siapa"],["وُجِدَ","ia ditemui"],["فِى","dalam"],["رَحْلِهِۦ","begnya"],["فَهُوَ","kemudian dia"],["جَزَٰٓؤُهُۥ ۚ","(akan menjadi) balasannya"],["كَذَٰلِكَ","Demikianlah"],["نَجْزِى","(adakah) kami membalasnya"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1672":["(Maka mulailah Yusuf dengan karung-karung mereka) yaitu memeriksanya (sebelum memeriksa karung saudaranya sendiri) supaya mereka tidak menaruh rasa curiga terhadapnya (kemudian dia mengeluarkan piala raja itu) yakni tempat minum raja. (dari karung saudaranya.) Selanjutnya Allah berfirman mengisahkan (Demikianlah) tipu muslihat itu (Kami atur untuk mencapai maksud Yusuf) artinya, Kami ajarkan kepadanya tentang siasat untuk mengambil saudara sekandungnya (Tiada patut) Yusuf (menghukum saudaranya) dengan menjadikannya sebagai budak karena terbukti telah mencuri (menurut undang-undang raja) sesuai dengan ketentuan raja Mesir, karena hukuman bagi pencuri menurut undang-undang raja Mesir ialah dipukuli dan dikenai denda sebanyak dua kali lipat harga barang yang dicurinya, bukannya dijadikan sebagai budak (kecuali Allah menghendaki-Nya) yakni menghendaki supaya Yusuf menghukum saudaranya sesuai dengan ketentuan syariat Nabi Yakub. Artinya Nabi Yusuf tidak dapat menghukumnya kecuali Allah menghendaki melalui wahyu-Nya supaya Nabi Yusuf menghukum saudaranya itu sesuai dengan syariat yang berlaku pada mereka (Kami tinggikan derajat orang yang Kami kehendaki) melalui ilmu seperti yang Kami lakukan terhadap Yusuf. Lafal ayat ini dapat dibaca secara idhafah, yaitu menjadi darajaati man nasyaau, dan dapat pula dibaca darajaatin man nasyaau (dan di atas tiap-tiap orang berpengetahuan itu) di antara semua makhluk (ada lagi yang Maha Mengetahui.) artinya yang lebih mengetahui daripadanya sehingga rentetannya selesai pada Allah swt.",[["فَبَدَأَ","Jadi dia mula"],["بِأَوْعِيَتِهِمْ","dengan beg mereka"],["قَبْلَ","sebelum"],["وِعَآءِ","(beg) itu"],["أَخِيهِ","(dari) saudaranya"],["ثُمَّ","kemudian"],["ٱسْتَخْرَجَهَا","dia membawanya keluar"],["مِن","daripada"],["وِعَآءِ","(beg) itu"],["أَخِيهِ ۚ","(dari) saudaranya"],["كَذَٰلِكَ","Demikianlah"],["كِدْنَا","(ada) Kami merancang"],["لِيُوسُفَ ۖ","untuk Yusuf"],["مَا","Dia tidak boleh"],["كَانَ","Dia tidak boleh"],["لِيَأْخُذَ","ambil"],["أَخَاهُ","abangnya"],["فِى","oleh"],["دِينِ","undang-undang"],["ٱلْمَلِكِ","(dari) raja"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يَشَآءَ","Allah menghendaki"],["ٱللَّهُ ۚ","Allah menghendaki"],["نَرْفَعُ","Kami naikkan"],["دَرَجَـٰتٍۢ","(dalam) darjah"],["مَّن","yang"],["نَّشَآءُ ۗ","Kami akan"],["وَفَوْقَ","tetapi berakhir"],["كُلِّ","setiap"],["ذِى","pemilik"],["عِلْمٍ","(dari) pengetahuan"],["عَلِيمٌۭ","(ialah) Yang Maha Mengetahui"]]],"1673":["(Mereka berkata, \"Jika ia mencuri maka sesungguhnya telah pernah mencuri pula saudaranya sebelum itu.\") yang dimaksud oleh mereka adalah Yusuf. Disebutkan bahwa Nabi Yusuf dahulu pernah mencuri sebuah berhala yang terbuat dari emas milik ayah ibunya kemudian berhala tersebut dihancurkannya; dimaksud supaya ia tidak menyembahnya. (Maka Yusuf menyembunyikan kejengkelan itu pada dirinya dan tidak menampakkannya) tidak melahirkannya (kepada mereka) dhamir atau kata ganti yang ada pada kalimat ayat ini merujuk kepada pengertian yang tersirat di dalam perkataan Nabi Yusuf berikut ini, yaitu: (Dia berkata,) di dalam hatinya (\"Kalian lebih buruk kedudukannya) daripada Yusuf dan saudara sekandungnya karena kalian telah mencuri saudara kalian, yaitu Nabi Yusuf sendiri dari tangan ayah kalian kemudian kalian telah berbuat aniaya terhadap dirinya (dan Allah Maha Mengetahui) mengetahui (apa yang kalian terangkan itu.\") apa yang kalian sebutkan tentang perkara Yusuf itu.",[["۞ قَالُوٓا۟","Mereka berkata"],["إِن","Jika"],["يَسْرِقْ","dia mencuri"],["فَقَدْ","maka sesungguhnya"],["سَرَقَ","mencuri"],["أَخٌۭ","seorang abang"],["لَّهُۥ","miliknya"],["مِن","sebelum"],["قَبْلُ ۚ","sebelum"],["فَأَسَرَّهَا","Tetapi Yusuf merahsiakannya"],["يُوسُفُ","Tetapi Yusuf merahsiakannya"],["فِى","dalam"],["نَفْسِهِۦ","dirinya sendiri"],["وَلَمْ","dan (tidak) tidak"],["يُبْدِهَا","mendedahkannya"],["لَهُمْ ۚ","kepada mereka"],["قَالَ","Dia berkata"],["أَنتُمْ","kamu"],["شَرٌّۭ","(adalah) lebih teruk"],["مَّكَانًۭا ۖ","(dalam) kedudukan"],["وَٱللَّهُ","dan Allah"],["أَعْلَمُ","lebih tahu"],["بِمَا","tentang apa"],["تَصِفُونَ","kamu huraikan"]]],"1674":["(Mereka berkata, \"Wahai Al-Aziz! Sesungguhnya ia mempunyai ayah yang sudah lanjut usianya) yang sangat mencintainya lebih daripada kecintaannya terhadap kami. Ia selalu menghibur dirinya dengan dia dari anaknya yang hilang dahulu karena ia sangat sedih sekali dengan kehilangannya (oleh karena itu ambillah salah seorang di antara kami) kemudian jadikanlah dia sebagai hamba sahayamu (sebagai gantinya.) penggantinya (Sesungguhnya kami melihat kamu termasuk orang-orang yang berbuat baik.\") dalam semua tindakan-tindakanmu.",[["قَالُوا۟","Mereka berkata"],["يَـٰٓأَيُّهَا","Wahai"],["ٱلْعَزِيزُ","Aziz"],["إِنَّ","Sesungguhnya"],["لَهُۥٓ","dia ada"],["أَبًۭا","seorang bapa"],["شَيْخًۭا","lama"],["كَبِيرًۭا","[hebat]"],["فَخُذْ","jadi ambil"],["أَحَدَنَا","salah seorang daripada kami"],["مَكَانَهُۥٓ ۖ","(di) tempatnya"],["إِنَّا","Sesungguhnya kami"],["نَرَىٰكَ","[kami] jumpa kamu"],["مِنَ","daripada"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"1675":["(Berkata Yusuf, \"Aku berlindung kepada Allah) lafal ini dinashabkan karena menjadi mashdar sedangkan fi`ilnya tidak disebutkan kemudian dimudhafkan kepada maf`ulnya; artinya aku mohon perlindungan kepada Allah (daripada menahan seorang kecuali orang yang kami temukan harta benda kami padanya) Nabi Yusuf dalam hal ini tidak memakai kata mencuri demi untuk memelihara diri daripada perkataan dusta (jika kami berbuat demikian, maka benar-benarlah kami) yaitu jika kami menghukum selainnya (orang-orang yang lalim.\")",[["قَالَ","Dia berkata"],["مَعَاذَ","Allah melarang"],["ٱللَّهِ","Allah melarang"],["أَن","bahawa"],["نَّأْخُذَ","kita ambil"],["إِلَّا","kecuali"],["مَن","(satu) siapa"],["وَجَدْنَا","kami jumpa"],["مَتَـٰعَنَا","milik kita"],["عِندَهُۥٓ","dengan dia"],["إِنَّآ","Sesungguhnya kami"],["إِذًۭا","kemudian"],["لَّظَـٰلِمُونَ","sesungguhnya (adalah) orang-orang yang zalim"]]],"1676":["(Maka tatkala mereka berputus asa) tidak mempunyai harapan lagi (daripada putusan Yusuf, mereka menyendiri) berkumpul menyendiri (sambil berunding dengan berbisik-bisik) lafal najiyyan adalah mashdar yang maknanya boleh untuk seorang dan orang banyak; artinya sebagian dari mereka berbisik-bisik kepada sebagian yang lain (Berkatalah yang tertua di antara mereka) yang umurnya paling besar, yaitu Rubel atau Raya yang dikenal juga dengan nama Yahudza (\"Tidakkah kalian ketahui bahwa sesungguhnya ayah kalian telah mengambil janji dari kalian) kalian telah bersumpah terhadapnya (dengan nama Allah) tentang saudara kalian ini, yaitu Bunyamin (dan sebelum itu) huruf maa pada kalimat ini zaidah (kalian telah menyia-nyiakan Yusuf) tetapi menurut pendapat yang lain huruf maa di sini adalah mashdariyah dan berkedudukan menjadi mubtada, sedangkan khabarnya adalah lafal min qablu. (Sebab itu aku tidak akan meninggalkan) tidak akan angkat kaki dari (negeri ini) yaitu negeri Mesir (sampai ayahku mengizinkan kepadaku) untuk kembali kepadanya (atau Allah memberi keputusan terhadapku) tentang pembebasan saudaraku Bunyamin ini. (Dan Dia adalah Hakim yang sebaik-baiknya.\") yakni yang paling adil di antara kesemuanya.",[["فَلَمَّا","Maka apabila"],["ٱسْتَيْـَٔسُوا۟","mereka putus asa"],["مِنْهُ","daripada dia"],["خَلَصُوا۟","mereka mengasingkan diri"],["نَجِيًّۭا ۖ","(dalam) perundingan peribadi"],["قَالَ","Berkata"],["كَبِيرُهُمْ","yang paling tua di antara mereka"],["أَلَمْ","Jangan"],["تَعْلَمُوٓا۟","kamu tahu"],["أَنَّ","bahawa"],["أَبَاكُمْ","ayah kamu"],["قَدْ","telah mengambil"],["أَخَذَ","telah mengambil"],["عَلَيْكُم","ke atas kamu"],["مَّوْثِقًۭا","sebuah janji"],["مِّنَ","oleh"],["ٱللَّهِ","Allah"],["وَمِن","dan sebelum ini"],["قَبْلُ","dan sebelum ini"],["مَا","bahawa"],["فَرَّطتُمْ","kamu gagal"],["فِى","tentang"],["يُوسُفَ ۖ","Yusuf"],["فَلَنْ","Jadi jangan sekali-kali"],["أَبْرَحَ","adakah aku akan pergi"],["ٱلْأَرْضَ","bumi"],["حَتَّىٰ","sehingga"],["يَأْذَنَ","permit"],["لِىٓ","aku"],["أَبِىٓ","ayah aku"],["أَوْ","atau"],["يَحْكُمَ","Allah yang menentukan"],["ٱللَّهُ","Allah yang menentukan"],["لِى ۖ","untuk aku"],["وَهُوَ","dan Dia"],["خَيْرُ","(adalah) yang Terbaik"],["ٱلْحَـٰكِمِينَ","(dari) para hakim"]]],"1677":["(Kembalilah kepada ayah kalian, dan katakanlah, \"Wahai ayah kami! Sesungguhnya anakmu telah mencuri; dan kami tiada menyaksikan) terhadapnya (melainkan berdasarkan apa yang telah kami ketahui) karena mereka merasa yakin setelah melihat dan menyaksikan adanya piala raja di dalam karung Bunyamin (dan sekali-kali terhadap barang yang gaib kami tidak) hal-hal yang gaib daripada kami sewaktu kami memberikan janji kepadamu (dapat menjaganya.) seandainya kami mengetahui apa yang akan terjadi kemudian, yaitu bahwasanya dia akan mencuri, niscaya kami tidak akan membawanya ikut bersama kami.",[["ٱرْجِعُوٓا۟","Kembali"],["إِلَىٰٓ","kepada"],["أَبِيكُمْ","ayah kamu"],["فَقُولُوا۟","dan katakan"],["يَـٰٓأَبَانَآ","'Wahai ayah kami"],["إِنَّ","Sesungguhnya"],["ٱبْنَكَ","anak kamu"],["سَرَقَ","telah mencuri"],["وَمَا","dan bukan"],["شَهِدْنَآ","kami bersaksi"],["إِلَّا","kecuali"],["بِمَا","tentang apa"],["عَلِمْنَا","kami tahu"],["وَمَا","Dan tidak"],["كُنَّا","kami"],["لِلْغَيْبِ","daripada yang ghaib"],["حَـٰفِظِينَ","penjaga"]]],"1678":["(Dan tanyalah penduduk negeri yang kami berada di situ) yakni negeri Mesir; artinya kirimkanlah utusan ke negeri Mesir kemudian tanyakanlah kepada penduduknya (dan kafilah) rombongan musafir (yang kami datang bersamanya) mereka adalah terdiri dari kaum Kan`an (dan sesungguhnya kami adalah orang-orang yang benar.\") di dalam perkataan kami ini. Kemudian mereka kembali kepada ayah mereka dan mengatakan seperti yang diajarkan oleh saudara mereka yang tertua.",[["وَسْـَٔلِ","Dan bertanya"],["ٱلْقَرْيَةَ","bandar itu"],["ٱلَّتِى","di mana"],["كُنَّا","kami"],["فِيهَا","[di dalamnya]"],["وَٱلْعِيرَ","dan karavan"],["ٱلَّتِىٓ","yang"],["أَقْبَلْنَا","kami balik"],["فِيهَا ۖ","[di dalamnya]"],["وَإِنَّا","Dan sesungguhnya, kita"],["لَصَـٰدِقُونَ","sesungguhnya (adalah) orang yang benar.'"]]],"1679":["(Yakub berkata, \"Bahkan telah menggoda) menganggap baik (kalian diri kalian sendiri perbuatan buruk itu) kemudian kalian mengerjakan perbuatan itu lagi. Nabi Yakub menuduh mereka seperti tuduhannya terhadap mereka mengenai peristiwa yang menimpa Nabi Yusuf dahulu. (Maka kesabaran yang baik itu) adalah kesabaranku. (Mudah-mudahan Allah mendatangkan mereka kepadaku) yaitu Yusuf dan saudaranya (semuanya; sesungguhnya Dialah Yang Maha Mengetahui) tentang keadaanku (lagi Maha Bijaksana.\") di dalam perbuatan-Nya.",[["قَالَ","Dia berkata"],["بَلْ","Bahkan"],["سَوَّلَتْ","telah memikat"],["لَكُمْ","kamu"],["أَنفُسُكُمْ","jiwa kamu"],["أَمْرًۭا ۖ","sesuatu"],["فَصَبْرٌۭ","jadi sabar"],["جَمِيلٌ ۖ","(adalah) cantik"],["عَسَى","barangkali"],["ٱللَّهُ","Allah"],["أَن","akan membawa mereka kepada aku"],["يَأْتِيَنِى","akan membawa mereka kepada aku"],["بِهِمْ","akan membawa mereka kepada aku"],["جَمِيعًا ۚ","semua"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","Dia"],["ٱلْعَلِيمُ","(ialah) Yang Maha Mengetahui"],["ٱلْحَكِيمُ","Maha Bijaksana"]]],"1680":["(Dan Yakub berpaling dari mereka) seraya tidak meladeni pembicaraan mereka (seraya berkata, \"Aduhai, duka-citaku) huruf alif yang terdapat pada kata yaa asafaa merupakan pergantian daripada huruf ya idhafat; artinya aduhai alangkah sedihnya (terhadap Yusuf,\" dan kedua matanya menjadi putih) bagian yang hitam dari matanya tertutup oleh benda yang putih karena terlalu banyak menangis (karena kesedihan) terhadap Yusuf (dan dia adalah seorang yang menahan amarah) terhadap anak-anaknya akan tetapi ia tidak menampakkan kemarahannya itu dan menahannya.",[["وَتَوَلَّىٰ","Dan dia berpaling"],["عَنْهُمْ","daripada mereka"],["وَقَالَ","dan berkata"],["يَـٰٓأَسَفَىٰ","Aduhai, kesedihan aku"],["عَلَىٰ","atas"],["يُوسُفَ","Yusuf"],["وَٱبْيَضَّتْ","Dan menjadi putih"],["عَيْنَاهُ","matanya"],["مِنَ","daripada"],["ٱلْحُزْنِ","kesedihan itu"],["فَهُوَ","dan dia (adalah)"],["كَظِيمٌۭ","penekan"]]],"1681":["(Mereka berkata, \"Demi Allah) tiada (henti-hentinya) terus-menerus (engkau masih mengingat Yusuf sehingga kamu mengidap penyakit yang amat berat) hampir binasa, karena penyakitmu yang berkepanjangan itu. Lafal haradhan berbentuk mashdar yang maknanya dapat diartikan untuk satu orang dan lebih (atau termasuk orang-orang yang binasa.\") orang-orang yang akan mati.",[["قَالُوا۟","Mereka berkata"],["تَٱللَّهِ","Demi Allah"],["تَفْتَؤُا۟","kamu tidak akan berhenti"],["تَذْكُرُ","mengingati"],["يُوسُفَ","Yusuf"],["حَتَّىٰ","sehingga"],["تَكُونَ","kamu menjadi"],["حَرَضًا","sakit maut"],["أَوْ","atau"],["تَكُونَ","menjadi"],["مِنَ","daripada"],["ٱلْهَـٰلِكِينَ","mereka yang binasa"]]],"1682":["(Yakub menjawab) terhadap anak-anaknya (\"Sesungguhnya aku mengadukan kesedihanku) yaitu kesusahan yang besar yang tidak dapat ditahan lagi; sehingga orang yang bersangkutan tidak mampu lagi menahannya lalu mengadukannya kepada orang lain (dan kesusahanku hanya kepada Allah) bukan kepada yang lain-Nya, karena hanya Dialah yang dapat menyelesaikan pengaduanku ini (dan aku mengetahui dari Allah apa yang tidak kalian ketahui.\") yaitu bahwasanya mimpi Yusuf itu adalah benar, dia masih tetap hidup. Kemudian ia berkata:",[["قَالَ","Dia berkata"],["إِنَّمَآ","Hanya"],["أَشْكُوا۟","aku mengeluh"],["بَثِّى","(dari) penderitaan aku"],["وَحُزْنِىٓ","dan kesedihan aku"],["إِلَى","kepada"],["ٱللَّهِ","Allah"],["وَأَعْلَمُ","dan aku tahu"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"1683":["(\"Hai anak-anakku! Pergilah kalian, maka carilah berita tentang Yusuf dan saudara sekandungnya) artinya carilah berita tentang keduanya (dan jangan kalian berputus asa) putus harapan (dari rahmat Allah) dari rahmat-Nya (Sesungguhnya tiada berputus asa dari rahmat Allah melainkan kaum yang kafir.\") Lalu mereka berangkat menuju ke negeri Mesir.",[["يَـٰبَنِىَّ","Wahai anak-anakku"],["ٱذْهَبُوا۟","Pergi"],["فَتَحَسَّسُوا۟","dan bertanya"],["مِن","tentang"],["يُوسُفَ","Yusuf"],["وَأَخِيهِ","dan abangnya"],["وَلَا","dan bukan"],["تَا۟يْـَٔسُوا۟","putus asa"],["مِن","daripada"],["رَّوْحِ","(rahmat) Allah"],["ٱللَّهِ ۖ","(rahmat) Allah"],["إِنَّهُۥ","Sesungguhnya"],["لَا","tiada"],["يَا۟يْـَٔسُ","putus asa"],["مِن","daripada"],["رَّوْحِ","(rahmat) Allah"],["ٱللَّهِ","(rahmat) Allah"],["إِلَّا","kecuali"],["ٱلْقَوْمُ","manusia"],["ٱلْكَـٰفِرُونَ","orang kafir"]]],"1684":["(Maka ketika mereka masuk ke tempat Yusuf mereka berkata, \"Hai Al-Aziz! Kami dan keluarga kami ditimpa kesengsaraan) yakni kelaparan (dan kami datang membawa barang-barang yang tak berharga) artinya barang-barang yang buruk; setiap orang yang melihatnya pasti akan menolaknya karena mutunya sangat rendah sekali. Disebutkan bahwa barang-barang tersebut berupa dirham-dirham palsu atau barang-barang lainnya (maka sempurnakanlah) genapkanlah (sukatan untuk kami dan bersedekahlah kepada kami) bertoleransilah terhadap kami sekali pun barang-barang kami rendah mutunya (sesungguhnya Allah memberi balasan kepada orang-orang yang bersedekah.\") artinya Allah memberi mereka pahala. Akhirnya Nabi Yusuf merasa belas kasihan kepada mereka timbullah rasa sayangnya. Kemudian Nabi Yusuf berbicara secara terus terang terhadap mereka untuk menyingkapkan tabir antara dirinya dan mereka.",[["فَلَمَّا","Maka apabila"],["دَخَلُوا۟","mereka masuk"],["عَلَيْهِ","atasnya"],["قَالُوا۟","mereka berkata"],["يَـٰٓأَيُّهَا","Wahai Aziz"],["ٱلْعَزِيزُ","Wahai Aziz"],["مَسَّنَا","Telah menyentuh kita"],["وَأَهْلَنَا","dan keluarga kami"],["ٱلضُّرُّ","kesusahan itu"],["وَجِئْنَا","dan kami telah datang"],["بِبِضَـٰعَةٍۢ","dengan barang"],["مُّزْجَىٰةٍۢ","(bernilai) sedikit"],["فَأَوْفِ","tetapi bayar (dalam) penuh"],["لَنَا","kepada kami"],["ٱلْكَيْلَ","ukurannya"],["وَتَصَدَّقْ","dan beramal"],["عَلَيْنَآ ۖ","kepada kami"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَجْزِى","ganjaran"],["ٱلْمُتَصَدِّقِينَ","amal itu"]]],"1685":["(Berkatalah Yusuf) kepada mereka dengan nada mencela (\"Apakah kalian mengetahui kejelekan apa yang telah kalian lakukan terhadap Yusuf) yaitu dengan memukuli dan menjualnya serta hal-hal lainnya yang menyakitkan (dan saudaranya) yakni penekanan kalian terhadapnya sesudah ia terpisah dari saudaranya (ketika kalian tidak mengetahui akibat perbuatan kalian itu?\") akibat perbuatan kalian terhadap Nabi Yusuf",[["قَالَ","Dia berkata"],["هَلْ","buat"],["عَلِمْتُم","kamu tahu"],["مَّا","apa"],["فَعَلْتُم","kamu buat"],["بِيُوسُفَ","dengan Yusuf"],["وَأَخِيهِ","dan abangnya"],["إِذْ","apabila"],["أَنتُمْ","kamu dahulu"],["جَـٰهِلُونَ","jahil"]]],"1686":["(Mereka berkata) sesudah mengetahuinya, ketika mereka mulai meneliti dan memperhatikan secara seksama tingkah laku raja (\"Apakah kamu ini) dapat dibaca ainnaka dan ayinnaka (benar-benar Yusuf?\" Yusuf menjawab, \"Akulah Yusuf dan ini saudaraku. Sesungguhnya telah mendapat karunia) telah memperoleh nikmat (kami dari Allah) sehingga kami dapat berkumpul. (Sesungguhnya barang siapa yang bertakwa) merasa takut kepada Allah (dan bersabar) atas apa yang menimpa dirinya (maka sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat baik.\") di dalam ungkapan ini terkandung pengertian meletakkan isim zahir pada tempat isim mudhmar.",[["قَالُوٓا۟","Mereka berkata"],["أَءِنَّكَ","Adakah kamu memang"],["لَأَنتَ","pasti kamu"],["يُوسُفُ ۖ","Yusuf"],["قَالَ","Dia berkata"],["أَنَا۠","aku"],["يُوسُفُ","Yusuf"],["وَهَـٰذَآ","dan ini"],["أَخِى ۖ","(ialah) saudara aku"],["قَدْ","Sesungguhnya"],["مَنَّ","Allah telah maha pemurah"],["ٱللَّهُ","Allah telah maha pemurah"],["عَلَيْنَآ ۖ","kepada kami"],["إِنَّهُۥ","Sesungguhnya dia"],["مَن","yang"],["يَتَّقِ","takut kepada Allah"],["وَيَصْبِرْ","dan (adalah) sabar"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُضِيعُ","biarkan pergi membazir"],["أَجْرَ","(i) ganjaran"],["ٱلْمُحْسِنِينَ","(dari) orang-orang yang berbuat baik"]]],"1687":["(Mereka berkata, \"Demi Allah, sesungguhnya telah melebihkan kamu) telah mengutamakan kamu (Allah atas kami) dengan memperoleh kerajaan dan nikmat-nikmat lainnya (dan sesungguhnya) huruf in di sini adalah bentuk takhfif daripada inna, artinya sesungguhnya (kami adalah orang-orang yang bersalah\") yakni orang-orang yang berdosa disebabkan kami telah merendahkanmu.",[["قَالُوا۟","Mereka berkata"],["تَٱللَّهِ","Demi Allah"],["لَقَدْ","sudah tentu"],["ءَاثَرَكَ","Allah telah mengutamakan kamu"],["ٱللَّهُ","Allah telah mengutamakan kamu"],["عَلَيْنَا","atas kita"],["وَإِن","dan sesungguhnya"],["كُنَّا","kami telah"],["لَخَـٰطِـِٔينَ","orang berdosa"]]],"1688":["(Yusuf berkata, \"Tidak ada cercaan) tidak ada celaan (terhadap kalian pada hari ini) kata hari ini secara khusus disebutkan, sebab celaan pasti terjadi di dalamnya akan tetapi pengertiannya menunjukkan, bahwa selainnya lebih utama lagi untuk tidak mendapatkan cercaan (mudah-mudahan Allah mengampuni kalian, dan Dia adalah Maha Penyayang di antara para penyayang.\") Lalu Nabi Yusuf menanyakan kepada mereka tentang keadaan ayahnya, mereka menjawab bahwa matanya telah rabun dan tidak dapat melihat dengan jelas lagi. Kemudian Nabi Yusuf berkata kepada mereka,",[["قَالَ","Dia berkata"],["لَا","Tidak"],["تَثْرِيبَ","salahkan"],["عَلَيْكُمُ","ke atas kamu"],["ٱلْيَوْمَ ۖ","hari ini"],["يَغْفِرُ","Allah akan mengampuni"],["ٱللَّهُ","Allah akan mengampuni"],["لَكُمْ ۖ","kamu"],["وَهُوَ","dan Dia"],["أَرْحَمُ","(adalah) Yang Maha Penyayang"],["ٱلرَّٰحِمِينَ","(dari) orang-orang yang mengasihani"]]],"1689":["(\"Pergilah kalian dengan membawa baju gamisku ini) yaitu baju gamis Nabi Ibrahim yang dipakainya sewaktu ia dicampakkan ke dalam api. Baju tersebut dikalungkan Nabi Yusuf sewaktu ia berada di dalam sumur. Baju tersebut dari surga; malaikat Jibril memerintahkan Nabi Yusuf supaya mengirimkannya kepada ayahnya, seraya berkata, 'Sesungguhnya pada baju itu terdapat bau surga, dan tidak sekali-kali ia diusapkan kepada orang yang sakit melainkan orang sakit itu akan sembuh dengan seketika (lalu letakkanlah dia ke wajah ayahku, nanti ia akan) menjadi (melihat kembali, dan bawalah keluarga kalian semuanya kepadaku.'\").",[["ٱذْهَبُوا۟","Pergi"],["بِقَمِيصِى","dengan baju aku ini"],["هَـٰذَا","dengan baju aku ini"],["فَأَلْقُوهُ","dan membuangnya"],["عَلَىٰ","atas"],["وَجْهِ","(si) muka"],["أَبِى","(dari) bapa aku"],["يَأْتِ","dia akan dapat melihat semula"],["بَصِيرًۭا","dia akan dapat melihat semula"],["وَأْتُونِى","Dan bawa kepada aku"],["بِأَهْلِكُمْ","keluarga kamu"],["أَجْمَعِينَ","semua bersama"]]],"1690":["(Tatkala kafilah itu telah keluar) dari negeri Mesir (berkata ayah mereka) kepada anak-anak dan cucu-cucunya yang ada bersamanya (\"Sesungguhnya aku mencium bau Yusuf) bau itu tercium oleh Nabi Yakub karena dibawa oleh angin berkat kekuasaan Allah dari jarak perjalanan tiga hari, atau delapan hari atau lebih dari itu (sekiranya kalian tidak menuduhku sebagai orang yang lemah akalnya.\") maka niscaya kalian akan membenarkan aku.",[["وَلَمَّا","Dan apabila"],["فَصَلَتِ","berlepas"],["ٱلْعِيرُ","karavan itu"],["قَالَ","kata ayah mereka"],["أَبُوهُمْ","kata ayah mereka"],["إِنِّى","Sesungguhnya aku"],["لَأَجِدُ","[Aku] dapati"],["رِيحَ","(yang) bau"],["يُوسُفَ ۖ","(dari) Yusuf"],["لَوْلَآ","jika tidak"],["أَن","bahawa"],["تُفَنِّدُونِ","kamu fikir aku lemah dalam fikiran"]]],"1691":["(Keluarganya berkata) kepadanya (Demi Allah, sesungguhnya engkau masih dalam kekeliruanmu) kesalahanmu (yang dahulu) disebabkan kecintaanmu yang berlebihan terhadap Yusuf, dan harapanmu yang selalu tak padam untuk bersua kembali dengannya sekali pun sudah lama masanya.",[["قَالُوا۟","Mereka berkata"],["تَٱللَّهِ","Demi Allah"],["إِنَّكَ","sesungguhnya, kamu"],["لَفِى","pasti (berada) dalam"],["ضَلَـٰلِكَ","kesilapan kamu"],["ٱلْقَدِيمِ","lama"]]],"1692":["(Tatkala) huruf an di sini adalah zaidah (telah tiba pembawa kabar gembira) yaitu Yahudza dengan membawa baju gamis Nabi Yusuf. Dahulu dialah yang membawa baju darah Nabi Yusuf, maka kali ini ia bermaksud untuk membuat bahagia ayahnya sebagai ganti daripada perbuatannya dahulu yang membuatnya sedih (maka diletakannya baju gamis itu) ditaruhnya baju gamis itu (ke wajah Yakub, lalu kembalilah) sehat seperti semula (dapat melihat. Berkata Yakub, \"Tidakkah aku katakan kepada kalian, bahwa aku mengetahui dari Allah apa yang kalian tidak mengetahuinya.\")",[["فَلَمَّآ","Kemudian apabila"],["أَن","[bahawa]"],["جَآءَ","tiba"],["ٱلْبَشِيرُ","pembawa berita gembira"],["أَلْقَىٰهُ","dia melemparkannya"],["عَلَىٰ","atas"],["وَجْهِهِۦ","mukanya"],["فَٱرْتَدَّ","maka kembalilah penglihatannya"],["بَصِيرًۭا ۖ","maka kembalilah penglihatannya"],["قَالَ","Dia berkata"],["أَلَمْ","tidak"],["أَقُل","aku cakap"],["لَّكُمْ","kepada kamu"],["إِنِّىٓ","sesungguhnya, aku"],["أَعْلَمُ","[Aku] tahu"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"1693":["(Mereka berkata, \"Wahai ayah kami, mohonkanlah ampun bagi kami terhadap dosa-dosa kami, sesungguhnya kami adalah orang-orang yang bersalah.\")",[["قَالُوا۟","Mereka berkata"],["يَـٰٓأَبَانَا","Wahai ayah kami"],["ٱسْتَغْفِرْ","Minta ampun"],["لَنَا","bagi kami"],["ذُنُوبَنَآ","(dari) dosa-dosa kita"],["إِنَّا","Sesungguhnya kami"],["كُنَّا","telah"],["خَـٰطِـِٔينَ","orang berdosa"]]],"1694":["(Yakub berkata, \"Aku akan memohonkan ampun bagi kalian kepada Rabbku. Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang.\") Nabi Yakub mengakhirkan atau menangguhkan doanya itu sampai dengan waktu sahur, dimaksud supaya lebih dekat untuk diperkenankan. Atau doanya itu ia tangguhkan sampai dengan malam Jumat. Kemudian mereka semua berangkat menuju ke negeri Mesir; dan Nabi Yusuf beserta pembesar-pembesar negeri Mesir lainnya keluar untuk menjemput kedatangan mereka.",[["قَالَ","Dia berkata"],["سَوْفَ","Tidak lama lagi"],["أَسْتَغْفِرُ","Aku akan meminta ampun"],["لَكُمْ","bagi kamu"],["رَبِّىٓ ۖ","(dari) Tuhanku"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","Dia"],["ٱلْغَفُورُ","(ialah) Yang Maha Pengampun"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"1695":["(Maka tatkala mereka masuk ke tempat Yusuf) yaitu ke kemah Nabi Yusuf (Yusuf merangkul) memeluk (ibu-bapaknya) kedua orang tuanya atau bapak dan bibinya (dan dia berkata) kepada mereka (\"Masuklah kalian ke negeri Mesir dalam keadaan aman.\") lalu mereka memasuki negeri Mesir dan Nabi Yusuf lalu duduk di atas singgasananya.",[["فَلَمَّا","Kemudian apabila"],["دَخَلُوا۟","mereka masuk"],["عَلَىٰ","ke atas"],["يُوسُفَ","Yusuf"],["ءَاوَىٰٓ","dia ambil"],["إِلَيْهِ","kepada dirinya sendiri"],["أَبَوَيْهِ","ibu bapanya"],["وَقَالَ","dan berkata"],["ٱدْخُلُوا۟","Masuk"],["مِصْرَ","Mesir"],["إِن","jika"],["شَآءَ","Allah berkehendak"],["ٱللَّهُ","Allah berkehendak"],["ءَامِنِينَ","selamat"]]],"1696":["(Dan ia menaikkan kedua ibu-bapaknya) yakni Yusuf mendudukkan kedua orang tuanya sejajar dengannya (ke atas singgasananya.) tempat duduknya (Dan mereka merebahkan diri) yakni kedua orang tuanya dan semua saudara-saudaranya (kepada Yusuf seraya bersujud) yang dimaksud adalah sujud dengan membungkukkan badan bukannya sujud dalam arti kata meletakkan kening; cara itu merupakan penghormatan yang berlaku pada zamannya. (Dan berkata Yusuf, \"Wahai ayahku! Inilah takwil mimpiku yang dahulu itu, sesungguhnya Rabbku telah menjadikannya suatu kenyataan. Dan sesungguhnya Rabbku telah berbuat baik kepadaku) terhadap diriku (ketika Dia membebaskan aku dari rumah penjara) Nabi Yusuf tidak menyinggung masalah sumur, hal ini sengaja ia lakukan demi menghormati saudara-saudaranya supaya mereka tidak malu (dan ketika membawa kalian dari dusun padang pasir) dari kampung padang pasir (setelah dirusak) dikacaukan (oleh setan hubungan antara aku dan saudara-saudaraku. Sesungguhnya Rabbku Maha Lembut terhadap apa yang Dia kehendaki. Sesungguhnya Dialah Yang Maha Mengetahui) tentang makhluk-Nya (lagi Maha Bijaksana.\") di dalam pekerjaan-Nya. Kemudian ayah Nabi Yusuf (Yakub) bermukim bersama Yusuf selama dua puluh empat tahun atau tujuh belas tahun. Disebutkan bahwa masa perpisahan mereka delapan belas tahun lamanya atau empat puluh tahun atau delapan puluh tahun. Kemudian Nabi Yakub menjelang ajalnya, sebelum itu ia berwasiat kepada Nabi Yusuf supaya ia dikebumikan di dekat ayahnya, yaitu Nabi Ishak. Lalu Nabi Yusuf membawa jenazah ayahnya ke tempat yang diisyaratkannya dalam wasiat dan mengebumikannya di tempat tersebut. Setelah itu Nabi Yusuf kembali ke Mesir dan ia tinggal di negeri itu sesudah Nabi Yakub meninggal dunia selama dua puluh tiga tahun. Ketika urusannya telah sempurna kemudian ia mengetahui bahwa dirinya tidak akan abadi dalam keadaan demikian lalu hatinya menginginkan agar ia hijrah ke kerajaan yang abadi, yakni akhirat. Untuk itu berkata seraya berdoa:",[["وَرَفَعَ","Dan dia bangkitkan"],["أَبَوَيْهِ","ibu bapanya"],["عَلَى","ke atas"],["ٱلْعَرْشِ","takhta"],["وَخَرُّوا۟","dan mereka jatuh"],["لَهُۥ","kepadanya"],["سُجَّدًۭا ۖ","sujud"],["وَقَالَ","Dan dia berkata"],["يَـٰٓأَبَتِ","Wahai ayahku"],["هَـٰذَا","Ini"],["تَأْوِيلُ","(ialah) tafsiran"],["رُءْيَـٰىَ","(dari) impian aku"],["مِن","(daripada) sebelum ini"],["قَبْلُ","(daripada) sebelum ini"],["قَدْ","Sesungguhnya"],["جَعَلَهَا","telah berjaya"],["رَبِّى","Tuhanku"],["حَقًّۭا ۖ","benar"],["وَقَدْ","Dan sesungguhnya"],["أَحْسَنَ","Dia baik"],["بِىٓ","kepada aku"],["إِذْ","apabila"],["أَخْرَجَنِى","Dia membawa aku keluar"],["مِنَ","daripada"],["ٱلسِّجْنِ","penjara itu"],["وَجَآءَ","dan dibawa"],["بِكُم","kamu"],["مِّنَ","daripada"],["ٱلْبَدْوِ","kehidupan badwi"],["مِنۢ","selepas"],["بَعْدِ","selepas"],["أَن","[bahawa]"],["نَّزَغَ","telah menimbulkan perselisihan"],["ٱلشَّيْطَـٰنُ","syaitan"],["بَيْنِى","antara aku"],["وَبَيْنَ","dan antara"],["إِخْوَتِىٓ ۚ","saudara-saudaraku"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["لَطِيفٌۭ","(adalah) Maha Halus"],["لِّمَا","ke apa"],["يَشَآءُ ۚ","Dia kehendaki"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","Dia"],["ٱلْعَلِيمُ","(ialah) Yang Maha Mengetahui"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"1697":["(Ya Rabbku! Sesungguhnya Engkau telah menganugerahkan kepadaku sebagian kerajaan dan telah mengajarkan kepadaku sebagian takbir mimpi) takwil-takwil mimpi (Ya Rabb Pencipta) yang menjadikan (langit dan bumi! Engkaulah Pelindungku) yang mengatur kebaikanku (di dunia dan di akhirat, wafatkanlah aku dalam keadaan Islam dan kumpulkanlah aku dengan orang-orang yang saleh) di antara bapak moyangku. Maka setelah ia berdoa, ia hidup hanya seminggu atau lebih dari seminggu. Kemudian ia wafat, pada saat itu usianya telah mencapai seratus dua puluh tahun. Lalu semua orang Mesir mengiringkan jenazahnya sampai ke tempat kuburannya; mereka meletakkan jenazah Nabi Yusuf di dalam sebuah tabelah yang terbuat dari marmer, dan mereka mengebumikannya di tempat yang terletak di antara kedua tepi sungai Nil, dimaksud supaya keberkahan terlimpahkan kepada kedua tepi sungai Nil. Maha Suci Allah yang tiada akhir bagi kerajaan-Nya.",[["۞ رَبِّ","Tuhanku"],["قَدْ","sesungguhnya"],["ءَاتَيْتَنِى","kamu telah berikan aku"],["مِنَ","daripada"],["ٱلْمُلْكِ","kedaulatan"],["وَعَلَّمْتَنِى","dan mengajar aku"],["مِن","daripada"],["تَأْوِيلِ","tafsiran itu"],["ٱلْأَحَادِيثِ ۚ","daripada peristiwa tersebut"],["فَاطِرَ","Pencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["أَنتَ","kamu"],["وَلِىِّۦ","(adalah) Pelindungku"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["وَٱلْـَٔاخِرَةِ ۖ","dan akhirat"],["تَوَفَّنِى","Menyebabkan aku mati"],["مُسْلِمًۭا","(sebagai) seorang Muslim"],["وَأَلْحِقْنِى","dan sertai aku"],["بِٱلصَّـٰلِحِينَ","dengan orang yang soleh"]]],"1698":["(Demikian itu) hal yang telah disebutkan itu menyangkut kisah tentang Nabi Yusuf (di antara berita-berita yang gaib) kisah-kisah yang tidak diketahui olehmu hai Muhammad sebelumnya (yang Kami wahyukan kepadamu padahal kamu tidak berada pada sisi mereka) yang dimaksud adalah saudara-saudara Nabi Yusuf (ketika mereka memutuskan rencananya) untuk berbuat makar terhadap Nabi Yusuf, yaitu memasukkannya ke dalam sumur (dan mereka sedang mengatur tipu daya) terhadap Nabi Yusuf. Artinya engkau tidak hadir bersama mereka, maka bagaimana engkau dapat mengetahui kisah mereka lalu engkau menceritakannya, tetapi hal ini hanya dapat kamu ketahui melalui wahyu.",[["ذَٰلِكَ","Itu"],["مِنْ","(adalah) daripada"],["أَنۢبَآءِ","berita itu"],["ٱلْغَيْبِ","(dari) yang ghaib"],["نُوحِيهِ","yang Kami nyatakan"],["إِلَيْكَ ۖ","kepada kamu"],["وَمَا","Dan tidak"],["كُنتَ","kamu dahulu"],["لَدَيْهِمْ","bersama mereka"],["إِذْ","apabila"],["أَجْمَعُوٓا۟","mereka susun bersama"],["أَمْرَهُمْ","rancangan mereka"],["وَهُمْ","sedangkan mereka"],["يَمْكُرُونَ","(sedang) merancang"]]],"1699":["(Dan tiadalah sebagian besar manusia) yang dimaksud adalah penduduk kota Mekah (walaupun kamu sangat menginginkannya) menginginkan mereka supaya mau beriman (akan beriman).",[["وَمَآ","Dan tidak"],["أَكْثَرُ","kebanyakannya"],["ٱلنَّاسِ","(dari) manusia"],["وَلَوْ","walaupun"],["حَرَصْتَ","kamu inginkan"],["بِمُؤْمِنِينَ","(akan) beriman"]]],"1700":["(Dan kamu sekali-kali tidak meminta kepada mereka atas seruanmu) yakni Alquran (suatu upah pun) yang kamu ambil sebagai imbalannya (Tidak lain) (ia) yakni Alquran (hanyalah pengajaran) nasihat (bagi semesta alam).",[["وَمَا","Dan tidak"],["تَسْـَٔلُهُمْ","kamu bertanya kepada mereka"],["عَلَيْهِ","baginya"],["مِنْ","sebarang"],["أَجْرٍ ۚ","pahala"],["إِنْ","Tidak"],["هُوَ","(adalah) ia"],["إِلَّا","tetapi"],["ذِكْرٌۭ","peringatan"],["لِّلْعَـٰلَمِينَ","kepada dunia"]]],"1701":["(Dan banyak sekali) sudah berapa banyak (tanda-tanda) yang menunjukkan keesaan Allah (di langit dan di bumi yang mereka melaluinya) artinya mereka menyaksikannya (sedangkan mereka berpaling daripadanya.) tidak mau memikirkan tentangnya.",[["وَكَأَيِّن","Dan berapa banyak"],["مِّنْ","daripada"],["ءَايَةٍۢ","sebuah Tanda"],["فِى","dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["يَمُرُّونَ","mereka lulus"],["عَلَيْهَا","atasnya"],["وَهُمْ","sedangkan mereka"],["عَنْهَا","(adalah) daripada mereka"],["مُعْرِضُونَ","mereka yang berpaling"]]],"1702":["(Dan sebagian besar dari mereka tidak beriman kepada Allah) mereka tidak mau mengakui bahwa Allah adalah Yang Menciptakan dan Yang Memberi rezeki (melainkan dalam keadaan mempersekutukan) Allah melalui penyembahan mereka kepada berhala-berhala. Oleh karenanya mereka mengatakan di dalam seruan-seruan mereka, \"Kupenuhi seruan-Mu; tiada sekutu bagi-Mu kecuali sekutu yang bagi-Mu; Kamu memilikinya akan tetapi dia tidak memiliki.\" Yang mereka maksud adalah berhala-berhala yang mereka sembah itu.",[["وَمَا","Dan tidak"],["يُؤْمِنُ","beriman"],["أَكْثَرُهُم","kebanyakan mereka"],["بِٱللَّهِ","kepada Allah"],["إِلَّا","kecuali"],["وَهُم","sedangkan mereka"],["مُّشْرِكُونَ","mempersekutukan-Nya"]]],"1703":["(Apakah mereka merasa aman dari kedatangan pembalasan) yang meliputi mereka semuanya (berupa siksa Allah atau kedatangan kiamat kepada mereka secara mendadak) secara tiba-tiba (sedang mereka tidak menyadarinya?) sebelumnya akan kedatangan hari kiamat itu.",[["أَفَأَمِنُوٓا۟","Adakah mereka kemudian berasa selamat"],["أَن","(menentang) itu"],["تَأْتِيَهُمْ","datang kepada mereka"],["غَـٰشِيَةٌۭ","yang amat menggembirakan"],["مِّنْ","[daripada]"],["عَذَابِ","hukuman"],["ٱللَّهِ","(milik) Allah"],["أَوْ","atau"],["تَأْتِيَهُمُ","datang kepada mereka"],["ٱلسَّاعَةُ","Jam itu"],["بَغْتَةًۭ","tiba-tiba"],["وَهُمْ","sedangkan mereka"],["لَا","jangan"],["يَشْعُرُونَ","mempersepsikan"]]],"1704":["(Katakanlah) kepada mereka (\"Inilah jalanku) pengertian jalan di sini dijelaskan oleh firman berikutnya; yaitu: (aku mengajak kepada) agama (Allah dengan hujah yang nyata) hujah yang jelas lagi gamblang (yaitu aku dan orang-orang yang mengikutiku) orang-orang yang beriman kepadaku. Lafal man diathafkan kepada lafal ana yang berkedudukan menjadi mubtada daripada khabar yang disebutkan sebelumnya (Maha Suci Allah) kalimat ini dimaksud mensucikan Allah daripada semua jenis sekutu (dan aku tiada termasuk orang-orang yang musyrik.\") kalimat ini termasuk ke dalam rangkaian keterangan daripada lafal sabiilii di atas.",[["قُلْ","Katakanlah"],["هَـٰذِهِۦ","Ini"],["سَبِيلِىٓ","(adalah) cara aku"],["أَدْعُوٓا۟","aku jemput"],["إِلَى","kepada"],["ٱللَّهِ ۚ","Allah"],["عَلَىٰ","dengan"],["بَصِيرَةٍ","wawasan"],["أَنَا۠","aku"],["وَمَنِ","dan sesiapa"],["ٱتَّبَعَنِى ۖ","mengikut aku"],["وَسُبْحَـٰنَ","Dan Maha Suci"],["ٱللَّهِ","(kepada) Allah"],["وَمَآ","dan bukan"],["أَنَا۠","aku"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"1705":["(Kami tidak mengutus sebelum kamu melainkan orang laki-laki yang Kami berikan wahyu) dan menurut suatu qiraat dibaca yuuhaa; artinya yang diberikan wahyu (kepada mereka) bukannya malaikat (di antara penduduk negeri) yakni penduduk kota-kota, sebab penduduk kota lebih mengetahui dan lebih menyantun, berbeda halnya dengan penduduk kampung yang terkenal dengan kekasaran sikap mereka dan kebodohannya itu (Maka tidaklah mereka bepergian) yang dimaksud adalah penduduk Mekah (di muka bumi lalu melihat bagaimana kesudahan orang-orang sebelum mereka) akibat daripada perbuatan mereka yang mendustakan rasul-rasul mereka, yaitu mereka dibinasakan (dan sesungguhnya kampung akhirat) yakni surga Allah (lebih baik bagi orang-orang yang bertakwa) kepada Allah (Maka tidakkah kalian memikirkannya?) hai penduduk Mekah, lalu kalian menjadi beriman karenanya. Lafal ta`qiluuna dapat pula dibaca ya`qiluuna yang artinya apakah mereka tidak memikirkannya?",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["مِن","sebelum kamu"],["قَبْلِكَ","sebelum kamu"],["إِلَّا","tetapi"],["رِجَالًۭا","lelaki"],["نُّوحِىٓ","Kami mendedahkan"],["إِلَيْهِم","kepada mereka"],["مِّنْ","daripada (antara)"],["أَهْلِ","kaum"],["ٱلْقُرَىٰٓ ۗ","(dari) perbandaran"],["أَفَلَمْ","Jadi belum"],["يَسِيرُوا۟","mereka mengembara"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَيَنظُرُوا۟","dan dilihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum mereka"],["قَبْلِهِمْ ۗ","(ada) sebelum mereka"],["وَلَدَارُ","Dan pastinya rumah"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["خَيْرٌۭ","(adalah) terbaik"],["لِّلَّذِينَ","bagi mereka yang"],["ٱتَّقَوْا۟ ۗ","takut kepada Allah"],["أَفَلَا","Kemudian tidak akan"],["تَعْقِلُونَ","kamu menggunakan alasan"]]],"1706":["(Sehingga) lafal hattaa menunjukkan makna batas atau limit waktu daripada pengertian yang terkandung di dalam firman-Nya, \"Kami tidak mengutus sebelum kalian melainkan seorang laki-laki...\" Artinya: Maka Allah menangguhkan pertolongan-Nya terhadap mereka hingga (bila merasa putus asa) putus harapan (para rasul itu dan mereka telah menyakini) para rasul itu merasa yakin (bahwasanya mereka benar-benar telah didustakan) sungguh-sungguh didustakan sehingga mereka tidak dapat diharapkan lagi untuk beriman; makna ini dibaca kudzdzibuu. Bila dibaca kudzibuu tanpa memakai tasydid, artinya umat-umat tersebut merasa yakin bahwa para rasul telah mengingkari ancaman yang telah mereka berikan kepadanya, yaitu mendapat pertolongan dari Allah (maka datanglah pertolongan Kami kepada mereka lalu Kami selamatkan) dibaca dengan memakai dua huruf nun yang pertama dibaca takhfif sedang yang kedua dibaca tasydid, atau dibaca nujjiya menjadi fi`il madhi (orang-orang yang Kami kehendaki. Dan tidak dapat ditolak siksa Kami) azab Kami (daripada orang-orang yang berdosa.) yakni orang-orang musyrik.",[["حَتَّىٰٓ","Sehinggalah"],["إِذَا","apabila"],["ٱسْتَيْـَٔسَ","putus harapan"],["ٱلرُّسُلُ","para Rasul"],["وَظَنُّوٓا۟","dan berfikir"],["أَنَّهُمْ","bahawa mereka"],["قَدْ","sudah tentu"],["كُذِبُوا۟","telah dinafikan"],["جَآءَهُمْ","kemudian datang kepada mereka"],["نَصْرُنَا","Bantuan kami"],["فَنُجِّىَ","dan telah diselamatkan"],["مَن","yang"],["نَّشَآءُ ۖ","Kami berkehendak"],["وَلَا","Dan tidak"],["يُرَدُّ","(boleh) ditolak"],["بَأْسُنَا","hukuman kita"],["عَنِ","daripada"],["ٱلْقَوْمِ","manusia"],["ٱلْمُجْرِمِينَ","(yang) penjenayah"]]],"1707":["(Sesungguhnya pada kisah mereka itu terdapat) yang dimaksud adalah kisah-kisah para rasul (pengajaran bagi orang-orang yang mempunyai akal) orang-orang yang berakal (Ini bukanlah) Alquran ini bukanlah (cerita yang dibuat-buat) sengaja dibuat-buat (akan tetapi) tetapi (membenarkan kitab-kitab yang sebelumnya) kitab-kitab yang diturunkan sebelum Alquran (dan menjelaskan) menerangkan (segala sesuatu) yang diperlukan dalam agama (dan sebagai petunjuk) dari kesesatan (dan rahmat bagi kaum yang beriman) mereka disebutkan secara khusus dalam ayat ini mengingat hanya mereka sajalah yang dapat mengambil manfaat Alquran bukan orang-orang selain mereka.",[["لَقَدْ","Sesungguhnya"],["كَانَ","(ada) ada"],["فِى","dalam"],["قَصَصِهِمْ","cerita mereka"],["عِبْرَةٌۭ","satu pengajaran"],["لِّأُو۟لِى","untuk lelaki"],["ٱلْأَلْبَـٰبِ ۗ","(dari) pemahaman"],["مَا","Tidak"],["كَانَ","(ia) ialah"],["حَدِيثًۭا","sebuah penceritaan"],["يُفْتَرَىٰ","dicipta"],["وَلَـٰكِن","tetapi"],["تَصْدِيقَ","pengesahan"],["ٱلَّذِى","(daripada itu) yang"],["بَيْنَ","(ada) sebelum itu"],["يَدَيْهِ","(ada) sebelum itu"],["وَتَفْصِيلَ","dan penerangan terperinci"],["كُلِّ","(dari) semua"],["شَىْءٍۢ","benda"],["وَهُدًۭى","dan hidayah"],["وَرَحْمَةًۭ","dan belas kasihan"],["لِّقَوْمٍۢ","bagi kaum"],["يُؤْمِنُونَ","yang beriman"]]],"1708":["(Alif laam raa) hanya Allahlah yang mengetahui maksudnya (Ini adalah) ayat-ayat ini (sebagian dari Alkitab) yakni Alquran; idhafat mengandung makna min, yaitu bermakna sebagian (Dan kitab yang diturunkan kepadamu dari Rabbmu itu) maksudnya Alquran. Kalimat ayat ini berkedudukan menjadi mubtada sedangkan khabarnya ialah (adalah benar) tiada keraguan di dalamnya (akan tetapi kebanyakan manusia) yakni penduduk kota Mekah (tidak beriman) bahwasanya Alquran itu dari sisi Allah swt.",[["الٓمٓر ۚ","Alif Laam Mim Ra"],["تِلْكَ","Ini"],["ءَايَـٰتُ","(adalah) ayat-ayat"],["ٱلْكِتَـٰبِ ۗ","Kitab"],["وَٱلَّذِىٓ","Dan yang"],["أُنزِلَ","telah didedahkan"],["إِلَيْكَ","kepada kamu"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["ٱلْحَقُّ","(adalah) kebenaran"],["وَلَـٰكِنَّ","tetapi"],["أَكْثَرَ","kebanyakannya"],["ٱلنَّاسِ","(dari) manusia"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"1709":["(Allahlah yang meninggikan langit tanpa tiang sebagaimana yang kalian lihat) lafal `amad merupakan bentuk jamak dari kata tunggal `imaad, yang artinya ialah tiang penyanggah. Dan memang sebagaimana yang terlihat langit itu tidak mempunyai tiang penyanggah (kemudian Dia berkuasa di atas Arsy) dalam arti kata kekuasaan yang layak bagi keagungan-Nya (dan menundukkan) menjinakkan (matahari dan bulan. Masing-masing) daripada matahari dan bulan itu (beredar) pada garis edarnya (hingga waktu yang ditentukan) yaitu hari kiamat. (Allah mengatur semua urusan) yakni memutuskan semua perkara kerajaan-Nya (menjelaskan) menerangkan (tanda-tanda) yang menunjukkan akan kekuasaan-Nya (supaya kalian) hai penduduk kota Mekah (terhadap hari pertemuan dengan Rabb kalian) melalui hari berbangkit (meyakininya).",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(ialah) Yang"],["رَفَعَ","dinaikkan"],["ٱلسَّمَـٰوَٰتِ","langit"],["بِغَيْرِ","tanpa"],["عَمَدٍۢ","tiang"],["تَرَوْنَهَا ۖ","yang kamu lihat"],["ثُمَّ","kemudian"],["ٱسْتَوَىٰ","Dia menubuhkan"],["عَلَى","pada"],["ٱلْعَرْشِ ۖ","takhta"],["وَسَخَّرَ","dan tertakluk"],["ٱلشَّمْسَ","matahari"],["وَٱلْقَمَرَ ۖ","dan bulan"],["كُلٌّۭ","setiap satu"],["يَجْرِى","berlari"],["لِأَجَلٍۢ","untuk satu penggal"],["مُّسَمًّۭى ۚ","dilantik"],["يُدَبِّرُ","Dia mengatur"],["ٱلْأَمْرَ","perkara itu"],["يُفَصِّلُ","Dia perincikan"],["ٱلْـَٔايَـٰتِ","Tanda-tanda"],["لَعَلَّكُم","supaya kamu"],["بِلِقَآءِ","dalam mesyuarat tersebut"],["رَبِّكُمْ","(dengan) Tuhanmu"],["تُوقِنُونَ","beriman dengan pasti"]]],"1710":["(Dan Dialah yang membentangkan) menghamparkan (bumi dan menjadikan) membuat (gunung-gunung padanya) gunung-gunung yang kokoh (dan sungai-sungai. Dan menjadikan padanya semua buah-buahan berpasang-pasangan) dari setiap jenis yang ada (Allah menutupkan) menutup (malam) dengan kegelapannya (kepada siang. Sesungguhnya pada yang demikian itu) dalam hal yang telah disebutkan itu (terdapat tanda-tanda) bukti-bukti yang menunjukkan akan keesaan Allah swt. (bagi kaum yang memikirkan) tentang ciptaan Allah.",[["وَهُوَ","Dan Dia"],["ٱلَّذِى","(ialah) Yang"],["مَدَّ","merebak"],["ٱلْأَرْضَ","bumi"],["وَجَعَلَ","dan diletakkan"],["فِيهَا","di dalamnya"],["رَوَٰسِىَ","gunung yang kukuh"],["وَأَنْهَـٰرًۭا ۖ","dan sungai"],["وَمِن","dan daripada"],["كُلِّ","semua"],["ٱلثَّمَرَٰتِ","(dari) buah-buahan"],["جَعَلَ","Dia buat"],["فِيهَا","di dalamnya"],["زَوْجَيْنِ","berpasangan"],["ٱثْنَيْنِ ۖ","dua"],["يُغْشِى","Dia meliputi"],["ٱلَّيْلَ","malam"],["ٱلنَّهَارَ ۚ","(dengan) hari itu"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَتَفَكَّرُونَ","yang merenung"]]],"1711":["(Dan di bumi terdapat bagian-bagian) berbagai macam daerah (yang berdampingan) yang saling berdekatan; di antaranya ada yang subur dan ada yang tandus; dan di antaranya lagi ada yang kekurangan air dan yang banyak airnya; hal ini merupakan bukti-bukti yang menunjukkan kepada kekuasaan-Nya (dan kebun-kebun) ladang-ladang (anggur, tanam-tanaman) dibaca rafa', yaitu zar'un karena diathafkan kepada lafal jannatun. Kalau dibaca jar, yaitu zar'in diathafkan kepada lafal a'naabin, demikian pula firman-Nya: (dan pohon kurma yang bercabang) lafal shinwaanun adalah bentuk jamak dari kata tunggal shinwun, artinya pohon kurma yang banyak cabangnya (dan yang tidak bercabang) pohon kurma yang tidak banyak cabangnya (disirami) kalau dibaca tusqaa, artinya kebun-kebun dan pohon-pohon yang ada padanya disirami. Dan kalau dibaca yusqa, artinya hal tersebut disirami (dengan air yang sama. Kami melebihkan) dapat dibaca nufadhdhilu dan yufadhdhilu (sebagian tanam-tanaman itu atas sebagian yang lain tentang rasanya) dapat dibaca al-ukuli dan al-ukli, artinya dalam hal rasa; yaitu ada yang manis dan ada yang masam. Hal ini merupakan tanda yang menunjukkan kepada kekuasaan Allah swt. (Sesungguhnya pada yang demikian itu) dalam hal tersebut (terdapat tanda-tanda bagi kaum yang berpikir) yaitu bagi orang-orang yang mau memikirkannya.",[["وَفِى","Dan dalam"],["ٱلْأَرْضِ","bumi"],["قِطَعٌۭ","adalah trek"],["مُّتَجَـٰوِرَٰتٌۭ","jiran"],["وَجَنَّـٰتٌۭ","dan taman-taman"],["مِّنْ","daripada"],["أَعْنَـٰبٍۢ","pokok anggur"],["وَزَرْعٌۭ","dan tanaman"],["وَنَخِيلٌۭ","dan kurma"],["صِنْوَانٌۭ","pokok (tumbuh) daripada satu akar"],["وَغَيْرُ","dan bukan"],["صِنْوَانٍۢ","pokok (tumbuh) daripada satu akar"],["يُسْقَىٰ","disiram"],["بِمَآءٍۢ","dengan air"],["وَٰحِدٍۢ","satu"],["وَنُفَضِّلُ","tetapi Kami lebihkan"],["بَعْضَهَا","sebahagian mereka"],["عَلَىٰ","atas"],["بَعْضٍۢ","yang lain"],["فِى","dalam"],["ٱلْأُكُلِ ۚ","buah itu"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tanda"],["لِّقَوْمٍۢ","bagi kaum"],["يَعْقِلُونَ","yang menggunakan akal"]]],"1712":["(Dan jika kamu merasa heran) hai Muhammad, tentang pendustaan yang dilakukan oleh orang-orang kafir terhadap dirimu (maka yang patut mengherankan) lebih berhak untuk ditakjubi (adalah ucapan mereka) orang-orang yang mengingkari adanya hari berbangkit (\"Apabila kami telah menjadi tanah, apakah kami sesungguhnya akan menjadi makhluk yang baru?\") karena sesungguhnya Dzat yang mampu menciptakan makhluk dan hal-hal yang telah disebutkan tadi yang tanpa tandingan mampu pula untuk mengembalikan mereka menjadi hidup kembali. Sehubungan dengan kedua huruf hamzah pada dua tempat dalam ayat ini, yaitu a-idzaa dan a-innaa dengan menyebutkan secara jelas keduanya. Dan dapat pula dibaca secara nyata pada yang pertama sedangkan pada yang kedua diringankan kemudian dimasukkan huruf alif di antara keduanya sebagaimana boleh pula huruf alif tidak dimasukkan. Akan tetapi menurut suatu qiraat, pada tempat yang pertama memakai huruf istifham sehingga menjadi a-idzaa sedangkan pada yang kedua dibaca dalam bentuk kalimat berita sehingga bacaannya menjadi innaa lafii khalqin jadiid. Dan menurut qiraat yang lainnya lagi dibaca secara kebalikannya sehingga menjadi idzaa kunnaa turaaban a-innaa lafii khalqin jadiid (orang-orang itulah yang kafir kepada Rabb mereka dan orang-orang itulah yang diletakkan belenggu di lehernya; mereka itulah penghuni neraka, mereka kekal di dalamnya.)",[["۞ وَإِن","Dan jika"],["تَعْجَبْ","kamu (terkejut)."],["فَعَجَبٌۭ","kemudian menakjubkan"],["قَوْلُهُمْ","(adalah) perkataan mereka"],["أَءِذَا","Apabila"],["كُنَّا","kita"],["تُرَٰبًا","habuk"],["أَءِنَّا","akan kita"],["لَفِى","(jadi) sesungguhnya, dalam"],["خَلْقٍۢ","sebuah ciptaan"],["جَدِيدٍ ۗ","baru"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["كَفَرُوا۟","kufur"],["بِرَبِّهِمْ ۖ","pada Tuhan mereka"],["وَأُو۟لَـٰٓئِكَ","dan mereka"],["ٱلْأَغْلَـٰلُ","rantai besi itu"],["فِىٓ","(akan) masuk"],["أَعْنَاقِهِمْ ۖ","leher mereka"],["وَأُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلنَّارِ ۖ","(dari) api"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"1713":["Ayat ini diturunkan berkenaan dengan permintaan mereka yang menginginkan disegerakannya azab; mereka kemukakan hal ini dengan nada mengejek (Mereka meminta kepadamu supaya disegerakan datangnya keburukan) yakni azab (sebelum mereka meminta kebaikan) rahmat (padahal telah terjadi bermacam-macam contoh siksa sebelum mereka) lafal matsulaat merupakan bentuk jamak dari kata tunggal al-matslah dengan wazan ats-tsamrah; artinya siksaan-siksaan yang telah menimpa orang-orang seperti mereka dari kalangan orang-orang yang mendustakan. Mengapa mereka tidak mengambil pelajaran daripadanya? (Dan sesungguhnya Rabbmu benar-benar mempunyai ampunan yang luas bagi manusia sekali pun) walaupun (mereka zalim) dan jika tidak demikian, niscaya tidak akan tersisa di permukaan bumi ini makhluk yang melata di atasnya. (Dan sesungguhnya Rabbmu benar-benar sangat keras siksaan-Nya) terhadap orang-orang yang durhaka kepada-Nya.",[["وَيَسْتَعْجِلُونَكَ","Dan mereka meminta kamu untuk menyegerakan"],["بِٱلسَّيِّئَةِ","yang jahat"],["قَبْلَ","sebelum"],["ٱلْحَسَنَةِ","yang baik"],["وَقَدْ","dan sesungguhnya"],["خَلَتْ","telah berlaku"],["مِن","daripada"],["قَبْلِهِمُ","sebelum mereka"],["ٱلْمَثُلَـٰتُ ۗ","[the] hukuman yang serupa"],["وَإِنَّ","Dan sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لَذُو","(ada) penuh"],["مَغْفِرَةٍۢ","(dari) pengampunan"],["لِّلنَّاسِ","untuk manusia"],["عَلَىٰ","bagi"],["ظُلْمِهِمْ ۖ","kesalahan mereka"],["وَإِنَّ","dan sesungguhnya"],["رَبَّكَ","Tuhanmu"],["لَشَدِيدُ","(adalah) teruk"],["ٱلْعِقَابِ","(dalam) penalti"]]],"1714":["(Orang-orang yang kafir berkata, \"Mengapa tidak) (diturunkan kepadanya) yakni kepada Muhammad (suatu tanda dari Rabbnya?\") yakni mukjizat, seperti tongkat dan tangannya Nabi Musa, dan seperti untanya Nabi Saleh. Maka Allah berfirman, (\"Sesungguhnya kamu hanyalah seorang pemberi peringatan) juru peringat bagi orang-orang yang kafir; dan tugasmu bukanlah untuk mendatangkan mukjizat-mukjizat (dan bagi tiap-tiap kaum ada orang yang memberi petunjuk\") seorang nabi yang mengajak mereka untuk menyembah Rabb mereka dengan membawa mukjizat-mukjizat yang telah diberikan oleh-Nya, bukannya mukjizat-mukjiat seperti apa yang orang-orang kafir minta.",[["وَيَقُولُ","Dan katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَوْلَآ","kenapa tidak"],["أُنزِلَ","telah diturunkan"],["عَلَيْهِ","kepadanya"],["ءَايَةٌۭ","satu tanda"],["مِّن","daripada"],["رَّبِّهِۦٓ ۗ","Tuhannya"],["إِنَّمَآ","Hanya"],["أَنتَ","kamu"],["مُنذِرٌۭ ۖ","(adalah) pemberi amaran"],["وَلِكُلِّ","dan untuk setiap"],["قَوْمٍ","orang ramai"],["هَادٍ","(adalah) panduan"]]],"1715":["(Allah mengetahui apa yang dikandung oleh setiap perempuan) apakah ia laki-laki atau perempuan, dan apakah kandungan itu berisi satu atau kembar dan lain sebagainya (dan apa yang kurang sempurna) kekurangan (pada kandungan rahim) tentang masa kandungan (dan apa yang lebih) daripada masa kandungan itu. (Dan segala sesuatu pada sisi-Nya ada ukurannya) menurut kadar dan ukuran yang tidak berlebihan.",[["ٱللَّهُ","Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["تَحْمِلُ","membawa"],["كُلُّ","setiap"],["أُنثَىٰ","perempuan"],["وَمَا","dan apa"],["تَغِيضُ","jatuh pendek"],["ٱلْأَرْحَامُ","rahim"],["وَمَا","dan apa"],["تَزْدَادُ ۖ","mereka melebihi"],["وَكُلُّ","Dan setiap"],["شَىْءٍ","perkara"],["عِندَهُۥ","dengan Dia"],["بِمِقْدَارٍ","(adalah) dalam perkadaran yang sewajarnya"]]],"1716":["(Yang mengetahui semua yang gaib dan yang tampak) hal-hal yang gaib dan hal-hal yang kelihatan (Yang Maha Besar) Maha Agung (lagi Maha Tinggi) di atas semua makhluk-Nya dengan cara paksa. Lafal al-muta`aal dapat pula di baca al-muta`aaliy dengan memakai huruf ya di akhirnya.",[["عَـٰلِمُ","Maha Mengetahui"],["ٱلْغَيْبِ","(dari) yang ghaib"],["وَٱلشَّهَـٰدَةِ","dan yang disaksikan"],["ٱلْكَبِيرُ","yang Maha Agung"],["ٱلْمُتَعَالِ","yang Maha Tinggi"]]],"1717":["(Sama saja) menurut ilmu Allah swt. (siapa yang merahasiakan ucapannya, dan siapa yang berterus terang, dan siapa yang bersembunyi) menyembunyikan dirinya (di malam hari) di dalam kegelapannya (dan yang berjalan) yang tampak kepergiannya di dalam perjalanannya (di siang hari).",[["سَوَآءٌۭ","(Ia adalah) sama (kepada-Nya)"],["مِّنكُم","[kamu]"],["مَّنْ","(satu) siapa"],["أَسَرَّ","menyembunyikan"],["ٱلْقَوْلَ","ucapan itu"],["وَمَن","atau (seorang) yang"],["جَهَرَ","menghebahkan"],["بِهِۦ","ia"],["وَمَنْ","dan (satu) siapa"],["هُوَ","[dia]"],["مُسْتَخْفٍۭ","(adalah) tersembunyi"],["بِٱلَّيْلِ","pada waktu malam"],["وَسَارِبٌۢ","atau pergi dengan bebas"],["بِٱلنَّهَارِ","mengikut hari"]]],"1718":["(Baginya) manusia (ada malaikat-malaikat yang selalu mengikutinya bergiliran) para malaikat yang bertugas mengawasinya (di muka) di hadapannya (dan di belakangnya) dari belakangnya (mereka menjaganya atas perintah Allah) berdasarkan perintah Allah, dari gangguan jin dan makhluk-makhluk yang lainnya. (Sesungguhnya Allah tidak mengubah keadaan sesuatu kaum) artinya Dia tidak mencabut dari mereka nikmat-Nya (sehingga mereka mengubah keadaan yang ada pada diri mereka sendiri) dari keadaan yang baik dengan melakukan perbuatan durhaka. (Dan apabila Allah menghendaki keburukan terhadap suatu kaum) yakni menimpakan azab (maka tak ada yang dapat menolaknya) dari siksaan-siksaan tersebut dan pula dari hal-hal lainnya yang telah dipastikan-Nya (dan sekali-kali tak ada bagi mereka) bagi orang-orang yang telah dikehendaki keburukan oleh Allah (selain Dia) selain Allah sendiri (seorang penolong pun) yang dapat mencegah datangnya azab Allah terhadap mereka. Huruf min di sini adalah zaidah.",[["لَهُۥ","Untuk dia"],["مُعَقِّبَـٰتٌۭ","(adalah) berturut-turut (Malaikat)"],["مِّنۢ","daripada"],["بَيْنِ","(sebelum ini)"],["يَدَيْهِ","(dia)"],["وَمِنْ","dan daripada"],["خَلْفِهِۦ","dan di belakangnya"],["يَحْفَظُونَهُۥ","yang menjaganya"],["مِنْ","oleh"],["أَمْرِ","(perintah)."],["ٱللَّهِ ۗ","(milik) Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُغَيِّرُ","berubah"],["مَا","(syarat)"],["بِقَوْمٍ","daripada sesuatu kaum"],["حَتَّىٰ","sehingga"],["يُغَيِّرُوا۟","mereka berubah"],["مَا","apa"],["بِأَنفُسِهِمْ ۗ","(ada) dalam diri mereka"],["وَإِذَآ","Dan apabila"],["أَرَادَ","wasiat"],["ٱللَّهُ","Allah"],["بِقَوْمٍۢ","bagi kaum"],["سُوٓءًۭا","musibah"],["فَلَا","maka (ada) tidak"],["مَرَدَّ","berpaling"],["لَهُۥ ۚ","daripadanya"],["وَمَا","dan bukan"],["لَهُم","bagi mereka"],["مِّن","daripada"],["دُونِهِۦ","selain Dia"],["مِن","sebarang"],["وَالٍ","pelindung"]]],"1719":["(Dialah Tuhan yang memperlihatkan kilat kepada kalian untuk menimbulkan ketakutan) terhadap orang-orang yang sedang musafir disebabkan suara halilintar (dan harapan) bagi orang yang bermukim terhadap turunnya hujan (dan Dia mengadakan) menciptakan (awan yang tebal) karena mengandung air hujan.",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["يُرِيكُمُ","menunjukkan kepada kamu"],["ٱلْبَرْقَ","kilat itu"],["خَوْفًۭا","ketakutan"],["وَطَمَعًۭا","dan sebuah harapan"],["وَيُنشِئُ","dan membangkitkan"],["ٱلسَّحَابَ","awan"],["ٱلثِّقَالَ","yang berat"]]],"1720":["(Dan guruh itu bertasbih) yaitu malaikat yang diserahi tugas untuk menggiring mendung seraya (memuji Allah) artinya ia selalu mengucapkan kalimat 'subhaanallaah wa bihamdihi' (dan) demikian pula bertasbih (para malaikat karena takut kepada-Nya) kepada Allah (dan Allah melepaskan halilintar) yaitu api yang keluar dari mendung (lalu menimpakannya kepada siapa yang Dia kehendaki) kemudian halilintar itu membakarnya. Ayat ini diturunkan berkenaan dengan seorang laki-laki yang Nabi saw. mengutus seseorang untuk menyerunya menyembah Allah. Akan tetapi laki-laki itu menjawab, \"Siapakah utusan Allah itu, dan siapakah Allah itu; apakah ia dari emas atau dari perak atau dari tembaga.\" Ketika itu juga turunlah halilintar menyambarnya sehingga hancur tulang batok kepalanya (dan mereka) orang-orang kafir (berbantah-bantahan) selalu membantah Nabi saw. (tentang Allah dan Dialah Tuhan Yang Maha Keras siksa-Nya) Maha Kuat atau Maha Keras azab-Nya.",[["وَيُسَبِّحُ","Dan bertasbih"],["ٱلرَّعْدُ","guruh itu"],["بِحَمْدِهِۦ","dengan pujiannya"],["وَٱلْمَلَـٰٓئِكَةُ","dan para Malaikat"],["مِنْ","bagi"],["خِيفَتِهِۦ","takut kepadaNya"],["وَيُرْسِلُ","Dan Dia menghantar"],["ٱلصَّوَٰعِقَ","petir"],["فَيُصِيبُ","dan mogok"],["بِهَا","dengannya"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَهُمْ","namun mereka"],["يُجَـٰدِلُونَ","pertikaian"],["فِى","tentang"],["ٱللَّهِ","Allah"],["وَهُوَ","Dan Dia"],["شَدِيدُ","(adalah) Perkasa"],["ٱلْمِحَالِ","(dalam) Kekuatan"]]],"1721":["(Hanya bagi Dia) bagi Allah swt. (doa yang benar) artinya kalimat-Nya, yaitu kalimat laa ilaaha illallaah (tiada Tuhan selain Allah). (Dan berhala-berhala yang mereka seru) dapat dibaca yad'uuna dan tad`uuna, artinya yang mereka sembah (selain Dia) yakni selain dari Allah, yaitu berhala-berhala (tidak dapat memperkenankan sesuatu pun bagi mereka) yakni sesuatu dari hal-hal yang mereka minta (melainkan) berkenaan (yang mirip dengan orang yang membukakan) artinya perihalnya sama dengan seseorang yang membukakan (kedua telapak tangannya ke dalam air) sedangkan ia berada di pinggir sumur, seraya menyeru air (supaya sampai kepada mulutnya) sekali pun tempat ia berada jauh dari air yang ada di dalam sumur itu (padahal air itu tidak dapat sampai kepadanya) ke mulutnya untuk selama-lamanya. Demikian pula keadaan para penyembah berhala itu, berhala-berhala yang mereka sembah itu tidak akan dapat memperkenankan kepada mereka. (Dan doa orang-orang kafir itu) penyembahan mereka terhadap berhala-berhala atau makna yang dimaksud adalah doa yang sesungguhnya (hanyalah sia-sia belaka) tidak ada artinya.",[["لَهُۥ","KepadaNya"],["دَعْوَةُ","(adalah) doa"],["ٱلْحَقِّ ۖ","(dari) kebenaran"],["وَٱلَّذِينَ","Dan mereka yang"],["يَدْعُونَ","mereka menyeru"],["مِن","selain Dia"],["دُونِهِۦ","selain Dia"],["لَا","tidak"],["يَسْتَجِيبُونَ","mereka bertindak balas"],["لَهُم","kepada mereka"],["بِشَىْءٍ","dengan sesuatu perkara"],["إِلَّا","kecuali"],["كَبَـٰسِطِ","seperti orang yang membentang"],["كَفَّيْهِ","tangannya"],["إِلَى","ke arah"],["ٱلْمَآءِ","air"],["لِيَبْلُغَ","untuk mencapai"],["فَاهُ","mulutnya"],["وَمَا","tetapi tidak"],["هُوَ","ia"],["بِبَـٰلِغِهِۦ ۚ","mencapainya"],["وَمَا","Dan tidak"],["دُعَآءُ","(ialah) doa itu"],["ٱلْكَـٰفِرِينَ","(dari) orang-orang kafir"],["إِلَّا","tetapi"],["فِى","dalam"],["ضَلَـٰلٍۢ","ralat"]]],"1722":["(Hanya kepada Allahlah sujud segala apa yang ada di langit dan di bumi, baik dengan kemauan sendiri) seperti orang-orang yang beriman (atau pun terpaksa) seperti orang-orang munafik dan orang-orang yang dipaksa dengan kekerasan (dan) sujud pula (bayang-bayangnya di waktu pagi) pada pagi hari (dan petang hari) sore hari.",[["وَلِلَّهِ","Dan kepada Allah"],["يَسْجُدُ","sujud"],["مَن","sesiapa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["طَوْعًۭا","dengan rela hati"],["وَكَرْهًۭا","atau tidak mahu"],["وَظِلَـٰلُهُم","dan (begitu juga) bayang-bayang mereka"],["بِٱلْغُدُوِّ","pada waktu pagi"],["وَٱلْـَٔاصَالِ ۩","dan pada sebelah petang"]]],"1723":["(Katakanlah) hai Muhammad kepada kaummu (\"Siapakah Rabb langit dan bumi?\" Jawabnya, \"Allah.\") jika mereka tidak mau mengatakannya, maka tiada jawaban lain kecuali itu. (Katakanlah) kepada mereka (\"Maka patutkah kalian mengambil selain Allah) selain-Nya (sebagai pelindung-pelindung) berhala-berhala yang kalian sembah (padahal mereka tidak memiliki kekuasaan untuk memberikan kemanfaatan dan tidak pula kemudaratan bagi diri mereka sendiri?\") kemudian kalian meninggalkan untuk menyembah kepada Yang memiliki dan Yang menguasai kemanfaatan dan kemudaratan? Kata tanya di sini mengandung pengertian cemoohan dan ejekan. (Katakanlah, \"Adakah sama orang buta dan orang yang melihat?) orang kafir dan orang mukmin itu apakah sama? (atau samakah gelap-gulita) yakni kekafiran (dan terang-benderang?) yakni keimanan? Tentu saja tidak. (Apakah mereka menjadikan beberapa sekutu bagi Allah yang dapat menciptakan seperti ciptaan-Nya sehingga kedua ciptaan itu serupa) artinya sekutu-sekutu itu dapat menciptakan seperti ciptaan Allah (menurut pandangan mereka?\") sehingga mereka berkeyakinan bahwa berhala-berhala atau sekutu-sekutu itu berhak untuk disembah oleh sebab kemampuan mereka dalam hal menciptakan? Kata tanya di sini mengandung makna ingkar; atau dengan kata lain berarti bahwa hakikatnya tidaklah demikian karena sesungguhnya tidak ada yang berhak untuk disembah selain daripada Yang Maha Pencipta. (Katakanlah, \"Allah adalah pencipta segala sesuatu) tiada sekutu bagi-Nya di dalam penciptaan ini, maka tiada sekutu pula bagi-Nya dalam hal disembah (dan Dialah Tuhan Yang Maha Esa lagi Maha Perkasa.\") di atas semua hamba-hamba-Nya.",[["قُلْ","Katakanlah"],["مَن","Siapa"],["رَّبُّ","(ialah) Tuhan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["قُلِ","Katakanlah"],["ٱللَّهُ ۚ","Allah"],["قُلْ","Katakanlah"],["أَفَٱتَّخَذْتُم","Adakah kamu kemudian mengambil"],["مِّن","daripada"],["دُونِهِۦٓ","selain Dia"],["أَوْلِيَآءَ","pelindung"],["لَا","tidak"],["يَمْلِكُونَ","mereka mempunyai kuasa"],["لِأَنفُسِهِمْ","untuk diri mereka sendiri"],["نَفْعًۭا","(untuk) mendapat manfaat"],["وَلَا","dan bukan"],["ضَرًّۭا ۚ","(untuk) membahayakan"],["قُلْ","Katakanlah"],["هَلْ","Adakah"],["يَسْتَوِى","sama rata"],["ٱلْأَعْمَىٰ","yang buta"],["وَٱلْبَصِيرُ","dan yang melihat"],["أَمْ","Atau"],["هَلْ","ialah"],["تَسْتَوِى","sama rata"],["ٱلظُّلُمَـٰتُ","kegelapan[es]"],["وَٱلنُّورُ ۗ","dan cahaya"],["أَمْ","Atau"],["جَعَلُوا۟","mereka sifatkan"],["لِلَّهِ","kepada Allah"],["شُرَكَآءَ","rakan kongsi"],["خَلَقُوا۟","yang mencipta"],["كَخَلْقِهِۦ","seperti ciptaanNya"],["فَتَشَـٰبَهَ","jadi itu kelihatan sama"],["ٱلْخَلْقُ","penciptaan"],["عَلَيْهِمْ ۚ","kepada mereka"],["قُلِ","Katakanlah"],["ٱللَّهُ","Allah"],["خَـٰلِقُ","(ialah) Pencipta"],["كُلِّ","daripada semua"],["شَىْءٍۢ","benda"],["وَهُوَ","dan Dia"],["ٱلْوَٰحِدُ","(ialah) Yang Esa"],["ٱلْقَهَّـٰرُ","yang tak tertahan"]]],"1724":["Kemudian Allah membuat suatu perumpamaan mengenai perkara yang hak dan perkara yang batil untuk itu Dia berfirman: (Allah telah menurunkan) Maha Tinggi Allah (air dari langit) yakni air hujan (maka mengalirlah air di lembah-lembah menurut ukurannya) sesuai dengan daya tampungnya (maka arus itu membawa buih yang mengembang) mengapung di atas air yang mengandung kotoran dan lain sebagainya. (Dan dari apa yang mereka lebur) dapat dibaca tuuqiduuna dan yuuqiduuna (dalam api) yaitu berupa logam yang dikeluarkan dari dalam bumi, seperti emas, perak dan tembaga (untuk membuat) untuk dijadikan (perhiasan) barang perhiasan (atau alat-alat) perabot-perabot yang diperlukan, jika kesemuanya itu dilebur (ada pula buihnya) yakni sama seperti buih arus tadi, yaitu kotorannya kemudian kotoran itu dibuang oleh orang yang mencetaknya. (Demikianlah) hal yang telah disebutkan itu (Allah membuat perumpamaan bagi yang benar dan yang batil) perumpamaan mengenai keduanya. (Adapun buih itu) buih arus itu dan kotoran barang logam yang dilebur (akan hilang sebagai sesuatu yang tak ada harganya) menjadi limbah yang dibuang (adapun yang memberi manfaat kepada manusia) yaitu air bersih dan inti logam (maka ia tetap) terkandung (di bumi) selama beberapa masa. Demikianlah perumpamaan tentang hal yang batil; akan pudar dan lenyap, sekalipun dalam beberapa waktu dapat mengalahkan perkara yang hak. Akan tetapi pada akhirnya perkara yang hak jugalah yang akan tetap tegak dan menang. (Demikian) hal yang disebutkan itu (Allah menjelaskan) menerangkan (perumpamaan-perumpamaan).",[["أَنزَلَ","Dia menghantar turun"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَسَالَتْ","dan mengalir"],["أَوْدِيَةٌۢ","lembah-lembah"],["بِقَدَرِهَا","mengikut sukatan mereka"],["فَٱحْتَمَلَ","dan membawa"],["ٱلسَّيْلُ","torrent itu"],["زَبَدًۭا","buih"],["رَّابِيًۭا ۚ","meningkat"],["وَمِمَّا","Dan dari apa"],["يُوقِدُونَ","mereka panas"],["عَلَيْهِ","[pada]nya"],["فِى","dalam"],["ٱلنَّارِ","api"],["ٱبْتِغَآءَ","untuk membuat"],["حِلْيَةٍ","perhiasan"],["أَوْ","atau"],["مَتَـٰعٍۢ","perkakas"],["زَبَدٌۭ","buih"],["مِّثْلُهُۥ ۚ","suka"],["كَذَٰلِكَ","Demikianlah"],["يَضْرِبُ","menetapkan"],["ٱللَّهُ","Allah"],["ٱلْحَقَّ","kebenaran"],["وَٱلْبَـٰطِلَ ۚ","dan kebatilan"],["فَأَمَّا","Kemudian untuk"],["ٱلزَّبَدُ","buih itu"],["فَيَذْهَبُ","ia berlalu pergi"],["جُفَآءًۭ ۖ","(sebagai) sampah"],["وَأَمَّا","dan bagi"],["مَا","apa"],["يَنفَعُ","faedah"],["ٱلنَّاسَ","umat manusia"],["فَيَمْكُثُ","tinggal"],["فِى","dalam"],["ٱلْأَرْضِ ۚ","bumi"],["كَذَٰلِكَ","Demikianlah"],["يَضْرِبُ","Allah menetapkan"],["ٱللَّهُ","Allah menetapkan"],["ٱلْأَمْثَالَ","contoh-contohnya"]]],"1725":["(Bagi orang-orang yang memenuhi seruan Rabbnya) yaitu mereka yang menjalankan seruan-Nya dengan melakukan ketaatan (disediakan pembalasan yang baik) yaitu surga (Dan orang-orang yang tidak memenuhi seruan Rabb) mereka adalah orang-orang kafir (sekiranya mereka mempunyai semua kekayaan sebanyak isi bumi itu beserta hal yang serupa niscaya mereka akan menebus dirinya dengan kekayaan itu) dari azab. (Orang-orang itu disediakan baginya hisab yang buruk) yaitu menghukum semua amal perbuatan yang telah dilakukannya tanpa ada pengampunan barang sedikit pun daripadanya (dan tempat kediaman mereka ialah Jahanam dan itulah seburuk-buruk tempat kediaman) tempat yang paling buruk ialah Jahanam.",[["لِلَّذِينَ","Bagi mereka yang"],["ٱسْتَجَابُوا۟","menjawab"],["لِرَبِّهِمُ","kepada Tuhan mereka"],["ٱلْحُسْنَىٰ ۚ","(ialah) kebahagiaan"],["وَٱلَّذِينَ","Dan bagi mereka yang"],["لَمْ","(tidak) tidak"],["يَسْتَجِيبُوا۟","bertindak balas"],["لَهُۥ","kepada-Nya"],["لَوْ","jika"],["أَنَّ","bahawa"],["لَهُم","mereka telah"],["مَّا","apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["جَمِيعًۭا","semua"],["وَمِثْلَهُۥ","dan seperti itu"],["مَعَهُۥ","dengannya"],["لَٱفْتَدَوْا۟","nescaya mereka akan menawarkan tebusan"],["بِهِۦٓ ۚ","dengannya"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["لَهُمْ","bagi mereka"],["سُوٓءُ","(adalah) yang dahsyat"],["ٱلْحِسَابِ","hisab"],["وَمَأْوَىٰهُمْ","dan tempat tinggal mereka"],["جَهَنَّمُ ۖ","(ialah) Neraka"],["وَبِئْسَ","dan celaka"],["ٱلْمِهَادُ","(ialah) tempat berehat"]]],"1726":["Ayat berikut ini diturunkan berkenaan dengan sahabat Hamzah dan Abu Jahal. (Adakah orang yang mengetahui bahwasanya apa yang diturunkan kepadamu dari Rabbmu itu benar) lalu ia beriman kepadanya (sama dengan orang yang buta?) yaitu orang yang tidak mengetahuinya dan tidak mau beriman kepadanya. Tentu saja tidak. (Sesungguhnya yang mau mengambil pelajaran itu) orang-orang yang menasihati dirinya sendiri (hanyalah orang-orang yang berakal saja) orang-orang yang memiliki akal sehat.",[["۞ أَفَمَن","Maka adakah (dia) yang"],["يَعْلَمُ","mengetahui"],["أَنَّمَآ","itu yang"],["أُنزِلَ","telah didedahkan"],["إِلَيْكَ","kepada kamu"],["مِن","daripada"],["رَّبِّكَ","Tuhanmu"],["ٱلْحَقُّ","(adalah) kebenaran"],["كَمَنْ","seperti (seorang) siapa"],["هُوَ","[dia]"],["أَعْمَىٰٓ ۚ","(adalah) buta"],["إِنَّمَا","Hanya"],["يَتَذَكَّرُ","ambil iktibar"],["أُو۟لُوا۟","lelaki"],["ٱلْأَلْبَـٰبِ","(dari) pemahaman"]]],"1727":["(Yaitu orang-orang yang memenuhi janji Allah) yang telah mereka ikrarkan di hadapan-Nya, yang hal ini terjadi di alam arwah, atau makna yang dimaksud adalah setiap janji (dan tidak merusak perjanjian) dengan meninggalkan keimanan atau meninggalkan hal-hal yang fardu.",[["ٱلَّذِينَ","Orang yang"],["يُوفُونَ","memenuhi"],["بِعَهْدِ","perjanjian itu"],["ٱللَّهِ","(milik) Allah"],["وَلَا","dan bukan"],["يَنقُضُونَ","mereka pecah"],["ٱلْمِيثَـٰقَ","kontrak itu"]]],"1728":["(Dan orang-orang yang menghubungkan apa-apa yang Allah perintahkan supaya dihubungkan) yaitu iman, silaturahmi dan lain sebagainya (dan mereka takut kepada Rabb mereka) ancaman-Nya (dan takut kepada hisab yang buruk) penafsiran kalimat ini telah dijelaskan sebelumnya.",[["وَٱلَّذِينَ","Dan orang yang"],["يَصِلُونَ","sertai"],["مَآ","apa"],["أَمَرَ","(telah) diperintahkan"],["ٱللَّهُ","(oleh) Allah"],["بِهِۦٓ","[untuk itu]"],["أَن","kepada"],["يُوصَلَ","disertai"],["وَيَخْشَوْنَ","dan ketakutan"],["رَبَّهُمْ","Tuhan mereka"],["وَيَخَافُونَ","dan takut"],["سُوٓءَ","(dari) kejahatan"],["ٱلْحِسَابِ","akaun tersebut"]]],"1729":["(Dan orang-orang yang sabar) di dalam menjalankan ketaatan dan menghadapi musibah serta teguh di dalam menjauhi kemaksiatan (karena mencari) demi karena (Rabbnya) bukan karena mengharapkan kebendaan (dan mendirikan salat dan menafkahkan) di jalan ketaatan (sebagian rezeki yang Kami berikan kepada mereka secara sembunyi atau terang-terangan serta menolak) menghadapi (kejahatan dengan kebaikan) seperti menghadapi kebodohan dengan sifat penyantun dan menghadapi perlakuan yang menyakitkan dengan bersabar diri (orang-orang itulah yang mendapat tempat kesudahan yang baik) yakni mendapat akibat yang terpuji di kampung akhirat, yaitu:",[["وَٱلَّذِينَ","Dan orang yang"],["صَبَرُوا۟","(adalah) sabar"],["ٱبْتِغَآءَ","mencari"],["وَجْهِ","(the) Muka"],["رَبِّهِمْ","(dari) Tuhan mereka"],["وَأَقَامُوا۟","dan menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَأَنفَقُوا۟","dan berbelanja"],["مِمَّا","daripada apa"],["رَزَقْنَـٰهُمْ","Kami telah menyediakan mereka"],["سِرًّۭا","secara rahsia"],["وَعَلَانِيَةًۭ","dan secara terbuka"],["وَيَدْرَءُونَ","dan mereka menolak"],["بِٱلْحَسَنَةِ","dengan kebaikan"],["ٱلسَّيِّئَةَ","yang jahat"],["أُو۟لَـٰٓئِكَ","mereka"],["لَهُمْ","bagi mereka"],["عُقْبَى","(ialah) pencapaian terakhir"],["ٱلدَّارِ","(dari) Rumah"]]],"1730":["(Surga Adn) sebagai tempat tinggalnya (yang mereka masuk ke dalamnya) bersama (dengan orang-orang yang saleh) orang-orang yang beriman (dari bapak-bapaknya, istri-istrinya dan anak-cucunya) sekali pun mereka tidak mengamalkan seperti apa yang diamalkannya, maka mereka tetap sederajat dengannya sebagai penghormatan terhadapnya (sedangkan malaikat-malaikat masuk ke tempat-tempat mereka dari setiap pintu) dari pintu-pintu surga atau pintu-pintu gedung surga, sewaktu pertama kali mereka memasukinya sebagai penghormatan dari para malaikat terhadap mereka.",[["جَنَّـٰتُ","Taman-taman"],["عَدْنٍۢ","dari Eden"],["يَدْخُلُونَهَا","mereka akan memasukinya"],["وَمَن","dan sesiapa"],["صَلَحَ","(adalah) orang yang soleh"],["مِنْ","antara"],["ءَابَآئِهِمْ","bapa mereka"],["وَأَزْوَٰجِهِمْ","dan pasangan mereka"],["وَذُرِّيَّـٰتِهِمْ ۖ","dan keturunan mereka"],["وَٱلْمَلَـٰٓئِكَةُ","Dan para Malaikat"],["يَدْخُلُونَ","akan masuk"],["عَلَيْهِم","ke atas mereka"],["مِّن","daripada"],["كُلِّ","setiap"],["بَابٍۢ","pintu pagar"]]],"1731":["Malaikat-malaikat itu mengucapkan (Kesejahteraan buat kalian) yakni pahala ini (berkat kesabaran kalian) sewaktu kalian di dunia (maka alangkah baiknya tempat kesudahan ini) akibat dari perbuatan kalian itu.",[["سَلَـٰمٌ","(Sambil berkata), \"Selamat sejahtera"],["عَلَيْكُم","(berada) atas kamu"],["بِمَا","bagi apa"],["صَبَرْتُمْ ۚ","kamu bersabar"],["فَنِعْمَ","Dan cemerlang"],["عُقْبَى","(ialah) pencapaian terakhir"],["ٱلدَّارِ","(dari) Rumah"]]],"1732":["(Orang-orang yang merusak janji Allah setelah diikrarkan dengan teguh dan memutuskan apa-apa yang Allah perintahkan supaya dihubungkan dan mengadakan kerusakan di bumi) dengan melakukan kekafiran dan perbuatan-perbuatan maksiat (orang-orang itulah yang memperoleh kutukan) yaitu dijauhkan dari rahmat Allah (dan bagi mereka tempat kediaman yang buruk) akibat yang buruk di kampung akhirat nanti, yaitu ditempatkan di neraka Jahanam.",[["وَٱلَّذِينَ","Dan orang yang"],["يَنقُضُونَ","rehat"],["عَهْدَ","perjanjian itu"],["ٱللَّهِ","(milik) Allah"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["مِيثَـٰقِهِۦ","mengontraknya"],["وَيَقْطَعُونَ","dan putuskan"],["مَآ","apa"],["أَمَرَ","(telah) diperintahkan"],["ٱللَّهُ","(oleh) Allah"],["بِهِۦٓ","baginya"],["أَن","kepada"],["يُوصَلَ","disertai"],["وَيُفْسِدُونَ","dan menyebarkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ ۙ","bumi"],["أُو۟لَـٰٓئِكَ","Itu"],["لَهُمُ","bagi mereka"],["ٱللَّعْنَةُ","(ialah) laknat"],["وَلَهُمْ","dan untuk mereka"],["سُوٓءُ","(adalah) kejahatan"],["ٱلدَّارِ","rumah"]]],"1733":["(Allah meluaskan rezeki) melebarkannya (bagi siapa yang dikehendaki-Nya dan menyempitkannya) artinya Allah pun menyempitkan rezeki bagi siapa yang dikehendaki-Nya. (Mereka bergembira) yang dimaksud ialah penduduk Mekah, yaitu dengan kegembiraan yang sombong (dengan kehidupan di dunia) dengan apa yang telah mereka peroleh daripada perkara duniawi (padahal kehidupan dunia itu) dibanding dengan (kehidupan di akhirat hanyalah kesenangan yang sedikit) kesenangan yang bersifat sementara lalu lenyap.",[["ٱللَّهُ","Allah"],["يَبْسُطُ","memanjang"],["ٱلرِّزْقَ","peruntukan itu"],["لِمَن","untuk siapa"],["يَشَآءُ","Dia kehendaki"],["وَيَقْدِرُ ۚ","dan menyekat"],["وَفَرِحُوا۟","Dan mereka bergembira"],["بِٱلْحَيَوٰةِ","dalam kehidupan"],["ٱلدُّنْيَا","dunia"],["وَمَا","dan tiada apa-apa"],["ٱلْحَيَوٰةُ","(ialah) kehidupan"],["ٱلدُّنْيَا","dunia"],["فِى","dalam (perbandingan dengan)"],["ٱلْـَٔاخِرَةِ","akhirat"],["إِلَّا","kecuali"],["مَتَـٰعٌۭ","suatu kenikmatan"]]],"1734":["(Orang-orang kafir berkata) mereka adalah dari kalangan penduduk Mekah (\"Mengapa tidak) (diturunkan kepadanya) yakni kepada Muhammad (suatu mukjizat dari Rabbnya?\") seperti tongkat dan tangan Nabi Musa dan unta Nabi Saleh. (Katakanlah) kepada mereka (Allah menyesatkan siapa yang Dia kehendaki) untuk disesatkan oleh sebab itu tiada gunanya sedikit pun baginya mukjizat-mukjizat itu (dan menunjuki) memberikan petunjuk (kepada-Nya) kepada agama-Nya (orang-orang yang bertobat) kepada-Nya. Kemudian pada ayat selanjutnya diterangkan, siapa yang dimaksud orang-orang yang bertobat itu.",[["وَيَقُولُ","Dan katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَوْلَآ","Kenapa belum"],["أُنزِلَ","telah diturunkan"],["عَلَيْهِ","atasnya"],["ءَايَةٌۭ","sebuah Tanda"],["مِّن","daripada"],["رَّبِّهِۦ ۗ","Tuhannya"],["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُضِلُّ","biarlah sesat"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَهْدِىٓ","dan panduan"],["إِلَيْهِ","kepada diriNya"],["مَنْ","sesiapa sahaja"],["أَنَابَ","berpatah balik"]]],"1735":["(Yaitu orang-orang yang beriman dan yang merasa tenang) tenteram (hati mereka dengan mengingat Allah) mengingat janji-Nya. (Ingatlah, hanya dengan mengingat Allahlah hati menjadi tenteram) yakni hati orang-orang yang beriman.",[["ٱلَّذِينَ","Orang yang"],["ءَامَنُوا۟","beriman"],["وَتَطْمَئِنُّ","dan mencari kepuasan"],["قُلُوبُهُم","hati mereka"],["بِذِكْرِ","dalam zikir"],["ٱللَّهِ ۗ","(milik) Allah"],["أَلَا","Tidak syak lagi"],["بِذِكْرِ","dalam zikir"],["ٱللَّهِ","(milik) Allah"],["تَطْمَئِنُّ","mencari kepuasan"],["ٱلْقُلُوبُ","hati"]]],"1736":["(Orang-orang yang beriman dan beramal saleh) kalimat ini menjadi mubtada sedangkan khabarnya ialah (alangkah bahagianya) lafal thuubaa mashdar daripada lafal ath-thiib, adalah nama sebuah pohon di surga, seseorang yang berkendaraan tidak akan dapat menempuh naungannya sekali pun berjalan seratus tahun (bagi mereka dan tempat kembali yang baik) tempat kembali di akhirat.",[["ٱلَّذِينَ","Orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["طُوبَىٰ","keberkatan"],["لَهُمْ","(adalah) untuk mereka"],["وَحُسْنُ","dan yang cantik"],["مَـَٔابٍۢ","tempat pulang"]]],"1737":["(Demikianlah) sebagaimana Kami mengutus nabi-nabi sebelummu (Kami mengutus kamu kepada suatu umat yang sungguh telah berlalu beberapa umat sebelumnya supaya kamu membacakan) mengajarkan (kepada mereka apa yang Kami wahyukan kepadamu) yaitu Alquran (padahal mereka kafir kepada Tuhan Yang Maha Pemurah) karena mereka mengatakan sewaktu mereka disuruh sujud atau menyembah kepada-Nya siapakah Tuhan Yang Maha Pemurah? (Katakanlah) kepada mereka hai Muhammad (\"Dialah Rabbku, tidak ada Tuhan selain Dia, hanya kepada-Nya aku bertawakal dan hanya kepada-Nya aku bertobat.\")",[["كَذَٰلِكَ","Demikianlah"],["أَرْسَلْنَـٰكَ","Kami telah menghantar kamu"],["فِىٓ","kepada"],["أُمَّةٍۢ","sebuah bangsa"],["قَدْ","sesungguhnya"],["خَلَتْ","telah meninggal dunia"],["مِن","daripada"],["قَبْلِهَآ","sebelum itu"],["أُمَمٌۭ","bangsa-bangsa"],["لِّتَتْلُوَا۟","supaya kamu boleh membaca"],["عَلَيْهِمُ","kepada mereka"],["ٱلَّذِىٓ","apa"],["أَوْحَيْنَآ","Kami mendedahkan"],["إِلَيْكَ","kepada kamu"],["وَهُمْ","sedangkan mereka"],["يَكْفُرُونَ","kufur"],["بِٱلرَّحْمَـٰنِ ۚ","dalam Yang Maha Pemurah"],["قُلْ","Katakanlah"],["هُوَ","Dia"],["رَبِّى","(ialah) Tuhanku"],["لَآ","(ada) tidak"],["إِلَـٰهَ","tuhan"],["إِلَّا","kecuali"],["هُوَ","Dia"],["عَلَيْهِ","atas Dia"],["تَوَكَّلْتُ","Aku meletakkan kepercayaan aku"],["وَإِلَيْهِ","dan kepada-Nya"],["مَتَابِ","(adalah) kepulangan aku"]]],"1738":["Ayat ini diturunkan ketika orang-orang kafir Mekah berkata kepada Nabi saw., \"Jika engkau ini benar-benar seorang nabi, maka lenyapkanlah gunung-gunung Mekah ini daripada kami, kemudian jadikanlah pada tempatnya sungai-sungai dan mata air-mata air supaya kami dapat bercocok tanam, dan bangkitkanlah nenek moyang kami yang telah mati menjadi hidup kembali, untuk berbicara kepada kami.\" (Dan sekiranya ada suatu bacaan yang dengan bacaan itu gunung-gunung dapat dipindahkan) artinya dapat dipindahkan dari tempatnya yang semula (atau dapat dibelah) dapat dipotong (karenanya bumi, atau oleh karenanya orang-orang yang sudah mati dapat berbicara) seumpamanya mereka dapat dihidupkan kembali karenanya, niscaya mereka tetap tidak akan beriman juga. (Sebenarnya segala urusan itu adalah kepunyaan Allah) bukan kepunyaan yang lain-Nya. Oleh sebab itu maka tiada beriman melainkan orang-orang yang telah dikehendaki oleh Allah untuk beriman, bukannya orang-orang selain mereka sekali pun didatangkan kepada mereka apa yang dipintanya itu. Sedangkan ayat selanjutnya ini diturunkan ketika para sahabat berkehendak untuk menampakkan apa yang mereka minta, karena para sahabat sangat menginginkan mereka mau beriman, yaitu firman-Nya: (Maka tidakkah mengetahui) mengerti (orang-orang yang beriman itu, bahwasanya) huruf an di sini adalah bentuk takhfif daripada anna (seandainya Allah menghendaki tentu Allah memberi petunjuk kepada manusia semuanya) kepada keimanan tanpa melalui mukjizat lagi. (Dan orang-orang yang kafir senantiasa) yakni penduduk Mekah yang kafir (ditimpa bencana disebabkan perbuatan mereka sendiri) yakni oleh sebab kekafiran mereka itu (yaitu berupa malapetaka) yang menimpa mereka dengan berbagai macam cobaan, seperti dibunuh, ditawan, diperangi dan paceklik (atau bencana itu terjadi) hai Muhammad terhadap pasukanmu (dekat tempat kediaman mereka) yaitu kota Mekah (sehingga datanglah janji Allah) yaitu memberikan pertolongan-Nya untuk mengalahkan mereka. (Sesungguhnya Allah tidak menyalahi janji) hal ini telah terjadi di Hudaibiah sehingga tibalah saatnya penaklukan kota Mekah.",[["وَلَوْ","Dan jika"],["أَنَّ","itu tadi"],["قُرْءَانًۭا","mana-mana al-Quran"],["سُيِّرَتْ","boleh digerakkan"],["بِهِ","olehnya"],["ٱلْجِبَالُ","pergunungan"],["أَوْ","atau"],["قُطِّعَتْ","boleh dibelah-belah"],["بِهِ","olehnya"],["ٱلْأَرْضُ","bumi"],["أَوْ","atau"],["كُلِّمَ","boleh dibuat untuk bercakap"],["بِهِ","olehnya"],["ٱلْمَوْتَىٰ ۗ","yang mati"],["بَل","Bahkan"],["لِّلَّهِ","dengan Allah"],["ٱلْأَمْرُ","(ialah) perintah"],["جَمِيعًا ۗ","semua"],["أَفَلَمْ","Kemudian jangan"],["يَا۟يْـَٔسِ","mengetahui"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوٓا۟","beriman"],["أَن","bahawa"],["لَّوْ","jika"],["يَشَآءُ","telah berkehendak"],["ٱللَّهُ","Allah"],["لَهَدَى","nescaya Dia akan memberi petunjuk"],["ٱلنَّاسَ","semua"],["جَمِيعًۭا ۗ","seluruh umat manusia"],["وَلَا","Dan tidak"],["يَزَالُ","akan terhenti"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["تُصِيبُهُم","untuk menyerang mereka"],["بِمَا","bagi apa"],["صَنَعُوا۟","mereka lakukan"],["قَارِعَةٌ","satu bencana"],["أَوْ","atau"],["تَحُلُّ","ia mengendap"],["قَرِيبًۭا","dekat"],["مِّن","daripada"],["دَارِهِمْ","rumah mereka"],["حَتَّىٰ","sehingga"],["يَأْتِىَ","datang"],["وَعْدُ","(janji) itu"],["ٱللَّهِ ۚ","(milik) Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","(akan) tidak"],["يُخْلِفُ","gagal"],["ٱلْمِيعَادَ","(dalam) Janji"]]],"1739":["(Dan sesungguhnya telah diperolok-olokkan beberapa rasul sebelum kamu) sebagaimana kamu diperolok-olokkan. Hal ini merupakan penghibur bagi hati Nabi saw. (maka Aku beri tangguh) menangguhkan (kepada orang-orang kafir itu, kemudian Aku binasakan mereka) dengan siksaan (maka sebagaimana siksaan-Ku terdahulu) artinya siksaan itu benar-benar telah menimpa orang-orang yang memperolok-olokkan para rasul, demikian pula Aku akan melakukan hal yang sama terhadap orang-orang yang memperolok-olokkan kamu.",[["وَلَقَدِ","Dan sungguh"],["ٱسْتُهْزِئَ","diejek"],["بِرُسُلٍۢ","Utusan"],["مِّن","daripada"],["قَبْلِكَ","sebelum kamu"],["فَأَمْلَيْتُ","tapi aku beri tangguh"],["لِلَّذِينَ","kepada mereka yang"],["كَفَرُوا۟","kufur"],["ثُمَّ","kemudian"],["أَخَذْتُهُمْ ۖ","Aku menangkap mereka"],["فَكَيْفَ","dan bagaimana"],["كَانَ","adalah"],["عِقَابِ","Penalti aku"]]],"1740":["(Maka apakah Tuhan yang menjaga) yakni mengawasi (setiap diri terhadap apa yang diperbuatnya) yaitu berupa amal kebaikan dan keburukan, sama keadaan-Nya dengan berhala-berhala yang tidak demikian keadaannya; tentu saja tidak. Pengertian ini ditunjukkan oleh firman selanjutnya, yaitu (Mereka menjadikan beberapa sekutu bagi Allah. Katakanlah, \"Sebutkanlah sifat-sifat mereka itu.\") kepada-Nya, siapakah berhala-berhala itu (atau) bahkan apakah (kalian hendak memberitakan kepada Allah) menceritakan kepada-Nya (mengenai apa) yakni sekutu (yang tidak diketahui)-Nya (di bumi) istifham atau kata tanya di sini mengandung pengertian ingkar; artinya jelas tidak ada sekutu itu, sebab jika sekutu itu ada niscaya Dia akan mengetahuinya, Maha Tinggi Allah dari semua sekutu (atau) bahkan mereka menamakannya sebagai sekutu-sekutu Allah (kalian mengatakan sekadar perkataan pada lahirnya) dengan sangkaan yang batil, lagi hal itu tidak ada kenyataannya pada batinnya. (Sebenarnya orang-orang kafir itu dijadikan memandang baik tipu daya mereka) yang dimaksud ialah kekafiran mereka (dan dihalanginya dari jalan yang benar) yaitu hidayah. (Dan barang siapa yang disesatkan Allah, maka tak ada seorang pun baginya yang akan memberi petunjuk).",[["أَفَمَنْ","Adakah kemudian Dia yang"],["هُوَ","(dia)"],["قَآئِمٌ","(adalah) seorang Penyelenggara"],["عَلَىٰ","daripada"],["كُلِّ","setiap"],["نَفْسٍۭ","jiwa"],["بِمَا","bagi apa"],["كَسَبَتْ ۗ","ia telah memperolehi"],["وَجَعَلُوا۟","Namun mereka menganggap"],["لِلَّهِ","kepada Allah"],["شُرَكَآءَ","rakan kongsi"],["قُلْ","Katakanlah"],["سَمُّوهُمْ ۚ","Namakan mereka"],["أَمْ","Atau"],["تُنَبِّـُٔونَهُۥ","(adakah) kamu memberitahu-Nya"],["بِمَا","tentang apa"],["لَا","tidak"],["يَعْلَمُ","Dia tahu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["أَم","atau"],["بِظَـٰهِرٍۢ","daripada yang nyata"],["مِّنَ","daripada"],["ٱلْقَوْلِ ۗ","kata-kata"],["بَلْ","Bahkan"],["زُيِّنَ","(adalah) dibuat kelihatan adil"],["لِلَّذِينَ","kepada mereka yang"],["كَفَرُوا۟","kufur"],["مَكْرُهُمْ","perancangan mereka"],["وَصُدُّوا۟","dan mereka terhalang"],["عَنِ","daripada"],["ٱلسَّبِيلِ ۗ","Jalan"],["وَمَن","Dan sesiapa"],["يُضْلِلِ","(oleh) Allah"],["ٱللَّهُ","Allah biarkan sesat"],["فَمَا","maka tidak"],["لَهُۥ","baginya"],["مِنْ","sebarang"],["هَادٍۢ","panduan"]]],"1741":["(Bagi mereka azab dalam kehidupan dunia) yaitu dengan dibunuh dan ditawan (dan sesungguhnya azab akhirat adalah lebih keras) lebih keras daripada siksaan di dunia (dan tak ada bagi mereka terhadap Allah) terhadap siksaan-Nya (seorang pelindung pun) yang dapat mencegah siksaan itu.",[["لَّهُمْ","Untuk mereka"],["عَذَابٌۭ","(ialah) azab"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا ۖ","dunia"],["وَلَعَذَابُ","dan sesungguhnya azab"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["أَشَقُّ ۖ","(adalah) lebih sukar"],["وَمَا","Dan tidak"],["لَهُم","bagi mereka"],["مِّنَ","terhadap"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["وَاقٍۢ","pertahanan"]]],"1742":["(Perumpamaan) gambaran (surga yang dijanjikan kepada orang-orang yang takwa) kalimat ayat ini menjadi mubtada, sedangkan khabarnya tidak disebutkan, lengkapnya mengatakan: yaitu seperti apa yang akan Kami ceritakan kepada kalian (mengalir sungai-sungai di bawahnya; buah-buahannya) artinya apa-apa yang dimakan di dalam surga (tiada henti-hentinya) tidak pernah lenyap (sedang naungannya) tiada henti-hentinya pula, tidak pernah terhapus oleh matahari, karena di dalam surga tidak ada matahari. (Itulah) yakni surga itu (tempat kesudahan) akhir daripada kesudahan (orang-orang yang bertakwa) takut kepada perbuatan syirik (sedangkan tempat kesudahan bagi orang-orang kafir ialah neraka).",[["۞ مَّثَلُ","Contohnya"],["ٱلْجَنَّةِ","daripada Syurga"],["ٱلَّتِى","yang"],["وُعِدَ","(adalah) dijanjikan"],["ٱلْمُتَّقُونَ ۖ","(kepada) orang-orang yang soleh"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ ۖ","sungai-sungai"],["أُكُلُهَا","Makanannya"],["دَآئِمٌۭ","(adalah) kekal"],["وَظِلُّهَا ۚ","dan naungannya"],["تِلْكَ","Ini"],["عُقْبَى","(adalah) akhir"],["ٱلَّذِينَ","daripada mereka yang"],["ٱتَّقَوا۟ ۖ","(adalah) soleh"],["وَّعُقْبَى","dan (akhirnya)."],["ٱلْكَـٰفِرِينَ","(dari) orang-orang kafir"],["ٱلنَّارُ","(ialah) Api"]]],"1743":["(Orang-orang yang Kami berikan kitab kepada mereka) seperti Abdullah bin Salam dan lain-lainnya dari kalangan orang-orang Yahudi yang beriman (mereka bergembira dengan kitab yang diturunkan kepadamu) karena Alquran yang diturunkan kepadanya tidak bertentangan dengan kitab Taurat yang ada pada mereka (dan di antara golongan-golongan) yang telah bersekutu untuk melawan kamu, yaitu mereka yang terdiri dari kalangan kaum musyrikin dan orang-orang Yahudi (ada yang menginginkan sebagiannya) yaitu yang menyangkut tentang penyebutan lafal Ar-Rahman dan hal-hal yang lain selain yang menyangkut kisah-kisah. (Katakanlah, \"Sesungguhnya aku hanya diperintahkan) oleh apa yang diturunkan kepadaku (untuk) supaya (menyembah Allah dan tidak menyekutukan-Nya dengan sesuatu pun. Hanya kepada-Nya aku berseru dan hanya kepada-Nya aku kembali.\") tempat kembaliku.",[["وَٱلَّذِينَ","Dan mereka (kepada) mereka"],["ءَاتَيْنَـٰهُمُ","Kami telah memberi mereka"],["ٱلْكِتَـٰبَ","Kitab"],["يَفْرَحُونَ","bergembiralah"],["بِمَآ","pada apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْكَ ۖ","kepada kamu"],["وَمِنَ","tetapi antara"],["ٱلْأَحْزَابِ","kumpulan-kumpulan tersebut"],["مَن","(mereka) yang"],["يُنكِرُ","menafikan"],["بَعْضَهُۥ ۚ","sebahagian daripadanya"],["قُلْ","Katakanlah"],["إِنَّمَآ","Hanya"],["أُمِرْتُ","Aku telah diperintahkan"],["أَنْ","bahawa"],["أَعْبُدَ","aku menyembah"],["ٱللَّهَ","Allah"],["وَلَآ","dan bukan"],["أُشْرِكَ","Aku mengaitkan rakan kongsi"],["بِهِۦٓ ۚ","dengan Dia"],["إِلَيْهِ","KepadaNya"],["أَدْعُوا۟","aku panggil"],["وَإِلَيْهِ","dan kepada-Nya"],["مَـَٔابِ","(adalah) kepulangan aku"]]],"1744":["(Dan demikianlah) penurunan itu (Kami telah menurunkannya) Alquran itu (sebagai peraturan dalam bahasa Arab) yaitu dengan memakai bahasa Arab, yang dengannya engkau putuskan hukum-hukum di antara manusia. (Dan seandainya kamu mengikuti hawa nafsu mereka) hawa nafsu orang-orang kafir, dalam hal apa yang mereka inginkan, supaya kamu melakukannya menurut peraturan agama mereka. Ini hanyalah merupakan perumpamaan (setelah datang pengetahuan kepadamu) tentang tauhid (maka sekali-kali tidak ada bagimu terhadap Allah) huruf min di sini adalah zaidah (seorang penolong pun) penolong yang mau membantu menyelamatkanmu (dan tidak pula seorang pemelihara) yang dapat mencegah azab Allah yang menimpa dirimu.",[["وَكَذَٰلِكَ","Dan dengan demikian"],["أَنزَلْنَـٰهُ","Kami telah mendedahkannya"],["حُكْمًا","(menjadi) penghakiman pihak berkuasa"],["عَرَبِيًّۭا ۚ","(dalam) bahasa Arab"],["وَلَئِنِ","Dan jika"],["ٱتَّبَعْتَ","kamu ikut"],["أَهْوَآءَهُم","keinginan mereka"],["بَعْدَ مَا","selepas apa"],["جَآءَكَ","datang kepada kamu"],["مِنَ","daripada"],["ٱلْعِلْمِ","pengetahuan itu"],["مَا","tidak"],["لَكَ","bagi kamu"],["مِنَ","terhadap"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["وَلِىٍّۢ","pelindung"],["وَلَا","dan bukan"],["وَاقٍۢ","pertahanan"]]],"1745":["Ayat ini diturunkan ketika orang-orang kafir mencela Nabi saw. karena istrinya banyak, yaitu: (Dan sesungguhnya Kami telah mengutus beberapa rasul sebelum kamu dan Kami memberikan kepada mereka istri-istri dan keturunan) yakni anak-anak, sedangkan engkau adalah salah satu di antara para rasul itu. (Dan tidak ada hak bagi seorang rasul) di antara para rasul itu (mendatangkan sesuatu ayat melainkan dengan izin Allah) karena para rasul itu tiada lain hanyalah hamba-hamba yang diasuh-Nya. (Bagi tiap-tiap masa) zaman (ada kitab) yang tertera di dalamnya tentang batas masa berlakunya.",[["وَلَقَدْ","Dan sungguh"],["أَرْسَلْنَا","Kami utus"],["رُسُلًۭا","Utusan"],["مِّن","daripada"],["قَبْلِكَ","sebelum kamu"],["وَجَعَلْنَا","dan Kami jadikan"],["لَهُمْ","bagi mereka"],["أَزْوَٰجًۭا","isteri-isteri"],["وَذُرِّيَّةًۭ ۚ","dan zuriat"],["وَمَا","Dan tidak"],["كَانَ","adalah"],["لِرَسُولٍ","untuk seorang Rasul"],["أَن","bahawa"],["يَأْتِىَ","dia datang"],["بِـَٔايَةٍ","dengan tanda"],["إِلَّا","kecuali"],["بِإِذْنِ","dengan cuti"],["ٱللَّهِ ۗ","(milik) Allah"],["لِكُلِّ","Untuk segala-galanya"],["أَجَلٍۢ","(adalah) suatu masa"],["كِتَابٌۭ","ditetapkan"]]],"1746":["(Allah menghapuskan) daripada kitab itu (apa yang dikehendaki-Nya dan menetapkan) dapat dibaca yutsbitu atau yutsabbitu, artinya hukum-hukum dan masalah-masalah lainnya yang dikehendaki-Nya untuk dihapus atau ditetapkan (dan di sisi-Nyalah terdapat Ummul Kitab) asal kitab yang tidak berubah sedikit pun daripadanya, yaitu kitab-kitab-Nya di zaman azali.",[["يَمْحُوا۟","(Adalah) dihapuskan"],["ٱللَّهُ","(oleh) Allah"],["مَا","apa"],["يَشَآءُ","Dia kehendaki"],["وَيُثْبِتُ ۖ","dan mengesahkan"],["وَعِندَهُۥٓ","dan dengan Dia"],["أُمُّ","(ialah) Ibu (dari) Kitab"],["ٱلْكِتَـٰبِ","(ialah) Ibu (dari) Kitab"]]],"1747":["(Dan jika) asalnya lafal immaa ini terdiri daripada in syarthiyah dan maa zaidah, kemudian keduanya dijadikan satu sehingga jadilah immaa, artinya seandainya (Kami perlihatkan kepadamu sebagian apa yang Kami ancamkan kepada mereka) yaitu sebagian daripada azab-Ku sewaktu kamu masih hidup. Jawab dari in syarthiyah tidak disebutkan, lengkapnya ialah fadzaaka: itulah azab-Ku (atau Kami wafatkan kamu) sebelum orang-orang kafir itu diazab (karena sesungguhnya tugasmu hanya menyampaikan saja) hal itu tidak penting bagimu, tugasmu tiada lain hanya menyampaikan (sedangkan Kamilah yang menghisab amalan mereka) jika mereka telah kembali kepada Kami, maka Kami akan membalas semua amal perbuatan mereka.",[["وَإِن","Dan sama ada"],["مَّا","(apa)"],["نُرِيَنَّكَ","Kami tunjukkan kepada kamu"],["بَعْضَ","bahagian"],["ٱلَّذِى","apa"],["نَعِدُهُمْ","Kami telah berjanji kepada mereka"],["أَوْ","atau"],["نَتَوَفَّيَنَّكَ","Kami menyebabkan kamu mati"],["فَإِنَّمَا","jadi sahaja"],["عَلَيْكَ","pada kamu"],["ٱلْبَلَـٰغُ","(ialah) pengangkutan"],["وَعَلَيْنَا","dan pada Kami"],["ٱلْحِسَابُ","(ialah) hisab"]]],"1748":["(Dan apakah mereka tidak melihat) yang dimaksud adalah penduduk Mekah (bahwa sesungguhnya Kami mendatangkan daerah-daerah) orang-orang kafir (lalu Kami kurangi daerah-daerah itu dari tepi-tepinya?) yaitu melalui pembukaan/penaklukan yang dilakukan oleh Nabi saw. (Dan Allah menetapkan hukum) atas makhluk-Nya menurut kehendak-Nya (tidak ada yang dapat menolak) tiada seorang pun yang dapat menolak (ketetapan-Nya; dan Dialah Yang Maha Cepat hisab-Nya.)",[["أَوَلَمْ","tidak"],["يَرَوْا۟","mereka lihat"],["أَنَّا","bahawa Kami"],["نَأْتِى","datang"],["ٱلْأَرْضَ","(ke) tanah"],["نَنقُصُهَا","mengurangkannya"],["مِنْ","daripada"],["أَطْرَافِهَا ۚ","sempadannya"],["وَٱللَّهُ","Dan Allah"],["يَحْكُمُ","hakim"],["لَا","(ada) tidak"],["مُعَقِّبَ","pelaras"],["لِحُكْمِهِۦ ۚ","(dari) Penghakiman-Nya"],["وَهُوَ","Dan Dia"],["سَرِيعُ","(ialah) Swift"],["ٱلْحِسَابِ","(dalam) hisab"]]],"1749":["(Dan sungguh orang-orang kafir yang sebelum mereka telah mengadakan tipu-daya) yang dimaksud adalah umat-umat terdahulu sebelum orang-orang kafir Mekah; mereka telah berbuat makar terhadap nabi-nabi-Nya sebagaimana orang-orang kafir Mekah telah berbuat makar terhadapmu (tetapi semua tipu-daya itu adalah dalam kekuasaan Allah) tipu daya mereka tidaklah sama dengan tipu daya-Nya, karena Allah swt. (Dia mengetahui apa yang diusahakan oleh setiap diri) maka untuk itu Dia telah mempersiapkan balasan usaha itu; dan inilah yang dinamakan tipu daya secara keseluruhan. Karena sesungguhnya balasan itu menimpa mereka sewaktu mereka tidak menyadarinya. (Dan orang-orang kafir akan mengetahui) lafal al-kaafir yang dimaksud adalah makna jenis sehingga artinya menunjukkan jamak sekalipun lafalnya mufrad. Akan tetapi menurut qiraat yang lain dibaca al-kuffaaru dalam bentuk jamak (untuk siapakah tempat kesudahan yang baik itu) akibat yang paling baik di akhirat kelak; apakah untuk mereka ataukah untuk Nabi saw. dan para sahabatnya?",[["وَقَدْ","Dan sungguh"],["مَكَرَ","diplot"],["ٱلَّذِينَ","orang yang"],["مِن","(adalah) dari"],["قَبْلِهِمْ","sebelum mereka"],["فَلِلَّهِ","tetapi kerana Allah"],["ٱلْمَكْرُ","(ialah) plot"],["جَمِيعًۭا ۖ","semua"],["يَعْلَمُ","Dia tahu"],["مَا","apa"],["تَكْسِبُ","memperolehi"],["كُلُّ","setiap"],["نَفْسٍۢ ۗ","jiwa"],["وَسَيَعْلَمُ","dan akan tahu"],["ٱلْكُفَّـٰرُ","orang kafir"],["لِمَنْ","untuk siapa"],["عُقْبَى","(adalah) final"],["ٱلدَّارِ","rumah itu"]]],"1750":["(Berkatalah orang-orang kafir) kepadamu (\"Kamu bukan seorang yang dijadikan rasul.\" Katakanlah) kepada mereka (\"Cukuplah Allah menjadi saksi antaraku dan kalian) atas kebenaranku (dan antara orang yang mempunyai ilmu Kitab.\") dari kalangan orang-orang yang beriman, Yahudi dan Nasrani.",[["وَيَقُولُ","Dan katakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَسْتَ","kamu bukan"],["مُرْسَلًۭا ۚ","seorang Rasul"],["قُلْ","Katakanlah"],["كَفَىٰ","Memadai"],["بِٱللَّهِ","(ialah) Allah"],["شَهِيدًۢا","(sebagai) seorang Saksi"],["بَيْنِى","antara aku"],["وَبَيْنَكُمْ","dan antara kamu"],["وَمَنْ","dan sesiapa"],["عِندَهُۥ","[dia] mempunyai"],["عِلْمُ","pengetahuan"],["ٱلْكِتَـٰبِ","Kitab"]]],"1751":["(Alif laam raa) hanya Allahlah yang mengetahui maksudnya. Alquran ini adalah (Kitab yang Kami turunkan kepadamu) Muhammad (supaya kamu mengeluarkan manusia dari kegelapan) dari kekafiran (kepada cahaya) yaitu agama Islam. (Dengan izin) perintah (Rabb mereka) lafal an-nuur diterangkan secara jelas pada ayat berikut ini: (yaitu ke jalan) tuntunan (Tuhan Yang Maha Perkasa) Maha Menang (lagi Maha Terpuji.) Yang Maha Terpuji.",[["الٓر ۚ","Alif Laam Ra"],["كِتَـٰبٌ","Sebuah Buku"],["أَنزَلْنَـٰهُ","yang telah Kami wahyukan"],["إِلَيْكَ","kepada kamu"],["لِتُخْرِجَ","supaya kamu boleh membawa keluar"],["ٱلنَّاسَ","umat manusia"],["مِنَ","daripada"],["ٱلظُّلُمَـٰتِ","kegelapan[es]"],["إِلَى","kepada"],["ٱلنُّورِ","cahaya itu"],["بِإِذْنِ","dengan izin"],["رَبِّهِمْ","(dari) Tuhan mereka"],["إِلَىٰ","kepada"],["صِرَٰطِ","Jalan"],["ٱلْعَزِيزِ","(dari) Yang Maha Perkasa"],["ٱلْحَمِيدِ","yang Terpuji"]]],"1752":["(Dialah Allah) kalau dibaca jar kedudukannya menjadi badal atau athaf bayan, sedangkan kedudukan kalimat yang sesudahnya menjadi sifat. Jika dibaca rafa` jadilah mubtada, sedangkan khabarnya adalah firman berikut ini: (yang memiliki segala apa yang ada di langit dan di bumi) semuanya adalah milik-Nya, hamba-Nya dan makhluk-Nya. (Dan kecelakaanlah bagi orang-orang kafir karena siksa yang sangat pedih.)",[["ٱللَّهِ","Allah"],["ٱلَّذِى","(ialah) Yang Esa"],["لَهُۥ","kepada-Nya (milik)"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۗ","bumi"],["وَوَيْلٌۭ","Dan celaka"],["لِّلْكَـٰفِرِينَ","kepada orang-orang kafir"],["مِنْ","daripada"],["عَذَابٍۢ","azab"],["شَدِيدٍ","teruk"]]],"1753":["(Yaitu orang-orang) kedudukannya sebagai sifat (yang lebih menyukai kehidupan dunia daripada kehidupan akhirat dan menghalang-halangi) manusia (dari jalan Allah) yaitu agama Islam (dan menginginkan supaya ia) jalan Allah tersebut (bengkok) tidak lurus. (Mereka itu berada dalam kesesatan yang jauh) yakni sesat dari jalan yang hak dan benar.",[["ٱلَّذِينَ","Orang yang"],["يَسْتَحِبُّونَ","lebih sayang"],["ٱلْحَيَوٰةَ","kehidupan"],["ٱلدُّنْيَا","dunia"],["عَلَى","daripada"],["ٱلْـَٔاخِرَةِ","akhirat"],["وَيَصُدُّونَ","dan menghalang"],["عَن","daripada"],["سَبِيلِ","(the) Jalan"],["ٱللَّهِ","(milik) Allah"],["وَيَبْغُونَهَا","dan carilah di dalamnya"],["عِوَجًا ۚ","kebengkokan"],["أُو۟لَـٰٓئِكَ","mereka"],["فِى","[dalam]"],["ضَلَـٰلٍۭ","(adalah) sesat jauh"],["بَعِيدٍۢ","(adalah) sesat jauh"]]],"1754":["(Kami tidak mengutus seorang rasul pun melainkan dengan bahasa) memakai bahasa (kaumnya, supaya ia dapat memberi pelajaran dengan terang kepada mereka) supaya mereka dapat memahami apa yang disampaikannya. (Maka Allah menyesatkan siapa yang Dia kehendaki dan memberi petunjuk kepada siapa yang Dia kehendaki. Dan Dialah Tuhan Yang Maha Kuasa) di dalam kerajaan-Nya (lagi Maha Bijaksana.) di dalam tindakan-Nya.",[["وَمَآ","Dan tidak"],["أَرْسَلْنَا","Kami utus"],["مِن","sebarang"],["رَّسُولٍ","Utusan"],["إِلَّا","kecuali"],["بِلِسَانِ","dengan bahasa"],["قَوْمِهِۦ","(dari) kaumnya"],["لِيُبَيِّنَ","supaya dia dapat menjelaskan"],["لَهُمْ ۖ","bagi mereka"],["فَيُضِلُّ","Kemudian Allah biarkan sesat"],["ٱللَّهُ","Kemudian Allah biarkan sesat"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["وَيَهْدِى","dan panduan"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَهُوَ","Dan Dia"],["ٱلْعَزِيزُ","(ialah) Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"1755":["(Dan sesungguhnya Kami telah mengutus Musa dengan membawa ayat-ayat Kami) yang berjumlah sembilan ayat lalu Kami firmankan kepadanya (\"Keluarkanlah kaummu) yaitu kaum Bani Israel (dari gelap-gulita) dari kekafiran (kepada cahaya yang terang-benderang) yaitu keimanan (dan ingatkanlah mereka kepada hari-hari Allah.\") yakni nikmat-nikmat-Nya. (Sesungguhnya pada yang demikian itu) yakni di dalam peringatan itu (terdapat tanda-tanda bagi setiap orang penyabar) di dalam mengerjakan ketaatan (dan banyak bersyukur) terhadap semua nikmat-nikmat-Nya.",[["وَلَقَدْ","Dan sesungguhnya"],["أَرْسَلْنَا","Kami utus"],["مُوسَىٰ","Musa"],["بِـَٔايَـٰتِنَآ","dengan Tanda-tanda Kami"],["أَنْ","bahawa"],["أَخْرِجْ","Bawa keluar"],["قَوْمَكَ","orang kamu"],["مِنَ","daripada"],["ٱلظُّلُمَـٰتِ","kegelapan[es]"],["إِلَى","kepada"],["ٱلنُّورِ","cahaya itu"],["وَذَكِّرْهُم","Dan ingatkan mereka"],["بِأَيَّىٰمِ","hari-hari"],["ٱللَّهِ ۚ","(milik) Allah"],["إِنَّ","Sesungguhnya"],["فِى","dalam"],["ذَٰلِكَ","bahawa"],["لَـَٔايَـٰتٍۢ","sesungguhnya (adalah) tanda-tandanya"],["لِّكُلِّ","untuk semua orang"],["صَبَّارٍۢ","sabar"],["شَكُورٍۢ","dan bersyukur"]]],"1756":["(Dan) ingatlah (ketika Musa berkata kepada kaumnya, \"Ingatlah nikmat Allah atas kalian ketika Dia menyelamatkan kalian dari Firaun dan pengikut-pengikutnya; mereka menyiksa kalian dengan siksa yang pedih, mereka menyembelih anak laki-laki kalian) yang baru lahir (dan membiarkan hidup) membiarkan tetap hidup (anak-anak perempuan) karena ada sebagian tukang tenung yang mengatakan bahwasanya akan lahir seorang anak lelaki dari kalangan kaum Bani Israel, dia adalah penyebab bagi runtuhnya kerajaan Firaun. (Sesungguhnya pada yang demikian itu) penyelamatan atau penyiksaan (ada cobaan) baik berupa pemberian nikmat maupun penimpaan malapetaka (yang besar dari Rabb kalian.\")",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["مُوسَىٰ","Musa"],["لِقَوْمِهِ","kepada umatnya"],["ٱذْكُرُوا۟","Ingat"],["نِعْمَةَ","(kenikmatan) Allah"],["ٱللَّهِ","(kenikmatan) Allah"],["عَلَيْكُمْ","ke atas kamu"],["إِذْ","apabila"],["أَنجَىٰكُم","Dia selamatkan kamu"],["مِّنْ","daripada"],["ءَالِ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["يَسُومُونَكُمْ","mereka menindas kamu"],["سُوٓءَ","(dengan) kejahatan"],["ٱلْعَذَابِ","azab"],["وَيُذَبِّحُونَ","dan sedang menyembelih"],["أَبْنَآءَكُمْ","anak lelaki kamu"],["وَيَسْتَحْيُونَ","dan membiarkan hidup"],["نِسَآءَكُمْ ۚ","wanita kamu"],["وَفِى","Dan dalam"],["ذَٰلِكُم","bahawa"],["بَلَآءٌۭ","(adalah) percubaan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["عَظِيمٌۭ","yang besar"]]],"1757":["(Dan ingatlah pula ketika mempermaklumkan) memberitahukan (Rabb kalian sesungguhnya jika kalian bersyukur) akan nikmat-Ku dengan menjalankan ketauhidan dan ketaatan (pasti Kami akan menambah nikmat kepada kalian dan jika kalian mengingkari nikmat-Ku) apabila kalian ingkar terhadap nikmat-Ku itu dengan berlaku kekafiran dan kedurhakaan niscaya Aku akan menurunkan azab kepada kalian. Pengertian ini diungkapkan oleh firman selanjutnya: (\"Sesungguhnya azab-Ku sangat keras.\")",[["وَإِذْ","Dan apabila"],["تَأَذَّنَ","diisytiharkan"],["رَبُّكُمْ","Tuhanmu"],["لَئِن","Jika"],["شَكَرْتُمْ","kamu bersyukur"],["لَأَزِيدَنَّكُمْ ۖ","nescaya Aku akan menambah kepadamu"],["وَلَئِن","tetapi jika"],["كَفَرْتُمْ","kamu tidak bersyukur"],["إِنَّ","sesungguhnya"],["عَذَابِى","hukuman aku"],["لَشَدِيدٌۭ","(adalah) pasti teruk"]]],"1758":["(Dan Musa berkata) kepada kaumnya (\"Jika kalian dan orang-orang yang ada di muka bumi semuanya mengingkari nikmat Allah, maka sesungguhnya Allah Maha Kaya) tidak membutuhkan makhluk-Nya (lagi Maha Terpuji.\") Maha Terpuji di dalam tindakan-Nya terhadap mereka.",[["وَقَالَ","Dan berkata"],["مُوسَىٰٓ","Musa"],["إِن","Jika"],["تَكْفُرُوٓا۟","kamu tidak beriman"],["أَنتُمْ","kamu"],["وَمَن","dan sesiapa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["جَمِيعًۭا","semua"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["لَغَنِىٌّ","sudah tentu (adalah) Bebas daripada keperluan"],["حَمِيدٌ","terpuji"]]],"1759":["(Belumkah sampai kepada kalian) Istifham atau kata tanya di sini mengandung makna menetapkan (berita) kisah (tentang orang-orang sebelum kalian, yaitu kaum Nuh dan Ad) kaum Nabi Hud (dan Tsamud) kaum Nabi Saleh (dan orang-orang sesudah mereka, yang tiada seorang pun mengetahui jumlah mereka selain Allah) karena saking banyaknya. (Telah datang rasul-rasul kepada mereka dengan membawa bukti-bukti yang nyata) yakni dengan membawa hujah-hujah yang jelas untuk membuktikan kebenaran mereka (lalu mereka menutupkan) yang dimaksud adalah umat-umat terdahulu itu (tangan mereka ke mulutnya) dengan menggigitnya sebagai pertanda kebencian mereka yang sangat terhadap ajakan para rasul itu (dan berkata, \"Sesungguhnya kami mengingkari apa yang kalian disuruh menyampaikannya) menurut anggapan kalian itu (dan sesungguhnya kami benar-benar dalam keraguan yang menggelisahkan terhadap apa yang kalian ajak kami kepadanya.\") artinya mereka benar-benar ragu terhadapnya.",[["أَلَمْ","belum"],["يَأْتِكُمْ","datang kepada kamu"],["نَبَؤُا۟","(the) berita"],["ٱلَّذِينَ","orang yang"],["مِن","(ada) sebelum kamu"],["قَبْلِكُمْ","(ada) sebelum kamu"],["قَوْمِ","manusia"],["نُوحٍۢ","daripada Nuh"],["وَعَادٍۢ","dan Aad"],["وَثَمُودَ ۛ","dan kaum Thamud"],["وَٱلَّذِينَ","dan orang yang"],["مِنۢ","(ada) selepas mereka"],["بَعْدِهِمْ ۛ","(ada) selepas mereka"],["لَا","tiada"],["يَعْلَمُهُمْ","mengenali mereka"],["إِلَّا","kecuali"],["ٱللَّهُ ۚ","Allah"],["جَآءَتْهُمْ","Datang kepada mereka"],["رُسُلُهُم","Rasul-rasul mereka"],["بِٱلْبَيِّنَـٰتِ","dengan bukti yang jelas"],["فَرَدُّوٓا۟","tetapi mereka kembali"],["أَيْدِيَهُمْ","tangan mereka"],["فِىٓ","dalam"],["أَفْوَٰهِهِمْ","mulut mereka"],["وَقَالُوٓا۟","dan mereka berkata"],["إِنَّا","Sesungguhnya kita"],["كَفَرْنَا","[kita] tidak beriman"],["بِمَآ","pada apa"],["أُرْسِلْتُم","kamu telah dihantar"],["بِهِۦ","dengan [ia]"],["وَإِنَّا","dan sesungguhnya, kita"],["لَفِى","(ada) pasti dalam"],["شَكٍّۢ","keraguan"],["مِّمَّا","tentang apa"],["تَدْعُونَنَآ","kamu menjemput kami"],["إِلَيْهِ","kepadanya"],["مُرِيبٍۢ","mencurigakan"]]],"1760":["(Berkata rasul-rasul mereka, \"Apakah ada keraguan terhadap Allah) istifham di sini mengandung makna ingkar; artinya tentu saja tidak ada keraguan di dalam mentauhidkan-Nya mengingat adanya bukti-bukti yang jelas menunjukkan ke arah itu (Pencipta) yang menciptakan (langit dan bumi? Dia menyeru kalian) supaya taat kepada-Nya (untuk memberi ampunan kepada kalian dari dosa-dosa kalian) huruf min adalah huruf zaidah. Karena sesungguhnya Islam itu menghapus semua dosa yang sebelumnya. Atau huruf min itu bermakna tab`idh yang artinya sebagian daripada dosa-dosa kalian. Dimaksud untuk mengecualikan dosa-dosa yang menyangkut hak-hak hamba-hamba Allah (dan menangguhkan kalian) tanpa mengazab kalian (sampai masa yang ditentukan?\") sampai kalian mati. (Mereka berkata, \"Tiada lain) tidak lain (kalian adalah manusia biasa seperti kami juga. Kalian menghendaki untuk menghalang-halangi kami dari apa yang selalu disembah oleh nenek moyang kami) yaitu berhala-berhala sesembahan mereka (karena itu datangkanlah kepada kami bukti yang nyata.\") hujah yang jelas untuk membuktikan kebenaran kalian itu.",[["۞ قَالَتْ","Berkata"],["رُسُلُهُمْ","Rasul-rasul mereka"],["أَفِى","Boleh (ada) kira-kira"],["ٱللَّهِ","Allah"],["شَكٌّۭ","sebarang keraguan"],["فَاطِرِ","(the) Pencipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["يَدْعُوكُمْ","Dia menjemput kamu"],["لِيَغْفِرَ","supaya Dia mengampuni"],["لَكُم","bagi kamu"],["مِّن","[daripada]"],["ذُنُوبِكُمْ","dosa kamu"],["وَيُؤَخِّرَكُمْ","dan memberi kamu tangguh"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["مُّسَمًّۭى ۚ","dilantik"],["قَالُوٓا۟","Mereka berkata"],["إِنْ","Tidak"],["أَنتُمْ","kamu"],["إِلَّا","(adalah) tetapi"],["بَشَرٌۭ","seorang manusia"],["مِّثْلُنَا","seperti kita"],["تُرِيدُونَ","kamu mahu"],["أَن","kepada"],["تَصُدُّونَا","menghalang kami"],["عَمَّا","daripada apa"],["كَانَ","dulu"],["يَعْبُدُ","ibadah"],["ءَابَآؤُنَا","nenek moyang kita"],["فَأْتُونَا","Jadi bawa kami"],["بِسُلْطَـٰنٍۢ","sebuah pihak berkuasa"],["مُّبِينٍۢ","yang nyata"]]],"1761":["(Rasul-rasul mereka berkata kepada mereka, \"Tiada lain) tidak lain (kami ini hanyalah manusia biasa sama dengan kalian) persis seperti apa yang kalian katakan itu (akan tetapi Allah memberi karunia kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya) berupa kenabian. (Dan tidak patut) tidak layak (bagi kami mendatangkan suatu bukti kepada kalian melainkan dengan izin Allah) berdasarkan perintah-Nya karena sesungguhnya kami ini adalah hamba-hamba yang dipelihara oleh-Nya (Dan hanya kepada Allah sajalah hendaknya orang-orang yang beriman bertawakal.\") hanya percaya kepada-Nya.",[["قَالَتْ","Berkata"],["لَهُمْ","kepada mereka"],["رُسُلُهُمْ","Rasul-rasul mereka"],["إِن","Tidak"],["نَّحْنُ","kami (adalah)"],["إِلَّا","tetapi"],["بَشَرٌۭ","seorang manusia"],["مِّثْلُكُمْ","macam kamu"],["وَلَـٰكِنَّ","tetapi"],["ٱللَّهَ","Allah"],["يَمُنُّ","melimpahkan RahmatNya"],["عَلَىٰ","pada"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦ ۖ","hambanya"],["وَمَا","Dan tidak"],["كَانَ","ialah"],["لَنَآ","bagi kami"],["أَن","bahawa"],["نَّأْتِيَكُم","kami bawakan kamu"],["بِسُلْطَـٰنٍ","sebuah pihak berkuasa"],["إِلَّا","kecuali"],["بِإِذْنِ","dengan izin Allah"],["ٱللَّهِ ۚ","dengan izin Allah"],["وَعَلَى","Dan selepas"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","maka hendaklah meletakkan amanah (mereka)."],["ٱلْمُؤْمِنُونَ","orang yang beriman"]]],"1762":["(\"Mengapa kami) huruf allaa asalnya adalah gabungan daripada an dan laa (tidak bertawakal kepada Allah) artinya tidak ada yang melarang kami untuk melakukan hal tersebut (padahal Dia telah menunjukkan jalan kepada kami dan kami sungguh-sungguh akan bersabar terhadap perlakuan-perlakuan kalian yang menyakitkan kami) di dalam menghadapi gangguan-gangguan yang kalian lakukan terhadap kami. (Dan hanya kepada Allah saja orang-orang yang bertawakal berserah diri.\")",[["وَمَا","Dan apa"],["لَنَآ","(adalah) untuk kita"],["أَلَّا","itu tidak"],["نَتَوَكَّلَ","kami meletakkan kepercayaan kami"],["عَلَى","ke atas"],["ٱللَّهِ","Allah"],["وَقَدْ","sedangkan pastinya"],["هَدَىٰنَا","Dia telah membimbing kita"],["سُبُلَنَا ۚ","kepada cara kita"],["وَلَنَصْبِرَنَّ","Dan sesungguhnya kami akan bersabar"],["عَلَىٰ","pada"],["مَآ","apa"],["ءَاذَيْتُمُونَا ۚ","kemudaratan yang kamu boleh menyebabkan kami"],["وَعَلَى","Dan selepas"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","maka hendaklah meletakkan amanah (mereka)."],["ٱلْمُتَوَكِّلُونَ","orang-orang yang bertawakkal"]]],"1763":["(Orang-orang kafir berkata kepada rasul-rasul mereka, \"Kami sungguh-sungguh akan mengusir kalian dari negeri kami atau kalian kembali) menjadi pemeluk (kepada tuntunan kami.\") yakni agama kami. (Maka Rabb mewahyukan kepada mereka, \"Kami pasti akan membinasakan orang-orang yang lalim itu.\") yakni orang-orang kafir itu.",[["وَقَالَ","Dan berkata"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لِرُسُلِهِمْ","kepada Rasul-rasul mereka"],["لَنُخْرِجَنَّكُم","Pasti kami akan menghalau kamu"],["مِّنْ","daripada"],["أَرْضِنَآ","tanah kita"],["أَوْ","atau"],["لَتَعُودُنَّ","pasti kamu harus kembali"],["فِى","kepada"],["مِلَّتِنَا ۖ","agama kita"],["فَأَوْحَىٰٓ","Jadi terinspirasi"],["إِلَيْهِمْ","kepada mereka"],["رَبُّهُمْ","Tuhan mereka"],["لَنُهْلِكَنَّ","Kami pasti akan memusnahkan"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"1764":["(\"Dan Kami pasti akan menempatkan kalian di negeri-negeri itu) di negeri tempat mereka tinggal (sesudah mereka) dibinasakan. (Yang demikian itu) yakni pertolongan dan mewariskan negeri itu (adalah untuk orang-orang yang takut akan menghadap kepada-Ku) pada hari ia menghadap kepada-Nya (dan yang takut kepada ancaman-Ku.\") takut kepada azab-Ku.",[["وَلَنُسْكِنَنَّكُمُ","Dan sesungguhnya Kami akan menempatkan kamu"],["ٱلْأَرْضَ","(dalam) tanah"],["مِنۢ","selepas mereka"],["بَعْدِهِمْ ۚ","selepas mereka"],["ذَٰلِكَ","Itu"],["لِمَنْ","(adalah) untuk sesiapa sahaja"],["خَافَ","ketakutan"],["مَقَامِى","berdiri di hadapan-Ku"],["وَخَافَ","dan ketakutan"],["وَعِيدِ","Ancaman Aku"]]],"1765":["(Dan mereka memohon kemenangan) para rasul itu memohon pertolongan Allah di dalam menghadapi kaumnya (dan merugilah) binasalah (setiap orang yang berlaku sewenang-wenang) setiap orang yang takabur tidak mau taat kepada Allah (lagi keras kepala) artinya tidak mau tunduk kepada perkara yang hak.",[["وَٱسْتَفْتَحُوا۟","Dan mereka mencari kemenangan"],["وَخَابَ","dan kecewa"],["كُلُّ","setiap"],["جَبَّارٍ","zalim"],["عَنِيدٍۢ","degil"]]],"1766":["(Di hadapannya) di depannya (ada Jahanam) yang akan dimasukinya (dan dia akan diberi minum) di dalam Jahanam itu (dengan air nanah) yaitu cairan yang meleleh dari perut ahli neraka bercampur dengan nanah dan darah.",[["مِّن","daripada dia"],["وَرَآئِهِۦ","Di hadapan"],["جَهَنَّمُ","(ialah) Neraka"],["وَيُسْقَىٰ","dan dia akan diberi minum"],["مِن","daripada"],["مَّآءٍۢ","air"],["صَدِيدٍۢ","bernanah"]]],"1767":["(Diminumnya air nanah itu) diteguknya air nanah itu seteguk demi seteguk karena rasanya teramat pahit (dan hampir dia tidak dapat menelannya) ia merasa amat jijik mengingat baunya yang sangat busuk dan rupanya yang sangat menjijikkan (dan datanglah bahaya maut kepadanya) hal-hal yang menyebabkan kematian, berupa berbagai macam azab (dari segenap penjuru, tetapi dia tidak juga mati dan di hadapannya) sesudah mengalami azab tersebut (masih ada siksaan yang berat) siksaan yang keras lagi terus-menerus.",[["يَتَجَرَّعُهُۥ","Dia akan menghirupnya"],["وَلَا","tetapi tidak"],["يَكَادُ","dia akan dekat"],["يُسِيغُهُۥ","(untuk) menelannya"],["وَيَأْتِيهِ","Dan akan datang kepadanya"],["ٱلْمَوْتُ","kematian itu"],["مِن","daripada"],["كُلِّ","setiap"],["مَكَانٍۢ","sebelah"],["وَمَا","tetapi tidak"],["هُوَ","dia"],["بِمَيِّتٍۢ ۖ","akan mati"],["وَمِن","Dan di hadapannya"],["وَرَآئِهِۦ","Dan di hadapannya"],["عَذَابٌ","(ialah) azab"],["غَلِيظٌۭ","keras"]]],"1768":["(Perumpamaan) gambaran (tentang orang-orang yang ingkar kepada Rabb mereka) kalimat ayat ini berkedudukan menjadi mubtada kemudian dijelaskan oleh badalnya pada firman selanjutnya, yaitu: (amalan-amalan mereka) yang baik, seperti silaturahmi dan sedekah, yaitu dalam hal tiada kemanfaatan (seperti abu yang ditiup angin dengan keras pada suatu hari yang berangin keras) sangat keras tiupannya sehingga angin keras itu menjadikannya debu-debu yang beterbangan yang tiada manfaatnya. Jar dan majrurnya merupakan khabar daripada mubtada (mereka tidak dapat) yakni orang-orang kafir itu (mengambil manfaat dari apa yang telah mereka upayakan itu) dari apa yang telah mereka amalkan sewaktu di dunia (barang sedikit pun) artinya mereka sama sekali tidak menemukan pahala daripada amal-amal mereka karena tidak memenuhi syarat, yaitu tiadanya iman. (Yang demikian itu adalah kesesatan) kebinasaan (yang jauh.)",[["مَّثَلُ","(The) contoh"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["بِرَبِّهِمْ ۖ","pada Tuhan mereka"],["أَعْمَـٰلُهُمْ","perbuatan mereka"],["كَرَمَادٍ","(adalah) seperti abu"],["ٱشْتَدَّتْ","bertiup kencang"],["بِهِ","di atasnya"],["ٱلرِّيحُ","angin"],["فِى","dalam"],["يَوْمٍ","sehari"],["عَاصِفٍۢ ۖ","ribut"],["لَّا","Tidak"],["يَقْدِرُونَ","mengawal (mereka ada)"],["مِمَّا","tentang apa"],["كَسَبُوا۟","mereka telah perolehi"],["عَلَىٰ","pada"],["شَىْءٍۢ ۚ","sesuatu"],["ذَٰلِكَ","Itu"],["هُوَ","[ia]"],["ٱلضَّلَـٰلُ","(ialah) yang sesat"],["ٱلْبَعِيدُ","jauh"]]],"1769":["(Tidakkah kamu perhatikan) hai orang yang diajak bicara, tidakkah kamu memperhatikan. Istifham atau kata tanya di sini mengandung makna menetapkan (bahwa sesungguhnya Allah telah menciptakan langit dan bumi dengan hak) lafal bilhaqqi bertaalluq atau berkaitan maknanya dengan lafal khalaqa. (Jika Dia menghendaki, niscaya Dia membinasakan kalian) hai manusia (dan mengganti kalian dengan makhluk yang baru) sebagai pengganti kalian.",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["بِٱلْحَقِّ ۚ","dalam kebenaran"],["إِن","Jika"],["يَشَأْ","Dia kehendaki"],["يُذْهِبْكُمْ","Dia boleh mengeluarkan kamu"],["وَيَأْتِ","dan bawa"],["بِخَلْقٍۢ","sebuah ciptaan"],["جَدِيدٍۢ","baru"]]],"1770":["(Dan yang demikian itu sekali-kali tidak sukar bagi Allah) tidak sulit bagi-Nya.",[["وَمَا","Dan tidak"],["ذَٰلِكَ","(ialah) itu"],["عَلَى","pada"],["ٱللَّهِ","Allah"],["بِعَزِيزٍۢ","yang besar"]]],"1771":["(Dan mereka akan berkumpul menghadap) semua makhluk itu menghadap. Ungkapan pada ayat ini dan ayat sebelumnya memakai fi`il madhi, dimaksud untuk memberikan pengertian kepastian bahwa hal itu benar-benar akan terjadi (kepada Allah semuanya, lalu berkatalah orang-orang yang lemah) yakni para pengikut (kepada orang-orang yang sombong) yaitu orang-orang yang diikuti (\"Sesungguhnya kami dahulu adalah pengikut-pengikut kalian) lafal taba`an merupakan bentuk jamak dari kata tunggal tabi`un (maka dapatkah kalian menghindarkan) menolak (daripada kami azab Allah walau sedikit saja?\") huruf min yang pertama tadi bermakna lit-tabyin atau untuk menjelaskan, sedangkan huruf min pada ayat ini bermakna lit-tab`idh atau menunjukkan makna sebagian. (Mereka berkata) orang-orang yang diikuti itu (\"Seandainya Allah memberi petunjuk kepada kami niscaya kami dapat memberi petunjuk kepada kalian) artinya nicaya kami akan menyeru kalian ke jalan hidayah. (Sama saja bagi kita, apakah kita mengeluh atau bersabar, sekali-kali tidak mempunyai) huruf min di sini adalah zaidah (tempat untuk melarikan diri.\") tempat berlindung dari azab-Nya.",[["وَبَرَزُوا۟","Dan mereka akan keluar"],["لِلَّهِ","di hadapan Allah"],["جَمِيعًۭا","semua bersama"],["فَقَالَ","kemudian akan berkata"],["ٱلضُّعَفَـٰٓؤُا۟","yang lemah"],["لِلَّذِينَ","kepada mereka yang"],["ٱسْتَكْبَرُوٓا۟","adalah sombong"],["إِنَّا","Sesungguhnya kita"],["كُنَّا","kami"],["لَكُمْ","kamu"],["تَبَعًۭا","pengikut"],["فَهَلْ","jadi boleh"],["أَنتُم","kamu (jadi)"],["مُّغْنُونَ","orang yang berfaedah"],["عَنَّا","kami"],["مِنْ","daripada"],["عَذَابِ","azab"],["ٱللَّهِ","(milik) Allah"],["مِن","sesuatu"],["شَىْءٍۢ ۚ","sesuatu"],["قَالُوا۟","Mereka akan berkata"],["لَوْ","Jika"],["هَدَىٰنَا","Allah telah memberi petunjuk kepada kita"],["ٱللَّهُ","Allah telah memberi petunjuk kepada kita"],["لَهَدَيْنَـٰكُمْ ۖ","nescaya kami akan memberi petunjuk kepada kamu"],["سَوَآءٌ","(Ia) sama"],["عَلَيْنَآ","bagi kami"],["أَجَزِعْنَآ","sama ada kita menunjukkan sikap tidak bertoleransi"],["أَمْ","atau"],["صَبَرْنَا","kita bersabar"],["مَا","tidak"],["لَنَا","(adalah) untuk kita"],["مِن","sebarang"],["مَّحِيصٍۢ","tempat melarikan diri"]]],"1772":["(Dan berkatalah setan) yakni iblis (tatkala perkara hisab telah diselesaikan) kemudian orang-orang yang berhak masuk surga dimasukkan ke dalam surga dan orang-orang yang berhak masuk neraka dimasukkan ke dalam neraka, lalu mereka semuanya mengerumuni iblis (\"Sesungguhnya Allah telah menjanjikan kepada kalian janji yang benar) yaitu dengan kebangkitan dari kubur dan pembalasan amal perbuatan lalu Dia telah memenuhi kalian (dan aku pun telah menjanjikan kepada kalian) bahwasanya hal ini tidak ada (tetapi aku menyalahinya. Sekali-kali aku terhadap kalian tidak memiliki) huruf min di sini zaidah (kekuasaan) kekuatan dan kemampuan yang dapat memaksakan kalian untuk mengikutiku (melainkan) kecuali (sekedar aku menyeru kalian, lalu kalian mematuhi seruanku, oleh sebab itu janganlah kalian mencerca aku, akan tetapi cercalah diri kalian sendiri) disebabkan kalian telah mengikuti seruanku itu. (Aku sekali-kali tidak dapat menolong kalian) dapat memberikan pertolongan kepada kalian (dan kalian pun tidak dapat menolongku) dapat dibaca mushrikhiyya dan mushrikhiyyi. (Sesungguhnya aku tidak membenarkan perbuatan kalian mempersekutukan aku) dengan Allah (sebelumnya.\") sewaktu di dunia. Lalu Allah berfirman: (\"Sesungguhnya orang-orang yang lalim itu mendapat siksaan yang pedih) siksaan yang sangat pedih.",[["وَقَالَ","Dan akan berkata"],["ٱلشَّيْطَـٰنُ","syaitan"],["لَمَّا","apabila"],["قُضِىَ","telah diputuskan"],["ٱلْأَمْرُ","perkara itu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["وَعَدَكُمْ","berjanji kepada kamu"],["وَعْدَ","sebuah janji"],["ٱلْحَقِّ","(dari) kebenaran"],["وَوَعَدتُّكُمْ","Dan aku berjanji kepada kamu"],["فَأَخْلَفْتُكُمْ ۖ","tetapi aku mengkhianati kamu"],["وَمَا","Tetapi tidak"],["كَانَ","aku ada"],["لِىَ","aku ada"],["عَلَيْكُم","atas kamu"],["مِّن","sebarang"],["سُلْطَـٰنٍ","pihak berkuasa"],["إِلَّآ","kecuali"],["أَن","bahawa"],["دَعَوْتُكُمْ","aku jemput kamu"],["فَٱسْتَجَبْتُمْ","dan kamu menjawab"],["لِى ۖ","kepada aku"],["فَلَا","Jadi (jangan)"],["تَلُومُونِى","salahkan aku"],["وَلُومُوٓا۟","tapi salahkan"],["أَنفُسَكُم ۖ","kamu sendiri"],["مَّآ","Tidak"],["أَنَا۠","(boleh) aku"],["بِمُصْرِخِكُمْ","(menjadi) penolongmu"],["وَمَآ","dan bukan"],["أَنتُم","kamu (boleh)"],["بِمُصْرِخِىَّ ۖ","(menjadi) penolongku"],["إِنِّى","Sesungguhnya aku"],["كَفَرْتُ","menafikan"],["بِمَآ","[dari apa]"],["أَشْرَكْتُمُونِ","persekutuan kamu denganku (dengan Allah)"],["مِن","sebelum"],["قَبْلُ ۗ","sebelum"],["إِنَّ","Sesungguhnya"],["ٱلظَّـٰلِمِينَ","orang yang zalim"],["لَهُمْ","bagi mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"1773":["(Dan dimasukkanlah orang-orang yang beriman dan beramal saleh ke alam surga yang mengalir di bawahnya sungai-sungai; mereka kekal) lafal khaalidiina menjadi hal daripada kalimat yang keberadaannya diperkirakan (di dalamnya dengan seizin Rabb mereka. Ucapan penghormatan mereka dalam surga itu) dari Allah dan dari para malaikat, serta di antara sesama mereka (salaam.)",[["وَأُدْخِلَ","Dan akan diterima masuk"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","(akan) kekal selama-lamanya"],["فِيهَا","di dalamnya"],["بِإِذْنِ","dengan izin"],["رَبِّهِمْ ۖ","(dari) Tuhan mereka"],["تَحِيَّتُهُمْ","salam mereka"],["فِيهَا","di dalamnya"],["سَلَـٰمٌ","(akan menjadi) kedamaian"]]],"1774":["(Tidakkah kamu perhatikan) memperhatikan (bagaimana Allah telah membuat perumpamaan) lafal matsalan ini dijelaskan oleh badalnya, yaitu (kalimat yang baik) yakni kalimat laa ilaaha illallaah/tiada Tuhan selain Allah (seperti pohon yang baik) yaitu pohon kurma (akarnya teguh) menancap dalam di bumi (dan cabangnya) ranting-rantingnya (menjulang ke langit).",[["أَلَمْ","Jangan"],["تَرَ","kamu lihat"],["كَيْفَ","bagaimana"],["ضَرَبَ","Allah menetapkan"],["ٱللَّهُ","Allah menetapkan"],["مَثَلًۭا","contoh"],["كَلِمَةًۭ","satu perkataan"],["طَيِّبَةًۭ","kebaikan"],["كَشَجَرَةٍۢ","(ialah) seperti pokok"],["طَيِّبَةٍ","kebaikan"],["أَصْلُهَا","akarnya"],["ثَابِتٌۭ","(adalah) tegas"],["وَفَرْعُهَا","dan dahan-dahannya"],["فِى","(ada) dalam"],["ٱلسَّمَآءِ","langit"]]],"1775":["(Pohon itu memberikan) membuahkan (buahnya) buah-buahannya (pada setiap musim dengan seizin Rabbnya) dengan kehendak-Nya demikian pula kalimat iman tertanam di dalam kalbu orang mukmin sedangkan amalnya naik ke langit kemudian memperoleh berkah dan pahala amalannya itu setiap saat (dibuatkan) dijelaskan (oleh Allah perumpamaan-perumpamaan itu untuk manusia supaya mereka selalu ingat) mau mengambil pelajaran daripadanya kemudian mereka mau beriman karenanya.",[["تُؤْتِىٓ","Memberi"],["أُكُلَهَا","buahnya"],["كُلَّ","semua"],["حِينٍۭ","masa"],["بِإِذْنِ","dengan izin"],["رَبِّهَا ۗ","daripada Tuhannya"],["وَيَضْرِبُ","Dan Allah menetapkan"],["ٱللَّهُ","Dan Allah menetapkan"],["ٱلْأَمْثَالَ","contoh-contohnya"],["لِلنَّاسِ","untuk manusia"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَتَذَكَّرُونَ","ingat"]]],"1776":["(Dan perumpamaan kalimat yang buruk) yaitu kalimat kekafiran (seperti pohon yang buruk) yaitu pohon hanzhal yang buahnya sangat pahit (yang telah dicabut) telah dibongkar sampai ke akar-akarnya (dari permukaan bumi, ia tidak dapat tetap sedikit pun) artinya tidak mempunyai tempat untuk berpijak lagi, maka demikian pula keadaan kalimat kekafiran tidak mempunyai tempat berpijak, tidak mempunyai ranting dan pula tidak ada keberkahannya.",[["وَمَثَلُ","Dan (contohnya)."],["كَلِمَةٍ","(dari) perkataan"],["خَبِيثَةٍۢ","jahat"],["كَشَجَرَةٍ","(ialah) seperti pokok"],["خَبِيثَةٍ","jahat"],["ٱجْتُثَّتْ","tercabut"],["مِن","daripada"],["فَوْقِ","permukaan"],["ٱلْأَرْضِ","(dari) bumi"],["مَا","tidak"],["لَهَا","baginya"],["مِن","(adalah) mana-mana"],["قَرَارٍۢ","kestabilan"]]],"1777":["(Allah meneguhkan iman orang-orang yang beriman dengan ucapan yang teguh itu) yaitu kalimat tauhid itu (di dunia dan di akhirat) yaitu di alam kubur, ketika dua orang malaikat menanyakan kepadanya tentang Rabb mereka, agama mereka dan nabi mereka. Maka orang-orang yang beriman dapat menjawabnya dengan benar; demikianlah menurut keterangan yang disebutkan di dalam hadis Imam Bukhari dan Imam Muslim (dan Allah menyesatkan orang-orang yang lalim) yaitu orang-orang kafir; oleh sebab itu mereka tidak mendapat petunjuk untuk memberikan jawaban yang benar. Bahkan mereka hanya mengatakan, \"Kami tidak tahu,\" demikian menurut keterangan dalam hadis (dan memperbuat apa yang Dia kehendaki.)",[["يُثَبِّتُ","Allah tetap teguh"],["ٱللَّهُ","Allah tetap teguh"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["بِٱلْقَوْلِ","dengan perkataan yang tegas"],["ٱلثَّابِتِ","dengan perkataan yang tegas"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا","dunia"],["وَفِى","dan dalam"],["ٱلْـَٔاخِرَةِ ۖ","akhirat"],["وَيُضِلُّ","Dan Allah membiarkan sesat"],["ٱللَّهُ","Dan Allah membiarkan sesat"],["ٱلظَّـٰلِمِينَ ۚ","orang yang zalim"],["وَيَفْعَلُ","Dan Allah melakukannya"],["ٱللَّهُ","Dan Allah melakukannya"],["مَا","apa"],["يَشَآءُ","Dia kehendaki"]]],"1778":["(Tidakkah kamu perhatikan) artinya melihat (orang-orang yang telah menukar nikmat Allah) yang dimaksud ialah bersyukur kepada Allah atas nikmat-Nya (dengan kekafiran) mereka adalah orang-orang yang kafir Quraisy (dan menjatuhkan) menyeret (kaumnya) yakni mereka menyesatkan kaumnya (ke lembah kebinasaan) ke dalam kebinasaan.",[["۞ أَلَمْ","belum"],["تَرَ","kamu nampak"],["إِلَى","[ke]"],["ٱلَّذِينَ","orang yang"],["بَدَّلُوا۟","(telah) berubah"],["نِعْمَتَ","(yang) nikmat"],["ٱللَّهِ","(milik) Allah"],["كُفْرًۭا","(untuk) kekufuran"],["وَأَحَلُّوا۟","dan mereka memimpin"],["قَوْمَهُمْ","rakyat mereka"],["دَارَ","(ke) rumah"],["ٱلْبَوَارِ","(dari) kemusnahan"]]],"1779":["(Yaitu neraka Jahanam) lafal Jahanam merupakan athaf bayan (mereka masuk ke dalamnya) dijebloskan ke dalamnya (dan itulah seburuk-buruk tempat kediaman) tempat yang paling buruk ialah Jahanam itu.",[["جَهَنَّمَ","Neraka"],["يَصْلَوْنَهَا ۖ","(di dalamnya) mereka akan terbakar"],["وَبِئْسَ","dan seorang yang celaka"],["ٱلْقَرَارُ","tempat menetap"]]],"1780":["(Orang-orang yang kafir itu telah menjadikan sekutu-sekutu bagi Allah) tandingan-tandingan (supaya mereka menyesatkan manusia) dapat dibaca liyudhilluu dan liyadhilluu (dari jalan-Nya) yaitu agama Islam. (Katakanlah) kepada mereka (\"Bersenang-senanglah kalian) dengan keduniaan kalian dalam waktu yang sedikit (karena sesungguhnya tempat kembali kalian) yaitu tempat menetap kalian (ialah neraka.\")",[["وَجَعَلُوا۟","Dan mereka menubuhkan"],["لِلَّهِ","kepada Allah"],["أَندَادًۭا","sama"],["لِّيُضِلُّوا۟","supaya mereka menyesatkan"],["عَن","daripada"],["سَبِيلِهِۦ ۗ","Jalan-Nya"],["قُلْ","Katakanlah"],["تَمَتَّعُوا۟","Nikmati"],["فَإِنَّ","tetapi sesungguhnya"],["مَصِيرَكُمْ","destinasi kamu"],["إِلَى","(adalah) kepada"],["ٱلنَّارِ","neraka"]]],"1781":["(Katakanlah kepada hamba-hamba-Ku yang telah beriman, \"Hendaklah mereka mendirikan salat, menafkahkan sebagian rezeki yang Kami berikan kepada mereka secara sembunyi atau pun terang-terangan sebelum datang hari kiamat yang pada hari itu tidak ada jual-beli) tebusan (dan persahabatan.\") persahabatan yang dapat menolong; yang dimaksud adalah hari kiamat.",[["قُل","Katakanlah"],["لِّعِبَادِىَ","kepada hamba-hamba-Ku"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["يُقِيمُوا۟","(untuk) menubuhkan"],["ٱلصَّلَوٰةَ","solat"],["وَيُنفِقُوا۟","dan (untuk) membelanjakan"],["مِمَّا","daripada apa"],["رَزَقْنَـٰهُمْ","Kami telah menyediakan mereka"],["سِرًّۭا","secara rahsia"],["وَعَلَانِيَةًۭ","dan secara terbuka"],["مِّن","sebelum"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["يَأْتِىَ","datang"],["يَوْمٌۭ","sehari"],["لَّا","tidak"],["بَيْعٌۭ","sebarang perdagangan"],["فِيهِ","di dalamnya"],["وَلَا","dan bukan"],["خِلَـٰلٌ","sebarang persahabatan"]]],"1782":["(Allahlah yang telah menciptakan langit dan bumi dan menurunkan air hujan dari langit kemudian Dia mengeluarkan dengan air hujan itu berbagai buah-buahan menjadi rezeki untuk kalian dan Dia telah menundukkan bahtera bagi kalian) yang dimaksud adalah perahu (supaya bahtera itu berlayar di lautan) sehingga kalian dapat menaikinya dan memuat barang-barang di atasnya (dengan kehendak-Nya) dengan seizin-Nya (dan Dia telah menundukkan pula bagi kalian sungai-sungai.)",[["ٱللَّهُ","Allah"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَ","dicipta"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضَ","dan bumi"],["وَأَنزَلَ","dan diturunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَأَخْرَجَ","kemudian dilahirkan"],["بِهِۦ","daripadanya"],["مِنَ","daripada"],["ٱلثَّمَرَٰتِ","buah-buahan"],["رِزْقًۭا","(sebagai) peruntukan"],["لَّكُمْ ۖ","bagi kamu"],["وَسَخَّرَ","dan tertakluk"],["لَكُمُ","bagi kamu"],["ٱلْفُلْكَ","kapal-kapal itu"],["لِتَجْرِىَ","supaya mereka boleh berlayar"],["فِى","dalam"],["ٱلْبَحْرِ","laut"],["بِأَمْرِهِۦ ۖ","dengan perintahNya"],["وَسَخَّرَ","dan tertakluk"],["لَكُمُ","bagi kamu"],["ٱلْأَنْهَـٰرَ","sungai-sungai"]]],"1783":["(Dan Dia telah menundukkan pula bagi kalian matahari dan bulan yang terus-menerus beredar) di dalam garis edarnya secara terus-menerus dan tidak pernah berhenti (dan Dia telah menundukkan pula bagi kalian malam) supaya kalian tenang di dalamnya (dan siang) dan supaya kalian mencari kemurahan Allah di dalamnya.",[["وَسَخَّرَ","Dan Dia menundukkan"],["لَكُمُ","bagi kamu"],["ٱلشَّمْسَ","matahari"],["وَٱلْقَمَرَ","dan bulan"],["دَآئِبَيْنِ ۖ","kedua-duanya sentiasa mengikuti kursus mereka"],["وَسَخَّرَ","dan tertakluk"],["لَكُمُ","bagi kamu"],["ٱلَّيْلَ","malam"],["وَٱلنَّهَارَ","dan hari"]]],"1784":["(Dan Dia telah memberikan kepada kalian dari segala apa yang kalian mohonkan kepada-Nya) sesuai dengan keperluan kalian (Dan jika kalian menghitung nikmat Allah) pemberian nikmat-Nya kepada kalian (tidaklah dapat kalian menghitungnya) kalian tidak akan mampu menghitung-hitungnya. (Sesungguhnya manusia itu) yang dimaksud adalah orang kafir (sangat lalim dan sangat ingkar) artinya banyak berbuat aniaya terhadap dirinya dengan cara melakukan maksiat dan banyak ingkar terhadap nikmat Rabbnya.",[["وَءَاتَىٰكُم","Dan Dia memberi kamu"],["مِّن","daripada"],["كُلِّ","semua"],["مَا","apa"],["سَأَلْتُمُوهُ ۚ","kamu bertanya kepada-Nya"],["وَإِن","Dan jika"],["تَعُدُّوا۟","kamu mengira"],["نِعْمَتَ","(kenikmatan) Allah"],["ٱللَّهِ","(kenikmatan) Allah"],["لَا","tidak"],["تُحْصُوهَآ ۗ","kamu akan (dapat) mengiranya"],["إِنَّ","Sesungguhnya"],["ٱلْإِنسَـٰنَ","umat manusia"],["لَظَلُومٌۭ","(adalah) sememangnya tidak adil"],["كَفَّارٌۭ","(dan) tidak bersyukur"]]],"1785":["(Dan) ingatlah (ketika Ibrahim berkata, \"Ya Rabbku! Jadikanlah negeri ini) yakni kota Mekah (negeri yang aman) memiliki keamanan dan ternyata Allah telah memperkenankan doanya, maka Dia menjadikan Mekah sebagai kota yang suci; dilarang di dalamnya mengalirkan darah manusia, menganiaya seseorang, berburu binatang buruannya dan menebang pepohonannya (dan jauhkanlah aku) hindarkanlah aku (beserta anak cucuku) daripada (menyembah berhala-berhala.\")",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["إِبْرَٰهِيمُ","Ibrahim"],["رَبِّ","Tuhanku"],["ٱجْعَلْ","buat"],["هَـٰذَا","ini"],["ٱلْبَلَدَ","bandar"],["ءَامِنًۭا","selamat"],["وَٱجْنُبْنِى","dan jauhkan aku"],["وَبَنِىَّ","dan anak-anak lelaki aku"],["أَن","bahawa"],["نَّعْبُدَ","kami sembah"],["ٱلْأَصْنَامَ","berhala"]]],"1786":["(\"Ya Rabbku! Sesungguhnya mereka itu) yakni berhala-berhala itu (telah menyesatkan kebanyakan daripada manusia) karena mereka menyembahnya (maka barang siapa yang mengikutiku) berpegang pada ajaran tauhid (maka sesungguhnya orang itu termasuk golonganku) termasuk pemeluk agamaku (dan barang siapa yang mendurhakai aku, maka sesungguhnya Engkau Maha Pengampun lagi Maha Penyayang.) pernyataan ini sebelum Nabi Ibrahim mengetahui, bahwa Allah swt. tidak mengampuni dosa syirik.",[["رَبِّ","Tuhanku"],["إِنَّهُنَّ","Sesungguhnya mereka"],["أَضْلَلْنَ","telah menyesatkan"],["كَثِيرًۭا","ramai"],["مِّنَ","antara"],["ٱلنَّاسِ ۖ","umat manusia"],["فَمَن","Jadi sesiapa"],["تَبِعَنِى","mengikut aku"],["فَإِنَّهُۥ","maka sesungguhnya, dia"],["مِنِّى ۖ","(adalah) daripada aku"],["وَمَنْ","dan sesiapa"],["عَصَانِى","menderhaka kepadaku"],["فَإِنَّكَ","maka sesungguhnya, Engkau"],["غَفُورٌۭ","(adalah) Selalu Pemaaf"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"1787":["(Ya Rabb kami! Sesungguhnya aku telah menempatkan sebagian keturunanku) sebagian daripada mereka, yaitu Nabi Ismail dan Siti Hajar ibunya (di lembah yang tidak mempunyai tanam-tanaman) yaitu Mekah (di dekat rumah Engkau yang suci) sebelum banjir besar terjadi (ya Rabb agar mereka mendirikan salat, maka jadikanlah hati) kalbu-kalbu (sebagian manusia cenderung) condong dan merindukan (kepada mereka) Sahabat Ibnu Abbas mengatakan, seandainya Nabi Ibrahim mengatakan di dalam doanya, yaitu af-idatan naasi yang artinya semua hati manusia, maka orang-orang Persia, Romawi dan semua manusia niscaya akan cenderung ke Baitullah (dan beri rezekilah mereka dari buah-buahan; mudah-mudahan mereka bersyukur.\") dan memang doanya diperkenankan, yaitu dengan disuplaikannya buah-buahan dari Thaif ke Mekah.",[["رَّبَّنَآ","Wahai Tuhan kami"],["إِنِّىٓ","Sesungguhnya aku"],["أَسْكَنتُ","[Aku] telah menetap"],["مِن","(beberapa) daripada"],["ذُرِّيَّتِى","keturunan aku"],["بِوَادٍ","di sebuah lembah"],["غَيْرِ","tidak"],["ذِى","dengan"],["زَرْعٍ","penanaman"],["عِندَ","dekat"],["بَيْتِكَ","Rumah Sucimu"],["ٱلْمُحَرَّمِ","Rumah Sucimu"],["رَبَّنَا","Tuhan kami"],["لِيُقِيمُوا۟","Supaya mereka mendirikan"],["ٱلصَّلَوٰةَ","solat"],["فَٱجْعَلْ","Jadi buat"],["أَفْـِٔدَةًۭ","hati"],["مِّنَ","daripada"],["ٱلنَّاسِ","kaum lelaki"],["تَهْوِىٓ","condong"],["إِلَيْهِمْ","terhadap mereka"],["وَٱرْزُقْهُم","dan menyediakan mereka"],["مِّنَ","dengan"],["ٱلثَّمَرَٰتِ","buah-buahan"],["لَعَلَّهُمْ","supaya mereka boleh"],["يَشْكُرُونَ","bersyukurlah"]]],"1788":["(Ya Rabb kami! Sesungguhnya Engkau mengetahui apa yang kami sembunyikan) apa yang kami tidak lahirkan (dan apa yang kami lahirkan; dan tidak ada yang tersembunyi bagi Allah) huruf min di sini adalah zaidah (sesuatu pun, baik yang ada di bumi maupun yang ada di langit) ayat ini dapat diartikan kalam Rabb dan dapat pula dianggap sebagai doa Nabi Ibrahim.",[["رَبَّنَآ","Wahai Tuhan kami"],["إِنَّكَ","Sesungguhnya, Engkau"],["تَعْلَمُ","kamu tahu"],["مَا","apa"],["نُخْفِى","kita sembunyikan"],["وَمَا","dan apa"],["نُعْلِنُ ۗ","kami mengisytiharkan"],["وَمَا","Dan tidak"],["يَخْفَىٰ","(adalah) tersembunyi"],["عَلَى","daripada"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["شَىْءٍۢ","perkara"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["وَلَا","dan bukan"],["فِى","dalam"],["ٱلسَّمَآءِ","syurga itu"]]],"1789":["(Segala puji bagi Allah yang telah menganugerahkan kepada diriku) memberiku (sekalipun) walaupun (sudah tua, Ismail) Nabi Ismail dilahirkan sewaktu Nabi Ibrahim berumur sembilan puluh sembilan tahun (dan Ishak.) dilahirkan sewaktu Nabi Ibrahim berumur seratus dua belas tahun (Sesungguhnya Rabbku benar-benar Maha Mendengar doa).",[["ٱلْحَمْدُ","Segala Pujian"],["لِلَّهِ","(adalah) untuk Allah"],["ٱلَّذِى","yang Esa"],["وَهَبَ","telah memberi"],["لِى","aku"],["عَلَى","dalam"],["ٱلْكِبَرِ","usia tua"],["إِسْمَـٰعِيلَ","Ismail"],["وَإِسْحَـٰقَ ۚ","dan Ishak"],["إِنَّ","Sesungguhnya"],["رَبِّى","Tuhanku"],["لَسَمِيعُ","(adalah) Yang Maha Mendengar"],["ٱلدُّعَآءِ","(dari) solat"]]],"1790":["(Ya Rabbku! Jadikanlah aku orang-orang yang tetap mendirikan salat dan) jadikan pula (anak cucuku) orang-orang yang tetap mendirikannya. Nabi Ibrahim sengaja di dalam doanya ini memakai ungkapan min yang menunjukkan makna sebagian karena Allah swt. telah memberitahukan kepadanya bahwa di antara anak cucunya itu terdapat orang yang kafir (Ya Rabb kami! Kabulkanlah doaku) semua doa yang telah disebutkan tadi.",[["رَبِّ","Tuhanku"],["ٱجْعَلْنِى","Buat aku"],["مُقِيمَ","seorang pendiri"],["ٱلصَّلَوٰةِ","(dari) solat"],["وَمِن","dan daripada"],["ذُرِّيَّتِى ۚ","keturunan aku"],["رَبَّنَا","Wahai Tuhan kami"],["وَتَقَبَّلْ","dan terima"],["دُعَآءِ","doa aku"]]],"1791":["(Ya Rabb kami! Beri ampunlah aku dan kedua ibu bapakku) doa ini diucapkan sebelum jelas bagi Nabi Ibrahim bahwa kedua orang tuanya memusuhi Allah swt. Akan tetapi menurut suatu pendapat dikatakan bahwa ibu Nabi Ibrahim masuk Islam. Lafal waalidayya menurut qiraat yang lain dapat dibaca mufrad sehingga bacaannya menjadi waalidiy (dan sekalian orang-orang mukmin pada hari terjadinya) ditegakkannya (hisab) selanjutnya Allah berfirman:",[["رَبَّنَا","Wahai Tuhan kami"],["ٱغْفِرْ","maafkan"],["لِى","aku"],["وَلِوَٰلِدَىَّ","dan ibu bapa aku"],["وَلِلْمُؤْمِنِينَ","dan orang-orang yang beriman"],["يَوْمَ","(pada) hari itu"],["يَقُومُ","akan (akan) ditubuhkan"],["ٱلْحِسَابُ","akaun tersebut"]]],"1792":["(Dan janganlah sekali-kali kamu mengira bahwa Allah lalai dari apa yang diperbuat oleh orang-orang yang lalim) yakni orang-orang kafir dari kalangan penduduk Mekah. (Sesungguhnya Allah hanya memberi tangguh kepada mereka) tanpa diazab (sampai hari yang pada waktu itu mata mereka terbelalak) karena ngerinya pemandangan yang mereka saksikan kala itu. Di dalam istilah bahasa atau lugah jika dikatakan bashara fulaanun syakhshan, artinya si polan melihat seseorang tanpa mengedipkan matanya.",[["وَلَا","Dan jangan"],["تَحْسَبَنَّ","fikir"],["ٱللَّهَ","(itu) Allah"],["غَـٰفِلًا","(adalah) tidak sedar"],["عَمَّا","tentang apa"],["يَعْمَلُ","lakukan"],["ٱلظَّـٰلِمُونَ ۚ","orang yang zalim"],["إِنَّمَا","Hanya"],["يُؤَخِّرُهُمْ","Dia memberi mereka tangguh"],["لِيَوْمٍۢ","kepada satu Hari"],["تَشْخَصُ","akan merenung"],["فِيهِ","di dalamnya"],["ٱلْأَبْصَـٰرُ","mata"]]],"1793":["(Mereka datang bergegas) dengan segera memenuhi panggilan. Lafal ayat ini berkedudukan menjadi hal atau kata keterangan (dengan mengangkat) mendongakkan (kepalanya) ke langit (sedangkan mata mereka tidak berkedip-kedip) melotot (dan hati mereka kosong) tidak ada suatu pikiran pun yang terbetik di dalamnya saking kaget dan ngerinya.",[["مُهْطِعِينَ","Berlumba ke hadapan"],["مُقْنِعِى","dibangkitkan"],["رُءُوسِهِمْ","kepala mereka"],["لَا","tidak"],["يَرْتَدُّ","kembali"],["إِلَيْهِمْ","terhadap mereka"],["طَرْفُهُمْ ۖ","pandangan mereka"],["وَأَفْـِٔدَتُهُمْ","dan hati mereka"],["هَوَآءٌۭ","(ada) kosong"]]],"1794":["(Dan berikanlah peringatan) hai Muhammad, peringatkanlah (kepada manusia) yakni orang-orang kafir (terhadap hari yang pada waktu itu datang azab kepada mereka) yaitu hari kiamat (maka berkatalah orang-orang yang lalim) yakni orang-orang kafir (\"Ya Rabb kami! Beri tangguhlah kami) seumpamanya Engkau mengembalikan kami ke dunia (walaupun dalam waktu yang sedikit, niscaya kami akan mematuhi seruan Engkau) dengan mengamalkan ajaran tauhid (dan akan mengikuti rasul-rasul.\") lalu dikatakan kepada mereka dengan nada celaan (\"Bukankah kalian telah bersumpah) telah berikrar (sebelumnya dahulu) yaitu sewaktu di dunia (bahwa sekali-kali kalian tidak akan) huruf min di sini adalah zaidah (binasa?\") setelah meninggalkan dunia menuju ke akhirat.",[["وَأَنذِرِ","Dan beri amaran"],["ٱلنَّاسَ","umat manusia"],["يَوْمَ","(dari) sehari"],["يَأْتِيهِمُ","(apabila) akan datang kepada mereka"],["ٱلْعَذَابُ","azab"],["فَيَقُولُ","kemudian akan berkata"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","buat salah"],["رَبَّنَآ","Wahai Tuhan kami"],["أَخِّرْنَآ","Rehatkan kami"],["إِلَىٰٓ","bagi"],["أَجَلٍۢ","satu istilah"],["قَرِيبٍۢ","pendek"],["نُّجِبْ","kami akan jawab"],["دَعْوَتَكَ","Panggilan kamu"],["وَنَتَّبِعِ","dan kami akan ikut"],["ٱلرُّسُلَ ۗ","para Rasul"],["أَوَلَمْ","Tidak"],["تَكُونُوٓا۟","kamu"],["أَقْسَمْتُم","bersumpah"],["مِّن","sebelum"],["قَبْلُ","sebelum"],["مَا","tidak"],["لَكُم","bagi kamu"],["مِّن","sebarang"],["زَوَالٍۢ","tamat"]]],"1795":["(\"Dan kalian telah berdiam) di dunia (di tempat-tempat kediaman orang-orang yang menganiaya dirinya sendiri) dengan melakukan kekafiran, yaitu bekas tempat tinggal umat-umat terdahulu yang durhaka (dan telah nyata bagi kalian bagaimana Kami telah berbuat terhadap mereka) yaitu berupa siksaan, akan tetapi kalian masih tetap tidak mau kapok juga (dan telah Kami berikan) telah Kami jelaskan (kepada kalian beberapa perumpamaan.\") di dalam Alquran, akan tetapi kalian tidak mau mengambilnya sebagai pelajaran.",[["وَسَكَنتُمْ","Dan kamu tinggal"],["فِى","dalam"],["مَسَـٰكِنِ","tempat tinggal"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوٓا۟","dizalimi"],["أَنفُسَهُمْ","diri mereka"],["وَتَبَيَّنَ","dan ia telah menjadi jelas"],["لَكُمْ","kepada kamu"],["كَيْفَ","bagaimana"],["فَعَلْنَا","Kami berurusan"],["بِهِمْ","bersama mereka"],["وَضَرَبْنَا","dan Kami keluarkan"],["لَكُمُ","bagi kamu"],["ٱلْأَمْثَالَ","contoh-contohnya"]]],"1796":["(Dan sesungguhnya mereka telah membuat makar) terhadap Nabi saw. (makar yang besar) yaitu mereka bermaksud untuk membunuh Nabi saw. atau membelenggunya, atau mengusirnya (padahal di sisi Allahlah makar mereka) yakni pengetahuan makar tersebut, atau pembalasan makar itu. (Dan tidak akan) tidak bisa (makar mereka itu) betapa pun besarnya (dapat melenyapkan gunung-gunung) pengertiannya ialah makar tersebut dibiarkan dan tidak memberikan mudarat melainkan hanya terhadap diri mereka sendiri. Yang dimaksud dengan pengertian gunung-gunung di sini, menurut suatu pendapat adalah hakiki, yakni gunung yang sesungguhnya, dan menurut pendapat yang lain dimaksud adalah syariat-syariat Islam yang digambarkan seperti gunung-gunung dalam hal ketetapan dan keteguhannya. Menurut suatu qiraat yang lain litazuula ini dibaca latazuulu, yakni dengan harakat fatah pada huruf lamnya kemudian akhir fi'ilnya dibaca rafa', maka berdasarkan qiraat ini berarti huruf in di sini adalah bentuk takhfif atau keringanan daripada huruf inna yang ditasydidkan huruf nunnya, makna yang dimaksud adalah menggambarkan tentang besarnya makar orang-orang kafir itu terhadap diri Nabi saw. Akan tetapi menurut pendapat yang lain dikatakan, yang dimaksud dengan lafal al-makru ialah kekafiran mereka. Makna yang terakhir ini sesuai pula dengan apa yang disebutkan di dalam firman Allah swt. yang. lainnya, yaitu, \"Hampir-hampir langit pecah karena ucapan itu (mendakwa Tuhan mempunyai anak), bumi belah, dan gunung-gunung runtuh.\" (Q.S. Maryam 90) Sedangkan pengertian yang pertama sesuai dengan bacaan yang tertera.",[["وَقَدْ","Dan sesungguhnya"],["مَكَرُوا۟","mereka merancang"],["مَكْرَهُمْ","rancangan mereka"],["وَعِندَ","tetapi dengan"],["ٱللَّهِ","Allah"],["مَكْرُهُمْ","(adalah) rancangan mereka"],["وَإِن","walaupun"],["كَانَ","adalah"],["مَكْرُهُمْ","rancangan mereka"],["لِتَزُولَ","itu harus dipindahkan"],["مِنْهُ","olehnya"],["ٱلْجِبَالُ","pergunungan"]]],"1797":["(Karena itu janganlah sekali-kali kalian mengira Allah akan menyalahi janji-Nya kepada rasul-rasul-Nya) yaitu akan memberikan pertolongan kepadanya. (Sesungguhnya Allah Maha Perkasa) Maha Menang, tiada sesuatu pun yang dapat menghalang-halangi-Nya (lagi mempunyai pembalasan) terhadap orang-orang yang mendurhakai-Nya.",[["فَلَا","Jadi (jangan)"],["تَحْسَبَنَّ","fikir"],["ٱللَّهَ","(itu) Allah"],["مُخْلِفَ","akan gagal"],["وَعْدِهِۦ","(untuk) menepati janji-Nya"],["رُسُلَهُۥٓ ۗ","(kepada) Rasul-rasulNya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَزِيزٌۭ","(adalah) Maha Perkasa"],["ذُو","Pemilik (bagi) Pembalasan"],["ٱنتِقَامٍۢ","Pemilik (bagi) Pembalasan"]]],"1798":["Ingatlah (Pada hari ketika bumi diganti dengan bumi yang lain dan demikian pula langit) yaitu hari kiamat, kemudian manusia digiring untuk dikumpulkan di suatu tanah yang putih bersih sebagaimana yang telah disebutkan di dalam hadis kitab Sahih Bukhari dan Muslim. Sehubungan dengan hal ini Imam Muslim meriwayatkan sebuah hadis bahwasanya Nabi saw. ditanya mengenai manusia pada saat itu. Lalu Nabi saw. menjawab, \"Berada di shirath.\" (dan mereka semuanya tampak bermunculan) artinya mereka keluar dari kuburan mereka masing-masing (untuk menghadap kepada Allah Yang Maha Esa lagi Maha Perkasa.)",[["يَوْمَ","(Pada) Hari"],["تُبَدَّلُ","akan diubah"],["ٱلْأَرْضُ","bumi"],["غَيْرَ","(kepada) selain (selain)"],["ٱلْأَرْضِ","bumi"],["وَٱلسَّمَـٰوَٰتُ ۖ","dan syurga"],["وَبَرَزُوا۟","dan mereka akan keluar"],["لِلَّهِ","di hadapan Allah"],["ٱلْوَٰحِدِ","yang Satu"],["ٱلْقَهَّارِ","yang tak tertahan"]]],"1799":["(Dan kamu akan melihat) hai Muhammad (orang-orang yang berdosa) yakni orang-orang kafir (pada hari itu diikat) dalam keadaan terikat beserta setan-setan mereka (dengan belenggu) tali-tali atau rantai-rantai.",[["وَتَرَى","Dan kamu akan melihat"],["ٱلْمُجْرِمِينَ","penjenayah"],["يَوْمَئِذٍۢ","(pada) hari itu"],["مُّقَرَّنِينَ","terikat bersama"],["فِى","dalam"],["ٱلْأَصْفَادِ","rantai"]]],"1800":["(Pakaian mereka) baju-baju mereka (adalah dari aspal) yang sangat mudah menyala (dan tertutuplah) ditutuplah (muka mereka oleh api neraka).",[["سَرَابِيلُهُم","pakaian mereka"],["مِّن","daripada"],["قَطِرَانٍۢ","tar"],["وَتَغْشَىٰ","dan akan meliputi"],["وُجُوهَهُمُ","muka mereka"],["ٱلنَّارُ","neraka"]]],"1801":["(Agar pembalasan diberikan) lafal ini bertaalluq kepada lafal barazuu (oleh Allah kepada tiap-tiap orang terhadap apa yang ia usahakan) baik berupa kebaikan atau pun keburukan. (Sesungguhnya Allah Maha cepat hisab-Nya) Dia menghisab semua makhluk selama setengah hari menurut ukuran hari dunia, demikianlah menurut penjelasan hadis.",[["لِيَجْزِىَ","Supaya Allah membalasnya"],["ٱللَّهُ","Supaya Allah membalasnya"],["كُلَّ","setiap satu"],["نَفْسٍۢ","jiwa"],["مَّا","(untuk) apa"],["كَسَبَتْ ۚ","ia diperolehi"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَرِيعُ","(ialah) Swift"],["ٱلْحِسَابِ","(dalam) hisab"]]],"1802":["(Ini) yakni Alquran ini (adalah penjelasan yang cukup bagi manusia) artinya diturunkan untuk disampaikan kepada mereka (dan supaya mereka diberi peringatan dengannya dan supaya mereka mengetahui) apa-apa yang terkandung di dalamnya berupa hujah-hujah (bahwasanya Dia) yakni Allah (adalah Tuhan Yang Maha Esa dan agar mau mengambil pelajaran) asalnya adalah liyatadzakkara, kemudian huruf ta diidgamkan kepada huruf dzal sehingga jadilah bacaannya liyadzdzakkara artinya, supaya mengambil pelajaran (orang-orang yang berakal) yang berakal sehat.",[["هَـٰذَا","Ini"],["بَلَـٰغٌۭ","(adalah) Mesej"],["لِّلنَّاسِ","untuk umat manusia"],["وَلِيُنذَرُوا۟","supaya mereka diberi amaran"],["بِهِۦ","dengannya"],["وَلِيَعْلَمُوٓا۟","dan supaya mereka mengetahui"],["أَنَّمَا","itu sahaja"],["هُوَ","Dia"],["إِلَـٰهٌۭ","(adalah) Tuhan yang Satu"],["وَٰحِدٌۭ","(adalah) Tuhan yang Satu"],["وَلِيَذَّكَّرَ","dan itu mungkin mengambil iktibar"],["أُو۟لُوا۟","lelaki"],["ٱلْأَلْبَـٰبِ","(dari) pemahaman"]]]});